    AllocateHostsRequest.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'InstanceType', traits: {"aws.protocols#ec2QueryName" => "InstanceType", "smithy.api#documentation" => "<p>Specifies the instance type to be supported by the Dedicated Hosts. If you specify an\n            instance type, the Dedicated Hosts support instances of the specified instance type\n            only.</p>\n         <p>If you want the Dedicated Hosts to support multiple instance types in a specific\n            instance family, omit this parameter and specify <b>InstanceFamily</b> instead. You cannot specify <b>InstanceType</b> and <b>InstanceFamily</b> in the\n            same request.</p>", "smithy.api#xmlName" => "instanceType"}))
