    CapacityReservation.add_member(:instance_platform, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationInstancePlatform, location_name: 'InstancePlatform', traits: {"aws.protocols#ec2QueryName" => "InstancePlatform", "smithy.api#documentation" => "<p>The type of operating system for which the Capacity Reservation reserves\n\t\t\tcapacity.</p>", "smithy.api#xmlName" => "instancePlatform"}))
