    CapacityReservation.add_member(:commitment_info, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationCommitmentInfo, location_name: 'CommitmentInfo', traits: {"aws.protocols#ec2QueryName" => "CommitmentInfo", "smithy.api#documentation" => "<p>Information about your commitment for a future-dated Capacity Reservation.</p>", "smithy.api#xmlName" => "commitmentInfo"}))
    CapacityReservation.add_member(:delivery_preference, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationDeliveryPreference, location_name: 'DeliveryPreference', traits: {"aws.protocols#ec2QueryName" => "DeliveryPreference", "smithy.api#documentation" => "<p>The delivery method for a future-dated Capacity Reservation. <code>incremental</code>\n\t\t\tindicates that the requested capacity is delivered in addition to any running instances\n\t\t\tand reserved capacity that you have in your account at the requested date and\n\t\t\ttime.</p>", "smithy.api#xmlName" => "deliveryPreference"}))
