    CapacityReservationBillingRequest.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationBillingRequestStatus, location_name: 'Status', traits: {"aws.protocols#ec2QueryName" => "Status", "smithy.api#documentation" => "<p>The status of the request. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/view-billing-transfers.html\"> View billing assignment\n\t\t\t\trequests for a shared Amazon EC2 Capacity Reservation</a>.</p>", "smithy.api#xmlName" => "status"}))
