    CapacityReservationFleet.add_member(:tenancy, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetCapacityReservationTenancy, location_name: 'Tenancy', traits: {"aws.protocols#ec2QueryName" => "Tenancy", "smithy.api#documentation" => "<p>The tenancy of the Capacity Reservation Fleet. Tenancies include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>default</code> - The Capacity Reservation Fleet is created on hardware\n\t\t\t\t\tthat is shared with other Amazon Web Services accounts.</p>\n            </li>\n            <li>\n               <p>\n                  <code>dedicated</code> - The Capacity Reservation Fleet is created on\n\t\t\t\t\tsingle-tenant hardware that is dedicated to a single Amazon Web Services account.</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "tenancy"}))
    CapacityReservationFleet.add_member(:end_date, Smithy::Schema::Shapes::ShapeRef.new(shape: MillisecondDateTime, location_name: 'EndDate', traits: {"aws.protocols#ec2QueryName" => "EndDate", "smithy.api#documentation" => "<p>The date and time at which the Capacity Reservation Fleet expires.</p>", "smithy.api#xmlName" => "endDate"}))
    CapacityReservationFleet.add_member(:create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: MillisecondDateTime, location_name: 'CreateTime', traits: {"aws.protocols#ec2QueryName" => "CreateTime", "smithy.api#documentation" => "<p>The date and time at which the Capacity Reservation Fleet was created.</p>", "smithy.api#xmlName" => "createTime"}))
    CapacityReservationFleet.add_member(:instance_match_criteria, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetInstanceMatchCriteria, location_name: 'InstanceMatchCriteria', traits: {"aws.protocols#ec2QueryName" => "InstanceMatchCriteria", "smithy.api#documentation" => "<p>Indicates the type of instance launches that the Capacity Reservation Fleet accepts.\n\t\t\tAll Capacity Reservations in the Fleet inherit this instance matching criteria.</p>\n         <p>Currently, Capacity Reservation Fleets support <code>open</code> instance matching\n\t\t\tcriteria only. This means that instances that have matching attributes (instance type,\n\t\t\tplatform, and Availability Zone) run in the Capacity Reservations automatically.\n\t\t\tInstances do not need to explicitly target a Capacity Reservation Fleet to use its\n\t\t\treserved capacity.</p>", "smithy.api#xmlName" => "instanceMatchCriteria"}))
    CapacityReservationFleet.add_member(:allocation_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AllocationStrategy', traits: {"aws.protocols#ec2QueryName" => "AllocationStrategy", "smithy.api#documentation" => "<p>The strategy used by the Capacity Reservation Fleet to determine which of the\n\t\t\tspecified instance types to use. For more information, see For more information, see\n\t\t\t\t<a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/crfleet-concepts.html#allocation-strategy\">Allocation\n\t\t\t\tstrategy</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "allocationStrategy"}))
