    CapacityReservationOptions.add_member(:usage_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetCapacityReservationUsageStrategy, location_name: 'UsageStrategy', traits: {"aws.protocols#ec2QueryName" => "UsageStrategy", "smithy.api#documentation" => "<p>Indicates whether to use unused Capacity Reservations for fulfilling On-Demand capacity.</p>\n         <p>If you specify <code>use-capacity-reservations-first</code>, the fleet uses unused\n         Capacity Reservations to fulfill On-Demand capacity up to the target On-Demand capacity. If\n         multiple instance pools have unused Capacity Reservations, the On-Demand allocation\n         strategy (<code>lowest-price</code> or <code>prioritized</code>) is applied. If the number\n         of unused Capacity Reservations is less than the On-Demand target capacity, the remaining\n         On-Demand target capacity is launched according to the On-Demand allocation strategy\n            (<code>lowest-price</code> or <code>prioritized</code>).</p>\n         <p>If you do not specify a value, the fleet fulfils the On-Demand capacity according to the\n         chosen On-Demand allocation strategy.</p>", "smithy.api#xmlName" => "usageStrategy"}))
    CapacityReservationOptions.type = Types::CapacityReservationOptions
    CapacityReservationOptionsRequest.add_member(:usage_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetCapacityReservationUsageStrategy, location_name: 'UsageStrategy', traits: {"smithy.api#documentation" => "<p>Indicates whether to use unused Capacity Reservations for fulfilling On-Demand capacity.</p>\n         <p>If you specify <code>use-capacity-reservations-first</code>, the fleet uses unused\n         Capacity Reservations to fulfill On-Demand capacity up to the target On-Demand capacity. If\n         multiple instance pools have unused Capacity Reservations, the On-Demand allocation\n         strategy (<code>lowest-price</code> or <code>prioritized</code>) is applied. If the number\n         of unused Capacity Reservations is less than the On-Demand target capacity, the remaining\n         On-Demand target capacity is launched according to the On-Demand allocation strategy\n            (<code>lowest-price</code> or <code>prioritized</code>).</p>\n         <p>If you do not specify a value, the fleet fulfils the On-Demand capacity according to the\n         chosen On-Demand allocation strategy.</p>"}))
    CapacityReservationOptionsRequest.type = Types::CapacityReservationOptionsRequest
    CapacityReservationPreference.add_member(:capacity_reservations_only, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'capacity_reservations_only', traits: {"smithy.api#enumValue" => "capacity-reservations-only"}))
    CapacityReservationPreference.add_member(:open, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'open', traits: {"smithy.api#enumValue" => "open"}))
    CapacityReservationPreference.add_member(:none, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'none', traits: {"smithy.api#enumValue" => "none"}))
    CapacityReservationSet.member = Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservation, traits: {"smithy.api#xmlName" => "item"})
    CapacityReservationSpecification.add_member(:capacity_reservation_preference, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationPreference, location_name: 'CapacityReservationPreference', traits: {"smithy.api#documentation" => "<p>Indicates the instance's Capacity Reservation preferences. Possible preferences\n\t\t\tinclude:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>capacity-reservations-only</code> - The instance will only run in a\n\t\t\t\t\tCapacity Reservation or Capacity Reservation group. If capacity isn't available,\n\t\t\t\t\tthe instance will fail to launch.</p>\n            </li>\n            <li>\n               <p>\n                  <code>open</code> - The instance can run in any <code>open</code> Capacity\n\t\t\t\t\tReservation that has matching attributes (instance type, platform, Availability\n\t\t\t\t\tZone, and tenancy). If capacity isn't available, the instance runs as an\n\t\t\t\t\tOn-Demand Instance.</p>\n            </li>\n            <li>\n               <p>\n                  <code>none</code> - The instance doesn't run in a Capacity Reservation even if\n\t\t\t\t\tone is available. The instance runs as an On-Demand Instance.</p>\n            </li>\n         </ul>"}))
    CapacityReservationSpecification.add_member(:capacity_reservation_target, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationTarget, location_name: 'CapacityReservationTarget', traits: {"smithy.api#documentation" => "<p>Information about the target Capacity Reservation or Capacity Reservation\n\t\t\tgroup.</p>"}))
    CapacityReservationSpecification.type = Types::CapacityReservationSpecification
    CapacityReservationSpecificationResponse.add_member(:capacity_reservation_preference, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationPreference, location_name: 'CapacityReservationPreference', traits: {"aws.protocols#ec2QueryName" => "CapacityReservationPreference", "smithy.api#documentation" => "<p>Describes the instance's Capacity Reservation preferences. Possible preferences include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>open</code> - The instance can run in any <code>open</code> Capacity Reservation that\n                    has matching attributes (instance type, platform, Availability Zone).</p>\n            </li>\n            <li>\n               <p>\n                  <code>none</code> - The instance avoids running in a Capacity Reservation even if one is\n                    available. The instance runs in On-Demand capacity.</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "capacityReservationPreference"}))
