    CopyImageRequest.add_member(:encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'Encrypted', traits: {"aws.protocols#ec2QueryName" => "Encrypted", "smithy.api#documentation" => "<p>Specifies whether the destination snapshots of the copied image should be encrypted. You\n      can encrypt a copy of an unencrypted snapshot, but you cannot create an unencrypted copy of an\n      encrypted snapshot. The default KMS key for Amazon EBS is used unless you specify a non-default\n      Key Management Service (KMS) KMS key using <code>KmsKeyId</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/AMIEncryption.html\">Use encryption with\n        EBS-backed AMIs</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "encrypted"}))
    CopyImageRequest.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyId, location_name: 'KmsKeyId', traits: {"aws.protocols#ec2QueryName" => "KmsKeyId", "smithy.api#documentation" => "<p>The identifier of the symmetric Key Management Service (KMS) KMS key to use when creating encrypted volumes.\n      If this parameter is not specified, your Amazon Web Services managed KMS key for Amazon EBS is used. If you\n      specify a KMS key, you must also set the encrypted state to <code>true</code>.</p>\n         <p>You can specify a KMS key using any of the following:</p>\n         <ul>\n            <li>\n               <p>Key ID. For example, 1234abcd-12ab-34cd-56ef-1234567890ab.</p>\n            </li>\n            <li>\n               <p>Key alias. For example, alias/ExampleAlias.</p>\n            </li>\n            <li>\n               <p>Key ARN. For example, arn:aws:kms:us-east-1:012345678910:key/1234abcd-12ab-34cd-56ef-1234567890ab.</p>\n            </li>\n            <li>\n               <p>Alias ARN. For example, arn:aws:kms:us-east-1:012345678910:alias/ExampleAlias.</p>\n            </li>\n         </ul>\n         <p>Amazon Web Services authenticates the KMS key asynchronously. Therefore, if you specify an identifier\n      that is not valid, the action can appear to complete, but eventually fails.</p>\n         <p>The specified KMS key must exist in the destination Region.</p>\n         <p>Amazon EBS does not support asymmetric KMS keys.</p>", "smithy.api#xmlName" => "kmsKeyId"}))
    CopyImageRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the new AMI in the destination Region.</p>", "smithy.api#required" => {}}))
    CopyImageRequest.add_member(:source_image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceImageId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the AMI to copy.</p>", "smithy.api#required" => {}}))
    CopyImageRequest.add_member(:source_region, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceRegion', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Region that contains the AMI to copy.</p>", "smithy.api#required" => {}}))
    CopyImageRequest.add_member(:destination_outpost_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DestinationOutpostArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Outpost to which to copy the AMI. Only specify this\n      parameter when copying an AMI from an Amazon Web Services Region to an Outpost. The AMI must be in the\n      Region of the destination Outpost. You cannot copy an AMI from an Outpost to a Region, from\n      one Outpost to another, or within the same Outpost.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/snapshots-outposts.html#copy-amis\">Copy AMIs from an Amazon Web Services Region\n        to an Outpost</a> in the <i>Amazon EBS User Guide</i>.</p>"}))
    CopyImageRequest.add_member(:copy_image_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'CopyImageTags', traits: {"smithy.api#documentation" => "<p>Indicates whether to include your user-defined AMI tags when copying the AMI.</p>\n         <p>The following tags will not be copied:</p>\n         <ul>\n            <li>\n               <p>System tags (prefixed with <code>aws:</code>)</p>\n            </li>\n            <li>\n               <p>For public and shared AMIs, user-defined tags that are attached by other Amazon Web Services\n          accounts</p>\n            </li>\n         </ul>\n         <p>Default: Your user-defined AMI tags are not copied.</p>"}))
    CopyImageRequest.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: TagSpecificationList, location_name: 'TagSpecifications', traits: {"smithy.api#documentation" => "<p>The tags to apply to the new AMI and new snapshots. You can tag the AMI, the snapshots, or\n      both.</p>\n         <ul>\n            <li>\n               <p>To tag the new AMI, the value for <code>ResourceType</code> must be\n          <code>image</code>.</p>\n            </li>\n            <li>\n               <p>To tag the new snapshots, the value for <code>ResourceType</code> must be\n            <code>snapshot</code>. The same tag is applied to all the new snapshots.</p>\n            </li>\n         </ul>\n         <p>If you specify other values for <code>ResourceType</code>, the request fails.</p>\n         <p>To tag an AMI or snapshot after it has been created, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateTags.html\">CreateTags</a>.</p>", "smithy.api#xmlName" => "TagSpecification"}))
    CopyImageRequest.add_member(:snapshot_copy_completion_duration_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'SnapshotCopyCompletionDurationMinutes', traits: {"smithy.api#documentation" => "<p>Specify a completion duration, in 15 minute increments, to initiate a time-based AMI copy.\n      The specified completion duration applies to each of the snapshots associated with the AMI.\n      Each snapshot associated with the AMI will be completed within the specified completion\n      duration, with copy throughput automatically adjusted for each snapshot based on its size to\n      meet the timing target.</p>\n         <p>If you do not specify a value, the AMI copy operation is completed on a best-effort \n      basis.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/time-based-copies.html\">Time-based copies for Amazon EBS snapshots and\n        EBS-backed AMIs</a>.</p>"}))
    CopyImageRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"aws.protocols#ec2QueryName" => "DryRun", "smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually making the request, \n\t\t\tand provides an error response. If you have the required permissions, the error response is \n\t\t\t<code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.</p>", "smithy.api#xmlName" => "dryRun"}))
    CopyImageRequest.type = Types::CopyImageRequest
    CopyImageResult.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ImageId', traits: {"aws.protocols#ec2QueryName" => "ImageId", "smithy.api#documentation" => "<p>The ID of the new AMI.</p>", "smithy.api#xmlName" => "imageId"}))
