    CopySnapshotRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description for the EBS snapshot.</p>"}))
    CopySnapshotRequest.add_member(:destination_outpost_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DestinationOutpostArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Outpost to which to copy the snapshot. Only \n\t\tspecify this parameter when copying a snapshot from an Amazon Web Services Region to an Outpost. \n\t\tThe snapshot must be in the Region for the destination Outpost. You cannot copy a \n\t\tsnapshot from an Outpost to a Region, from one Outpost to another, or within the same \n\t\tOutpost.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/snapshots-outposts.html#copy-snapshots\">\n  \t\tCopy snapshots from an Amazon Web Services Region to an Outpost</a> in the \n  \t\t<i>Amazon EBS User Guide</i>.</p>"}))
    CopySnapshotRequest.add_member(:destination_region, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DestinationRegion', traits: {"aws.protocols#ec2QueryName" => "DestinationRegion", "smithy.api#documentation" => "<p>The destination Region to use in the <code>PresignedUrl</code> parameter of a snapshot\n      copy operation. This parameter is only valid for specifying the destination Region in a\n        <code>PresignedUrl</code> parameter, where it is required.</p>\n         <p>The snapshot copy is sent to the regional endpoint that you sent the HTTP\n    \trequest to (for example, <code>ec2.us-east-1.amazonaws.com</code>). With the CLI, this is\n      specified using the <code>--region</code> parameter or the default Region in your Amazon Web Services\n      configuration file.</p>", "smithy.api#xmlName" => "destinationRegion"}))
    CopySnapshotRequest.add_member(:encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'Encrypted', traits: {"aws.protocols#ec2QueryName" => "Encrypted", "smithy.api#documentation" => "<p>To encrypt a copy of an unencrypted snapshot if encryption by default is not enabled, \n      enable encryption using this parameter. Otherwise, omit this parameter. Encrypted snapshots \n      are encrypted, even if you omit this parameter and encryption by default is not enabled. You \n      cannot set this parameter to false. For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/ebs-encryption.html\">Amazon EBS encryption</a> in the \n      <i>Amazon EBS User Guide</i>.</p>", "smithy.api#xmlName" => "encrypted"}))
    CopySnapshotRequest.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyId, location_name: 'KmsKeyId', traits: {"aws.protocols#ec2QueryName" => "KmsKeyId", "smithy.api#documentation" => "<p>The identifier of the KMS key to use for Amazon EBS encryption.\n      If this parameter is not specified, your KMS key for Amazon EBS is used. If <code>KmsKeyId</code> is\n      specified, the encrypted state must be <code>true</code>.</p>\n         <p>You can specify the KMS key using any of the following:</p>\n         <ul>\n            <li>\n               <p>Key ID. For example, 1234abcd-12ab-34cd-56ef-1234567890ab.</p>\n            </li>\n            <li>\n               <p>Key alias. For example, alias/ExampleAlias.</p>\n            </li>\n            <li>\n               <p>Key ARN. For example, arn:aws:kms:us-east-1:012345678910:key/1234abcd-12ab-34cd-56ef-1234567890ab.</p>\n            </li>\n            <li>\n               <p>Alias ARN. For example, arn:aws:kms:us-east-1:012345678910:alias/ExampleAlias.</p>\n            </li>\n         </ul>\n         <p>Amazon Web Services authenticates the KMS key asynchronously. Therefore, if you specify an ID, alias, or ARN that is not valid, \n      the action can appear to complete, but eventually fails.</p>", "smithy.api#xmlName" => "kmsKeyId"}))
    CopySnapshotRequest.add_member(:presigned_url, Smithy::Schema::Shapes::ShapeRef.new(shape: CopySnapshotRequestPSU, location_name: 'PresignedUrl', traits: {"aws.protocols#ec2QueryName" => "PresignedUrl", "smithy.api#documentation" => "<p>When you copy an encrypted source snapshot using the Amazon EC2 Query API, you must supply a\n      pre-signed URL. This parameter is optional for unencrypted snapshots. For more information,\n      see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/Query-Requests.html\">Query\n        requests</a>.</p>\n         <p>The <code>PresignedUrl</code> should use the snapshot source endpoint, the\n        <code>CopySnapshot</code> action, and include the <code>SourceRegion</code>,\n        <code>SourceSnapshotId</code>, and <code>DestinationRegion</code> parameters. The\n        <code>PresignedUrl</code> must be signed using Amazon Web Services Signature Version 4. Because EBS\n      snapshots are stored in Amazon S3, the signing algorithm for this parameter uses the same logic\n      that is described in <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/API/sigv4-query-string-auth.html\">\n        Authenticating Requests: Using Query Parameters (Amazon Web Services Signature Version 4)</a> in the <i>Amazon S3 API Reference</i>. An\n      invalid or improperly signed <code>PresignedUrl</code> will cause the copy operation to fail\n      asynchronously, and the snapshot will move to an <code>error</code> state.</p>", "smithy.api#xmlName" => "presignedUrl"}))
    CopySnapshotRequest.add_member(:source_region, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceRegion', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the Region that contains the snapshot to be copied.</p>", "smithy.api#required" => {}}))
    CopySnapshotRequest.add_member(:source_snapshot_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceSnapshotId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the EBS snapshot to copy.</p>", "smithy.api#required" => {}}))
    CopySnapshotRequest.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: TagSpecificationList, location_name: 'TagSpecifications', traits: {"smithy.api#documentation" => "<p>The tags to apply to the new snapshot.</p>", "smithy.api#xmlName" => "TagSpecification"}))
    CopySnapshotRequest.add_member(:completion_duration_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotCompletionDurationMinutesRequest, location_name: 'CompletionDurationMinutes', traits: {"smithy.api#documentation" => "<p>Specify a completion duration, in 15 minute increments, to initiate a time-based snapshot \n      copy. Time-based snapshot copy operations complete within the specified duration. For more \n      information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/time-based-copies.html\">\n        Time-based copies</a>.</p>\n         <p>If you do not specify a value, the snapshot copy operation is completed on a \n      best-effort basis.</p>"}))
    CopySnapshotRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"aws.protocols#ec2QueryName" => "DryRun", "smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually making the request, \n   and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. \n   Otherwise, it is <code>UnauthorizedOperation</code>.</p>", "smithy.api#xmlName" => "dryRun"}))
