    CpuOptionsRequest.add_member(:core_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'CoreCount', traits: {"smithy.api#documentation" => "<p>The number of CPU cores for the instance.</p>"}))
    CpuOptionsRequest.add_member(:threads_per_core, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ThreadsPerCore', traits: {"smithy.api#documentation" => "<p>The number of threads per CPU core. To disable multithreading for the instance,\n            specify a value of <code>1</code>. Otherwise, specify the default value of\n                <code>2</code>.</p>"}))
    CpuOptionsRequest.add_member(:amd_sev_snp, Smithy::Schema::Shapes::ShapeRef.new(shape: AmdSevSnpSpecification, location_name: 'AmdSevSnp', traits: {"smithy.api#documentation" => "<p>Indicates whether to enable the instance for AMD SEV-SNP. AMD SEV-SNP is supported \n            with M6a, R6a, and C6a instance types only. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/sev-snp.html\">AMD SEV-SNP</a>.</p>"}))
    CpuOptionsRequest.type = Types::CpuOptionsRequest
    CpuPerformanceFactor.add_member(:references, Smithy::Schema::Shapes::ShapeRef.new(shape: PerformanceFactorReferenceSet, location_name: 'References', traits: {"aws.protocols#ec2QueryName" => "ReferenceSet", "smithy.api#documentation" => "<p>Specify an instance family to use as the baseline reference for CPU performance. All\n         instance types that match your specified attributes will be compared against the CPU\n         performance of the referenced instance family, regardless of CPU manufacturer or\n         architecture differences.</p>\n         <note>\n            <p>Currently, only one instance family can be specified in the list.</p>\n         </note>", "smithy.api#xmlName" => "referenceSet"}))
