    CreateClientVpnEndpointRequest.add_member(:client_cidr_block, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ClientCidrBlock', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The IPv4 address range, in CIDR notation, from which to assign client IP addresses. The address range cannot overlap with the local CIDR of the VPC in which the associated subnet is located, or the routes that you add manually. The address range cannot be changed after the Client VPN endpoint has been created. Client CIDR range must have a size of at least /22 and must not be greater than /12.</p>", "smithy.api#required" => {}}))
    CreateClientVpnEndpointRequest.add_member(:server_certificate_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ServerCertificateArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ARN of the server certificate. For more information, see \n\t\t\tthe <a href=\"https://docs.aws.amazon.com/acm/latest/userguide/\">Certificate Manager User Guide</a>.</p>", "smithy.api#required" => {}}))
    CreateClientVpnEndpointRequest.add_member(:authentication_options, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientVpnAuthenticationRequestList, location_name: 'AuthenticationOptions', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Information about the authentication method to be used to authenticate clients.</p>", "smithy.api#required" => {}, "smithy.api#xmlName" => "Authentication"}))
    CreateClientVpnEndpointRequest.add_member(:connection_log_options, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectionLogOptions, location_name: 'ConnectionLogOptions', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Information about the client connection logging options.</p>\n         <p>If you enable client connection logging, data about client connections is sent to a\n\t\t\tCloudwatch Logs log stream. The following information is logged:</p>\n         <ul>\n            <li>\n               <p>Client connection requests</p>\n            </li>\n            <li>\n               <p>Client connection results (successful and unsuccessful)</p>\n            </li>\n            <li>\n               <p>Reasons for unsuccessful client connection requests</p>\n            </li>\n            <li>\n               <p>Client connection termination time</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateClientVpnEndpointRequest.add_member(:dns_servers, Smithy::Schema::Shapes::ShapeRef.new(shape: ValueStringList, location_name: 'DnsServers', traits: {"smithy.api#documentation" => "<p>Information about the DNS servers to be used for DNS resolution. A Client VPN endpoint can\n\t\t\thave up to two DNS servers. If no DNS server is specified, the DNS address configured on the device is used for the DNS server.</p>"}))
    CreateClientVpnEndpointRequest.add_member(:transport_protocol, Smithy::Schema::Shapes::ShapeRef.new(shape: TransportProtocol, location_name: 'TransportProtocol', traits: {"smithy.api#documentation" => "<p>The transport protocol to be used by the VPN session.</p>\n         <p>Default value: <code>udp</code>\n         </p>"}))
    CreateClientVpnEndpointRequest.add_member(:vpn_port, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'VpnPort', traits: {"smithy.api#documentation" => "<p>The port number to assign to the Client VPN endpoint for TCP and UDP traffic.</p>\n         <p>Valid Values: <code>443</code> | <code>1194</code>\n         </p>\n         <p>Default Value: <code>443</code>\n         </p>"}))
