    CreateFleetRequest.add_member(:launch_template_configs, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetLaunchTemplateConfigListRequest, location_name: 'LaunchTemplateConfigs', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The configuration for the EC2 Fleet.</p>", "smithy.api#required" => {}}))
    CreateFleetRequest.add_member(:target_capacity_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetCapacitySpecificationRequest, location_name: 'TargetCapacitySpecification', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The number of units to request.</p>", "smithy.api#required" => {}}))
    CreateFleetRequest.add_member(:terminate_instances_with_expiration, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'TerminateInstancesWithExpiration', traits: {"smithy.api#documentation" => "<p>Indicates whether running instances should be terminated when the EC2 Fleet expires.</p>"}))
    CreateFleetRequest.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetType, location_name: 'Type', traits: {"smithy.api#documentation" => "<p>The fleet type. The default value is <code>maintain</code>.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>maintain</code> - The EC2 Fleet places an asynchronous request for your desired\n               capacity, and continues to maintain your desired Spot capacity by replenishing\n               interrupted Spot Instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>request</code> - The EC2 Fleet places an asynchronous one-time request for your\n               desired capacity, but does submit Spot requests in alternative capacity pools if Spot\n               capacity is unavailable, and does not maintain Spot capacity if Spot Instances are\n               interrupted.</p>\n            </li>\n            <li>\n               <p>\n                  <code>instant</code> - The EC2 Fleet places a synchronous one-time request for your\n               desired capacity, and returns errors for any instances that could not be\n               launched.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-fleet-request-type.html\">EC2 Fleet\n            request types</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    CreateFleetRequest.add_member(:valid_from, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'ValidFrom', traits: {"smithy.api#documentation" => "<p>The start date and time of the request, in UTC format (for example,\n            <i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).\n         The default is to start fulfilling the request immediately.</p>"}))
    CreateFleetRequest.add_member(:valid_until, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'ValidUntil', traits: {"smithy.api#documentation" => "<p>The end date and time of the request, in UTC format (for example,\n            <i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).\n         At this point, no new EC2 Fleet requests are placed or able to fulfill the request. If no value is specified, the request remains until you cancel it.</p>"}))
    CreateFleetRequest.add_member(:replace_unhealthy_instances, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ReplaceUnhealthyInstances', traits: {"smithy.api#documentation" => "<p>Indicates whether EC2 Fleet should replace unhealthy Spot Instances. Supported only for\n         fleets of type <code>maintain</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/manage-ec2-fleet.html#ec2-fleet-health-checks\">EC2 Fleet\n            health checks</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    CreateFleetRequest.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: TagSpecificationList, location_name: 'TagSpecifications', traits: {"smithy.api#documentation" => "<p>The key-value pair for tagging the EC2 Fleet request on creation. For more information, see \n         <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/Using_Tags.html#tag-resources\">Tag your resources</a>.</p>\n         <p>If the fleet type is <code>instant</code>, specify a resource type of <code>fleet</code> \n         to tag the fleet or <code>instance</code> to tag the instances at launch.</p>\n         <p>If the fleet type is <code>maintain</code> or <code>request</code>, specify a resource\n         type of <code>fleet</code> to tag the fleet. You cannot specify a resource type of\n            <code>instance</code>. To tag instances at launch, specify the tags in a <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-launch-templates.html#create-launch-template\">launch template</a>.</p>", "smithy.api#xmlName" => "TagSpecification"}))
    CreateFleetRequest.add_member(:context, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Context', traits: {"smithy.api#documentation" => "<p>Reserved.</p>"}))
