    CreateFleetResult.add_member(:errors, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateFleetErrorsSet, location_name: 'Errors', traits: {"aws.protocols#ec2QueryName" => "ErrorSet", "smithy.api#documentation" => "<p>Information about the instances that could not be launched by the fleet. Supported only for\n            fleets of type <code>instant</code>.</p>", "smithy.api#xmlName" => "errorSet"}))
