    CreateFlowLogsRequest.add_member(:deliver_logs_permission_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DeliverLogsPermissionArn', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role that allows Amazon EC2 to publish flow logs to the log destination.</p>\n         <p>This parameter is required if the destination type is <code>cloud-watch-logs</code>,\n            or if the destination type is <code>kinesis-data-firehose</code> and the delivery stream\n            and the resources to monitor are in different accounts.</p>"}))
