    CreateFlowLogsRequest.add_member(:log_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LogGroupName', traits: {"smithy.api#documentation" => "<p>The name of a new or existing CloudWatch Logs log group where Amazon EC2 publishes your flow logs.</p>\n         <p>This parameter is valid only if the destination type is <code>cloud-watch-logs</code>.</p>"}))
    CreateFlowLogsRequest.add_member(:resource_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: FlowLogResourceIds, location_name: 'ResourceIds', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The IDs of the resources to monitor. For example, if the resource type is\n                <code>VPC</code>, specify the IDs of the VPCs.</p>\n         <p>Constraints: Maximum of 25 for transit gateway resource types. Maximum of 1000 for the\n            other resource types.</p>", "smithy.api#required" => {}, "smithy.api#xmlName" => "ResourceId"}))
    CreateFlowLogsRequest.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: FlowLogsResourceType, location_name: 'ResourceType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The type of resource to monitor.</p>", "smithy.api#required" => {}}))
    CreateFlowLogsRequest.add_member(:traffic_type, Smithy::Schema::Shapes::ShapeRef.new(shape: TrafficType, location_name: 'TrafficType', traits: {"smithy.api#documentation" => "<p>The type of traffic to monitor (accepted traffic, rejected traffic, or all traffic).\n            This parameter is not supported for transit gateway resource types. It is required for\n            the other resource types.</p>"}))
    CreateFlowLogsRequest.add_member(:log_destination_type, Smithy::Schema::Shapes::ShapeRef.new(shape: LogDestinationType, location_name: 'LogDestinationType', traits: {"smithy.api#documentation" => "<p>The type of destination for the flow log data.</p>\n         <p>Default: <code>cloud-watch-logs</code>\n         </p>"}))
    CreateFlowLogsRequest.add_member(:log_destination, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LogDestination', traits: {"smithy.api#documentation" => "<p>The destination for the flow log data. The meaning of this parameter depends on the destination type.</p>\n         <ul>\n            <li>\n               <p>If the destination type is <code>cloud-watch-logs</code>, specify the ARN of a CloudWatch Logs log group. For example:</p>\n               <p>arn:aws:logs:<i>region</i>:<i>account_id</i>:log-group:<i>my_group</i>\n               </p>\n               <p>Alternatively, use the <code>LogGroupName</code> parameter.</p>\n            </li>\n            <li>\n               <p>If the destination type is <code>s3</code>, specify the ARN of an S3 bucket. For example:</p>\n               <p>arn:aws:s3:::<i>my_bucket</i>/<i>my_subfolder</i>/</p>\n               <p>The subfolder is optional. Note that you can't use <code>AWSLogs</code> as a subfolder name.</p>\n            </li>\n            <li>\n               <p>If the destination type is <code>kinesis-data-firehose</code>, specify the ARN of a Kinesis Data Firehose delivery stream. For example:</p>\n               <p>arn:aws:firehose:<i>region</i>:<i>account_id</i>:deliverystream:<i>my_stream</i>\n               </p>\n            </li>\n         </ul>"}))
    CreateFlowLogsRequest.add_member(:log_format, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LogFormat', traits: {"smithy.api#documentation" => "<p>The fields to include in the flow log record. List the fields in the order in which\n            they should appear. If you omit this parameter, the flow log is created using the\n            default format. If you specify this parameter, you must include at least one\n            field. For more information about the available fields, see <a href=\"https://docs.aws.amazon.com/vpc/latest/userguide/flow-log-records.html\">Flow log records</a> \n            in the <i>Amazon VPC User Guide</i> or <a href=\"https://docs.aws.amazon.com/vpc/latest/tgw/tgw-flow-logs.html#flow-log-records\">Transit Gateway Flow Log\n                    records</a> in the <i>Amazon Web Services Transit Gateway Guide</i>.</p>\n         <p>Specify the fields using the <code>${field-id}</code> format, separated by spaces.</p>"}))
    CreateFlowLogsRequest.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: TagSpecificationList, location_name: 'TagSpecifications', traits: {"smithy.api#documentation" => "<p>The tags to apply to the flow logs.</p>", "smithy.api#xmlName" => "TagSpecification"}))
    CreateFlowLogsRequest.add_member(:max_aggregation_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'MaxAggregationInterval', traits: {"smithy.api#documentation" => "<p>The maximum interval of time during which a flow of packets is captured and aggregated into a flow log record. \n            The possible values are 60 seconds (1 minute) or 600 seconds (10 minutes).\n            This parameter must be 60 seconds for transit gateway resource types.</p>\n         <p>When a network interface is attached to a <a href=\"https://docs.aws.amazon.com/ec2/latest/instancetypes/ec2-nitro-instances.html\">Nitro-based\n                instance</a>, the aggregation interval is always 60 seconds or less, regardless\n            of the value that you specify.</p>\n         <p>Default: 600</p>"}))
    CreateFlowLogsRequest.add_member(:destination_options, Smithy::Schema::Shapes::ShapeRef.new(shape: DestinationOptionsRequest, location_name: 'DestinationOptions', traits: {"smithy.api#documentation" => "<p>The destination options.</p>"}))
