    CreateInstanceConnectEndpointRequest.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIdStringListRequest, location_name: 'SecurityGroupIds', traits: {"smithy.api#documentation" => "<p>One or more security groups to associate with the endpoint. If you don't specify a security group, \n            the default security group for your VPC will be associated with the endpoint.</p>", "smithy.api#xmlName" => "SecurityGroupId"}))
    CreateInstanceConnectEndpointRequest.add_member(:preserve_client_ip, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'PreserveClientIp', traits: {"smithy.api#documentation" => "<p>Indicates whether the client IP address is preserved as the source. The following are the possible values.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>true</code> - Use the client IP address as the source.</p>\n            </li>\n            <li>\n               <p>\n                  <code>false</code> - Use the network interface IP address as the source.</p>\n            </li>\n         </ul>\n         <note>\n            <p>\n               <code>PreserveClientIp</code> is only supported on IPv4 EC2 Instance Connect\n                Endpoints. To use <code>PreserveClientIp</code>, the value for\n                    <code>IpAddressType</code> must be <code>ipv4</code>.</p>\n         </note>\n         <p>Default: <code>false</code>\n         </p>"}))
    CreateInstanceConnectEndpointRequest.add_member(:client_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ClientToken', traits: {"smithy.api#documentation" => "<p>Unique, case-sensitive identifier that you provide to ensure the idempotency of the request.</p>", "smithy.api#idempotencyToken" => {}}))
    CreateInstanceConnectEndpointRequest.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: TagSpecificationList, location_name: 'TagSpecifications', traits: {"smithy.api#documentation" => "<p>The tags to apply to the EC2 Instance Connect Endpoint during creation.</p>", "smithy.api#xmlName" => "TagSpecification"}))
    CreateInstanceConnectEndpointRequest.add_member(:ip_address_type, Smithy::Schema::Shapes::ShapeRef.new(shape: IpAddressType, location_name: 'IpAddressType', traits: {"smithy.api#documentation" => "<p>The IP address type of the endpoint.</p>\n         <p>If no value is specified, the default value is determined by the IP address type of\n            the subnet:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>dualstack</code> - If the subnet has both IPv4 and IPv6 CIDRs</p>\n            </li>\n            <li>\n               <p>\n                  <code>ipv4</code> - If the subnet has only IPv4 CIDRs</p>\n            </li>\n            <li>\n               <p>\n                  <code>ipv6</code> - If the subnet has only IPv6 CIDRs</p>\n            </li>\n         </ul>\n         <note>\n            <p>\n               <code>PreserveClientIp</code> is only supported on IPv4 EC2 Instance Connect\n                Endpoints. To use <code>PreserveClientIp</code>, the value for\n                <code>IpAddressType</code> must be <code>ipv4</code>.</p>\n         </note>"}))
