    CreateInstanceEventWindowRequest.add_member(:time_ranges, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceEventWindowTimeRangeRequestSet, location_name: 'TimeRanges', traits: {"smithy.api#documentation" => "<p>The time range for the event window. If you specify a time range, you can't specify a\n         cron expression.</p>", "smithy.api#xmlName" => "TimeRange"}))
    CreateInstanceEventWindowRequest.add_member(:cron_expression, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceEventWindowCronExpression, location_name: 'CronExpression', traits: {"smithy.api#documentation" => "<p>The cron expression for the event window, for example, <code>* 0-4,20-23 * * 1,5</code>.\n         If you specify a cron expression, you can't specify a time range.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Only hour and day of the week values are supported.</p>\n            </li>\n            <li>\n               <p>For day of the week values, you can specify either integers <code>0</code> through\n                  <code>6</code>, or alternative single values <code>SUN</code> through\n                  <code>SAT</code>.</p>\n            </li>\n            <li>\n               <p>The minute, month, and year must be specified by <code>*</code>.</p>\n            </li>\n            <li>\n               <p>The hour value must be one or a multiple range, for example, <code>0-4</code> or\n                  <code>0-4,20-23</code>.</p>\n            </li>\n            <li>\n               <p>Each hour range must be >= 2 hours, for example, <code>0-2</code> or\n                  <code>20-23</code>.</p>\n            </li>\n            <li>\n               <p>The event window must be >= 4 hours. The combined total time ranges in the event\n               window must be >= 4 hours.</p>\n            </li>\n         </ul>\n         <p>For more information about cron expressions, see <a href=\"https://en.wikipedia.org/wiki/Cron\">cron</a> on the <i>Wikipedia\n            website</i>.</p>"}))
    CreateInstanceEventWindowRequest.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: TagSpecificationList, location_name: 'TagSpecifications', traits: {"smithy.api#documentation" => "<p>The tags to apply to the event window.</p>", "smithy.api#xmlName" => "TagSpecification"}))
