    CreateIpamPoolRequest.add_member(:ipam_scope_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamScopeId, location_name: 'IpamScopeId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the scope in which you would like to create the IPAM pool.</p>", "smithy.api#required" => {}}))
    CreateIpamPoolRequest.add_member(:locale, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Locale', traits: {"smithy.api#documentation" => "<p>The locale for the pool should be one of the following:</p>\n         <ul>\n            <li>\n               <p>An Amazon Web Services Region where you want this IPAM pool to be available for allocations.</p>\n            </li>\n            <li>\n               <p>The network border group for an Amazon Web Services Local Zone where you want this IPAM pool to be available for allocations (<a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-byoip.html#byoip-zone-avail\">supported Local Zones</a>). This option is only available for IPAM IPv4 pools in the public scope.</p>\n            </li>\n         </ul>\n         <p>Possible values: Any Amazon Web Services Region or supported Amazon Web Services Local Zone. Default is <code>none</code> and means any locale.</p>"}))
    CreateIpamPoolRequest.add_member(:source_ipam_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamPoolId, location_name: 'SourceIpamPoolId', traits: {"smithy.api#documentation" => "<p>The ID of the source IPAM pool. Use this option to create a pool within an existing pool. Note that the CIDR you provision for the pool within the source pool must be available in the source pool's CIDR range.</p>"}))
    CreateIpamPoolRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description for the IPAM pool.</p>"}))
    CreateIpamPoolRequest.add_member(:address_family, Smithy::Schema::Shapes::ShapeRef.new(shape: AddressFamily, location_name: 'AddressFamily', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The IP protocol assigned to this IPAM pool. You must choose either IPv4 or IPv6 protocol for a pool.</p>", "smithy.api#required" => {}}))
    CreateIpamPoolRequest.add_member(:auto_import, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AutoImport', traits: {"smithy.api#documentation" => "<p>If selected, IPAM will continuously look for resources within the CIDR range of this pool \n         and automatically import them as allocations into your IPAM. The CIDRs that will be allocated for\n         these resources must not already be allocated to other resources in order for the import to succeed. IPAM will import \n         a CIDR regardless of its compliance with the pool's allocation rules, so a resource might be imported and subsequently \n         marked as noncompliant. If IPAM discovers multiple CIDRs that overlap, IPAM will import the largest CIDR only. If IPAM \n         discovers multiple CIDRs with matching CIDRs, IPAM will randomly import one of them only.\n      </p>\n         <p>A locale must be set on the pool for this feature to work.</p>"}))
    CreateIpamPoolRequest.add_member(:publicly_advertisable, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'PubliclyAdvertisable', traits: {"smithy.api#documentation" => "<p>Determines if the pool is publicly advertisable. The request can only contain <code>PubliclyAdvertisable</code> if <code>AddressFamily</code> is <code>ipv6</code> and <code>PublicIpSource</code> is <code>byoip</code>.</p>"}))
    CreateIpamPoolRequest.add_member(:allocation_min_netmask_length, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamNetmaskLength, location_name: 'AllocationMinNetmaskLength', traits: {"smithy.api#documentation" => "<p>The minimum netmask length required for CIDR allocations in this IPAM pool to be compliant. The minimum netmask length must be \n         less than the maximum netmask length. Possible netmask lengths for IPv4 addresses are 0 - 32. Possible netmask lengths for IPv6 addresses are  0 - 128.</p>"}))
    CreateIpamPoolRequest.add_member(:allocation_max_netmask_length, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamNetmaskLength, location_name: 'AllocationMaxNetmaskLength', traits: {"smithy.api#documentation" => "<p>The maximum netmask length possible for CIDR allocations in this IPAM pool to be compliant. The maximum netmask length must be \n         greater than the minimum netmask length. Possible netmask lengths for IPv4 addresses are 0 - 32. Possible netmask lengths for IPv6 addresses are  0 - 128.</p>"}))
    CreateIpamPoolRequest.add_member(:allocation_default_netmask_length, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamNetmaskLength, location_name: 'AllocationDefaultNetmaskLength', traits: {"smithy.api#documentation" => "<p>The default netmask length for allocations added to this pool. If, for example, the CIDR assigned to this pool is 10.0.0.0/8 and you enter 16 here, \n         new allocations will default to 10.0.0.0/16.</p>"}))
    CreateIpamPoolRequest.add_member(:allocation_resource_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: RequestIpamResourceTagList, location_name: 'AllocationResourceTags', traits: {"smithy.api#documentation" => "<p>Tags that are required for resources that use CIDRs from this IPAM pool. Resources that do not have these tags will not be allowed to allocate space from the pool. If the resources have their tags changed after they have allocated space or if the allocation tagging requirements are changed on the pool, the resource may be marked as noncompliant.</p>", "smithy.api#xmlName" => "AllocationResourceTag"}))
