    CreateMacSystemIntegrityProtectionModificationTaskRequest.add_member(:mac_system_integrity_protection_status, Smithy::Schema::Shapes::ShapeRef.new(shape: MacSystemIntegrityProtectionSettingStatus, location_name: 'MacSystemIntegrityProtectionStatus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the overall SIP status for the instance. To enable all SIP settings, specify \n         <code>enabled</code>. To disable all SIP settings, specify <code>disabled</code>.</p>", "smithy.api#required" => {}}))
