    DescribeAvailabilityZonesRequest.add_member(:all_availability_zones, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AllAvailabilityZones', traits: {"smithy.api#documentation" => "<p>Include all Availability Zones, Local Zones, and Wavelength Zones regardless of your\n      opt-in status.</p>\n         <p>If you do not use this parameter, the results include only the zones for the Regions where you have chosen the option to opt in.</p>"}))
