    DescribeImageAttributeOutput.add_member(:uefi_data, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValue, location_name: 'UefiData', traits: {"aws.protocols#ec2QueryName" => "UefiData", "smithy.api#documentation" => "<p>Base64 representation of the non-volatile UEFI variable store. To retrieve the UEFI data,\n      use the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetInstanceUefiData\">GetInstanceUefiData</a> command. You can inspect and modify the UEFI data by using the\n        <a href=\"https://github.com/awslabs/python-uefivars\">python-uefivars tool</a> on\n      GitHub. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/uefi-secure-boot.html\">UEFI Secure Boot for Amazon EC2\n        instances</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "uefiData"}))
    DescribeImageAttributeOutput.add_member(:last_launched_time, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValue, location_name: 'LastLaunchedTime', traits: {"aws.protocols#ec2QueryName" => "LastLaunchedTime", "smithy.api#documentation" => "<p>The date and time, in <a href=\"http://www.iso.org/iso/iso8601\">ISO 8601 date-time\n        format</a>, when the AMI was last used to launch an EC2 instance. When the AMI is used\n      to launch an instance, there is a 24-hour delay before that usage is reported.</p>\n         <note>\n            <p>\n               <code>lastLaunchedTime</code> data is available starting April 2017.</p>\n         </note>", "smithy.api#xmlName" => "lastLaunchedTime"}))
    DescribeImageAttributeOutput.add_member(:imds_support, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValue, location_name: 'ImdsSupport', traits: {"aws.protocols#ec2QueryName" => "ImdsSupport", "smithy.api#documentation" => "<p>If <code>v2.0</code>, it indicates that IMDSv2 is specified in the AMI. Instances launched\n      from this AMI will have <code>HttpTokens</code> automatically set to <code>required</code> so\n      that, by default, the instance requires that IMDSv2 is used when requesting instance metadata.\n      In addition, <code>HttpPutResponseHopLimit</code> is set to <code>2</code>. For more\n      information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/configuring-IMDS-new-instances.html#configure-IMDS-new-instances-ami-configuration\">Configure the AMI</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "imdsSupport"}))
