    DescribeSpotPriceHistoryRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"aws.protocols#ec2QueryName" => "DryRun", "smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually\n            making the request, and provides an error response. If you have the required\n            permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is\n            <code>UnauthorizedOperation</code>.</p>", "smithy.api#xmlName" => "dryRun"}))
    DescribeSpotPriceHistoryRequest.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'StartTime', traits: {"aws.protocols#ec2QueryName" => "StartTime", "smithy.api#documentation" => "<p>The date and time, up to the past 90 days, from which to start retrieving the price\n            history data, in UTC format (for example,\n            <i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).</p>", "smithy.api#xmlName" => "startTime"}))
    DescribeSpotPriceHistoryRequest.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'EndTime', traits: {"aws.protocols#ec2QueryName" => "EndTime", "smithy.api#documentation" => "<p>The date and time, up to the current date, from which to stop retrieving the price\n            history data, in UTC format (for example,\n            <i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).</p>", "smithy.api#xmlName" => "endTime"}))
