    DescribeSpotPriceHistoryRequest.add_member(:filters, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Filters', traits: {"smithy.api#documentation" => "<p>The filters.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>availability-zone</code> - The Availability Zone for which prices should\n                    be returned.</p>\n            </li>\n            <li>\n               <p>\n                  <code>availability-zone-id</code> - The ID of the Availability Zone for which\n                    prices should be returned.</p>\n            </li>\n            <li>\n               <p>\n                  <code>instance-type</code> - The type of instance (for example,\n                    <code>m3.medium</code>).</p>\n            </li>\n            <li>\n               <p>\n                  <code>product-description</code> - The product description for the Spot price\n                    (<code>Linux/UNIX</code> | <code>Red Hat Enterprise Linux</code> |\n                    <code>SUSE Linux</code> | <code>Windows</code> | <code>Linux/UNIX (Amazon\n                        VPC)</code> | <code>Red Hat Enterprise Linux (Amazon VPC)</code> |\n                    <code>SUSE Linux (Amazon VPC)</code> | <code>Windows (Amazon\n                        VPC)</code>).</p>\n            </li>\n            <li>\n               <p>\n                  <code>spot-price</code> - The Spot price. The value must match exactly (or use\n                    wildcards; greater than or less than comparison is not supported).</p>\n            </li>\n            <li>\n               <p>\n                  <code>timestamp</code> - The time stamp of the Spot price history, in UTC format\n                    (for example, <i>ddd MMM dd\n                        HH</i>:<i>mm</i>:<i>ss</i> UTC\n                        <i>YYYY</i>). You can use wildcards (<code>*</code> and\n                        <code>?</code>). Greater than or less than comparison is not\n                    supported.</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "Filter"}))
    DescribeSpotPriceHistoryRequest.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZone', traits: {"aws.protocols#ec2QueryName" => "AvailabilityZone", "smithy.api#documentation" => "<p>Filters the results by the specified Availability Zone.</p>\n         <p>Either <code>AvailabilityZone</code> or <code>AvailabilityZoneId</code> can be specified, but not both</p>", "smithy.api#xmlName" => "availabilityZone"}))
    DescribeSpotPriceHistoryRequest.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'MaxResults', traits: {"aws.protocols#ec2QueryName" => "MaxResults", "smithy.api#documentation" => "<p>The maximum number of items to return for this request.\n         To get the next page of items, make another request with the token returned in the output.\n\t        For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/Query-Requests.html#api-pagination\">Pagination</a>.</p>", "smithy.api#xmlName" => "maxResults"}))
