    EnableSnapshotBlockPublicAccessRequest.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotBlockPublicAccessState, location_name: 'State', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The mode in which to enable block public access for snapshots for the Region. \n      Specify one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>block-all-sharing</code> - Prevents all public sharing of snapshots in \n          the Region. Users in the account will no longer be able to request new public \n          sharing. Additionally, snapshots that are already publicly shared are treated as \n          private and they are no longer publicly available.</p>\n            </li>\n            <li>\n               <p>\n                  <code>block-new-sharing</code>  - Prevents only new public sharing of snapshots \n          in the Region. Users in the account will no longer be able to request new public \n          sharing. However, snapshots that are already publicly shared, remain publicly \n          available.</p>\n            </li>\n         </ul>\n         <p>\n            <code>unblocked</code> is not a valid value for <b>EnableSnapshotBlockPublicAccess</b>.</p>", "smithy.api#required" => {}}))
    EnableSnapshotBlockPublicAccessRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually making the request, \n   and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. \n   Otherwise, it is <code>UnauthorizedOperation</code>.</p>"}))
