    ExportTransitGatewayRoutesRequest.add_member(:filters, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Filters', traits: {"smithy.api#documentation" => "<p>One or more filters. The possible values are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>attachment.transit-gateway-attachment-id</code> - The id of the transit gateway attachment.</p>\n            </li>\n            <li>\n               <p>\n                  <code>attachment.resource-id</code> - The resource id of the transit gateway attachment.</p>\n            </li>\n            <li>\n               <p>\n                  <code>route-search.exact-match</code> - The exact match of the specified filter.</p>\n            </li>\n            <li>\n               <p>\n                  <code>route-search.longest-prefix-match</code> - The longest prefix that matches the route.</p>\n            </li>\n            <li>\n               <p>\n                  <code>route-search.subnet-of-match</code> - The routes with a subnet that match the specified CIDR filter.</p>\n            </li>\n            <li>\n               <p>\n                  <code>route-search.supernet-of-match</code> - The routes with a CIDR that encompass the CIDR filter. For example, if you have 10.0.1.0/29 and 10.0.1.0/31 routes in your route table and you specify supernet-of-match as 10.0.1.0/30, then the result returns 10.0.1.0/29.</p>\n            </li>\n            <li>\n               <p>\n                  <code>state</code> - The state of the route (<code>active</code> | <code>blackhole</code>).</p>\n            </li>\n            <li>\n               <p>\n                  <code>transit-gateway-route-destination-cidr-block</code> - The CIDR range.</p>\n            </li>\n            <li>\n               <p>\n                  <code>type</code> - The type of route (<code>propagated</code> |\n               <code>static</code>).</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "Filter"}))
    ExportTransitGatewayRoutesRequest.add_member(:s3_bucket, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3Bucket', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the S3 bucket.</p>", "smithy.api#required" => {}}))
