    FleetActivityStatus.add_member(:fulfilled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FULFILLED', traits: {"smithy.api#enumValue" => "fulfilled"}))
    FleetBlockDeviceMappingRequest.add_member(:device_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DeviceName', traits: {"smithy.api#documentation" => "<p>The device name (for example, <code>/dev/sdh</code> or <code>xvdh</code>).</p>"}))
    FleetBlockDeviceMappingRequest.add_member(:virtual_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'VirtualName', traits: {"smithy.api#documentation" => "<p>The virtual device name (<code>ephemeralN</code>). Instance store volumes are numbered\n         starting from 0. An instance type with 2 available instance store volumes can specify\n         mappings for <code>ephemeral0</code> and <code>ephemeral1</code>. The number of available\n         instance store volumes depends on the instance type. After you connect to the instance, you\n         must mount the volume.</p>\n         <p>NVMe instance store volumes are automatically enumerated and assigned a device name.\n         Including them in your block device mapping has no effect.</p>\n         <p>Constraints: For M3 instances, you must specify instance store volumes in the block\n         device mapping for the instance. When you launch an M3 instance, we ignore any instance\n         store volumes specified in the block device mapping for the AMI.</p>"}))
    FleetBlockDeviceMappingRequest.add_member(:ebs, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetEbsBlockDeviceRequest, location_name: 'Ebs', traits: {"smithy.api#documentation" => "<p>Parameters used to automatically set up EBS volumes when the instance is\n         launched.</p>"}))
    FleetBlockDeviceMappingRequest.add_member(:no_device, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NoDevice', traits: {"smithy.api#documentation" => "<p>To omit the device from the block device mapping, specify an empty string. When this\n         property is specified, the device is removed from the block device mapping regardless of\n         the assigned value.</p>"}))
    FleetBlockDeviceMappingRequest.type = Types::FleetBlockDeviceMappingRequest
    FleetBlockDeviceMappingRequestList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: FleetBlockDeviceMappingRequest, traits: {"smithy.api#xmlName" => "BlockDeviceMapping"})
