    FleetCapacityReservation.add_member(:availability_zone_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZoneId', traits: {"aws.protocols#ec2QueryName" => "AvailabilityZoneId", "smithy.api#documentation" => "<p>The ID of the Availability Zone in which the Capacity Reservation reserves\n\t\t\tcapacity.</p>", "smithy.api#xmlName" => "availabilityZoneId"}))
