    FleetCapacityReservation.add_member(:instance_platform, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationInstancePlatform, location_name: 'InstancePlatform', traits: {"aws.protocols#ec2QueryName" => "InstancePlatform", "smithy.api#documentation" => "<p>The type of operating system for which the Capacity Reservation reserves\n\t\t\tcapacity.</p>", "smithy.api#xmlName" => "instancePlatform"}))
    FleetCapacityReservation.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZone', traits: {"aws.protocols#ec2QueryName" => "AvailabilityZone", "smithy.api#documentation" => "<p>The Availability Zone in which the Capacity Reservation reserves capacity.</p>", "smithy.api#xmlName" => "availabilityZone"}))
