    FleetCapacityReservation.add_member(:fulfilled_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'FulfilledCapacity', traits: {"aws.protocols#ec2QueryName" => "FulfilledCapacity", "smithy.api#documentation" => "<p>The number of capacity units fulfilled by the Capacity Reservation. For more\n\t\t\tinformation, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/crfleet-concepts.html#target-capacity\">Total target\n\t\t\t\tcapacity</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "fulfilledCapacity"}))
    FleetCapacityReservation.add_member(:ebs_optimized, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EbsOptimized', traits: {"aws.protocols#ec2QueryName" => "EbsOptimized", "smithy.api#documentation" => "<p>Indicates whether the Capacity Reservation reserves capacity for EBS-optimized\n\t\t\tinstance types.</p>", "smithy.api#xmlName" => "ebsOptimized"}))
    FleetCapacityReservation.add_member(:create_date, Smithy::Schema::Shapes::ShapeRef.new(shape: MillisecondDateTime, location_name: 'CreateDate', traits: {"aws.protocols#ec2QueryName" => "CreateDate", "smithy.api#documentation" => "<p>The date and time at which the Capacity Reservation was created.</p>", "smithy.api#xmlName" => "createDate"}))
    FleetCapacityReservation.add_member(:weight, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleWithConstraints, location_name: 'Weight', traits: {"aws.protocols#ec2QueryName" => "Weight", "smithy.api#documentation" => "<p>The weight of the instance type in the Capacity Reservation Fleet. For more\n\t\t\tinformation, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/crfleet-concepts.html#instance-weight\">Instance type\n\t\t\t\tweight</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "weight"}))
    FleetCapacityReservation.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerWithConstraints, location_name: 'Priority', traits: {"aws.protocols#ec2QueryName" => "Priority", "smithy.api#documentation" => "<p>The priority of the instance type in the Capacity Reservation Fleet. For more\n\t\t\tinformation, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/crfleet-concepts.html#instance-priority\">Instance type\n\t\t\t\tpriority</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "priority"}))
