    FleetCapacityReservationUsageStrategy.add_member(:use_capacity_reservations_first, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'USE_CAPACITY_RESERVATIONS_FIRST', traits: {"smithy.api#enumValue" => "use-capacity-reservations-first"}))
    FleetData.add_member(:activity_status, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetActivityStatus, location_name: 'ActivityStatus', traits: {"aws.protocols#ec2QueryName" => "ActivityStatus", "smithy.api#documentation" => "<p>The progress of the EC2 Fleet. If there is an error, the status is <code>error</code>. After\n         all requests are placed, the status is <code>pending_fulfillment</code>. If the size of the\n         EC2 Fleet is equal to or greater than its target capacity, the status is <code>fulfilled</code>.\n         If the size of the EC2 Fleet is decreased, the status is <code>pending_termination</code> while\n         instances are terminating.</p>", "smithy.api#xmlName" => "activityStatus"}))
    FleetData.add_member(:create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'CreateTime', traits: {"aws.protocols#ec2QueryName" => "CreateTime", "smithy.api#documentation" => "<p>The creation date and time of the EC2 Fleet.</p>", "smithy.api#xmlName" => "createTime"}))
    FleetData.add_member(:fleet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetId, location_name: 'FleetId', traits: {"aws.protocols#ec2QueryName" => "FleetId", "smithy.api#documentation" => "<p>The ID of the EC2 Fleet.</p>", "smithy.api#xmlName" => "fleetId"}))
    FleetData.add_member(:fleet_state, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetStateCode, location_name: 'FleetState', traits: {"aws.protocols#ec2QueryName" => "FleetState", "smithy.api#documentation" => "<p>The state of the EC2 Fleet.</p>", "smithy.api#xmlName" => "fleetState"}))
    FleetData.add_member(:client_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ClientToken', traits: {"aws.protocols#ec2QueryName" => "ClientToken", "smithy.api#documentation" => "<p>Unique, case-sensitive identifier that you provide to ensure the idempotency of the\n         request. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/Run_Instance_Idempotency.html\">Ensuring\n            idempotency</a>.</p>\n         <p>Constraints: Maximum 64 ASCII characters</p>", "smithy.api#xmlName" => "clientToken"}))
    FleetData.add_member(:excess_capacity_termination_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetExcessCapacityTerminationPolicy, location_name: 'ExcessCapacityTerminationPolicy', traits: {"aws.protocols#ec2QueryName" => "ExcessCapacityTerminationPolicy", "smithy.api#documentation" => "<p>Indicates whether running instances should be terminated if the target capacity of the\n         EC2 Fleet is decreased below the current size of the EC2 Fleet.</p>\n         <p>Supported only for fleets of type <code>maintain</code>.</p>", "smithy.api#xmlName" => "excessCapacityTerminationPolicy"}))
    FleetData.add_member(:fulfilled_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'FulfilledCapacity', traits: {"aws.protocols#ec2QueryName" => "FulfilledCapacity", "smithy.api#documentation" => "<p>The number of units fulfilled by this request compared to the set target\n         capacity.</p>", "smithy.api#xmlName" => "fulfilledCapacity"}))
    FleetData.add_member(:fulfilled_on_demand_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'FulfilledOnDemandCapacity', traits: {"aws.protocols#ec2QueryName" => "FulfilledOnDemandCapacity", "smithy.api#documentation" => "<p>The number of units fulfilled by this request compared to the set target On-Demand\n         capacity.</p>", "smithy.api#xmlName" => "fulfilledOnDemandCapacity"}))
    FleetData.add_member(:launch_template_configs, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetLaunchTemplateConfigList, location_name: 'LaunchTemplateConfigs', traits: {"aws.protocols#ec2QueryName" => "LaunchTemplateConfigs", "smithy.api#documentation" => "<p>The launch template and overrides.</p>", "smithy.api#xmlName" => "launchTemplateConfigs"}))
    FleetData.add_member(:target_capacity_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetCapacitySpecification, location_name: 'TargetCapacitySpecification', traits: {"aws.protocols#ec2QueryName" => "TargetCapacitySpecification", "smithy.api#documentation" => "<p>The number of units to request. You can choose to set the target capacity in terms of\n         instances or a performance characteristic that is important to your application workload,\n         such as vCPUs, memory, or I/O. If the request type is <code>maintain</code>, you can\n         specify a target capacity of 0 and add capacity later.</p>", "smithy.api#xmlName" => "targetCapacitySpecification"}))
    FleetData.add_member(:terminate_instances_with_expiration, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'TerminateInstancesWithExpiration', traits: {"aws.protocols#ec2QueryName" => "TerminateInstancesWithExpiration", "smithy.api#documentation" => "<p>Indicates whether running instances should be terminated when the EC2 Fleet expires. </p>", "smithy.api#xmlName" => "terminateInstancesWithExpiration"}))
    FleetData.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetType, location_name: 'Type', traits: {"aws.protocols#ec2QueryName" => "Type", "smithy.api#documentation" => "<p>The type of request. Indicates whether the EC2 Fleet only <code>requests</code> the target\n         capacity, or also attempts to <code>maintain</code> it. If you request a certain target\n         capacity, EC2 Fleet only places the required requests; it does not attempt to replenish\n         instances if capacity is diminished, and it does not submit requests in alternative\n         capacity pools if capacity is unavailable. To maintain a certain target capacity, EC2 Fleet\n         places the required requests to meet this target capacity. It also automatically\n         replenishes any interrupted Spot Instances. Default: <code>maintain</code>.</p>", "smithy.api#xmlName" => "type"}))
    FleetData.add_member(:valid_from, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'ValidFrom', traits: {"aws.protocols#ec2QueryName" => "ValidFrom", "smithy.api#documentation" => "<p>The start date and time of the request, in UTC format (for example,\n            <i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).\n         The default is to start fulfilling the request immediately. </p>", "smithy.api#xmlName" => "validFrom"}))
    FleetData.add_member(:valid_until, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'ValidUntil', traits: {"aws.protocols#ec2QueryName" => "ValidUntil", "smithy.api#documentation" => "<p>The end date and time of the request, in UTC format (for example,\n            <i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).\n         At this point, no new instance requests are placed or able to fulfill the request. The\n         default end date is 7 days from the current date. </p>", "smithy.api#xmlName" => "validUntil"}))
    FleetData.add_member(:replace_unhealthy_instances, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ReplaceUnhealthyInstances', traits: {"aws.protocols#ec2QueryName" => "ReplaceUnhealthyInstances", "smithy.api#documentation" => "<p>Indicates whether EC2 Fleet should replace unhealthy Spot Instances. Supported only for\n         fleets of type <code>maintain</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/manage-ec2-fleet.html#ec2-fleet-health-checks\">EC2 Fleet\n            health checks</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "replaceUnhealthyInstances"}))
    FleetData.add_member(:spot_options, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotOptions, location_name: 'SpotOptions', traits: {"aws.protocols#ec2QueryName" => "SpotOptions", "smithy.api#documentation" => "<p>The configuration of Spot Instances in an EC2 Fleet.</p>", "smithy.api#xmlName" => "spotOptions"}))
    FleetData.add_member(:on_demand_options, Smithy::Schema::Shapes::ShapeRef.new(shape: OnDemandOptions, location_name: 'OnDemandOptions', traits: {"aws.protocols#ec2QueryName" => "OnDemandOptions", "smithy.api#documentation" => "<p>The allocation strategy of On-Demand Instances in an EC2 Fleet.</p>", "smithy.api#xmlName" => "onDemandOptions"}))
    FleetData.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"aws.protocols#ec2QueryName" => "TagSet", "smithy.api#documentation" => "<p>The tags for an EC2 Fleet resource.</p>", "smithy.api#xmlName" => "tagSet"}))
    FleetData.add_member(:errors, Smithy::Schema::Shapes::ShapeRef.new(shape: DescribeFleetsErrorSet, location_name: 'Errors', traits: {"aws.protocols#ec2QueryName" => "ErrorSet", "smithy.api#documentation" => "<p>Information about the instances that could not be launched by the fleet. Valid only when\n         <b>Type</b> is set to <code>instant</code>.</p>", "smithy.api#xmlName" => "errorSet"}))
    FleetData.add_member(:instances, Smithy::Schema::Shapes::ShapeRef.new(shape: DescribeFleetsInstancesSet, location_name: 'Instances', traits: {"aws.protocols#ec2QueryName" => "FleetInstanceSet", "smithy.api#documentation" => "<p>Information about the instances that were launched by the fleet. Valid only when\n         <b>Type</b> is set to <code>instant</code>.</p>", "smithy.api#xmlName" => "fleetInstanceSet"}))
    FleetData.add_member(:context, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Context', traits: {"aws.protocols#ec2QueryName" => "Context", "smithy.api#documentation" => "<p>Reserved.</p>", "smithy.api#xmlName" => "context"}))
    FleetData.type = Types::FleetData
    FleetEbsBlockDeviceRequest.add_member(:encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'Encrypted', traits: {"smithy.api#documentation" => "<p>Indicates whether the encryption state of an EBS volume is changed while being restored\n         from a backing snapshot. The effect of setting the encryption state to <code>true</code>\n         depends on the volume origin (new or from a snapshot), starting encryption state,\n         ownership, and whether encryption by default is enabled. For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/ebs-encryption.html\">Amazon EBS\n            encryption</a> in the <i>Amazon EBS User Guide</i>.</p>\n         <p>In no case can you remove encryption from an encrypted volume.</p>\n         <p>Encrypted volumes can only be attached to instances that support Amazon EBS encryption. For\n         more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/ebs-encryption-requirements.html#ebs-encryption_supported_instances\">Supported instance types</a>.</p>\n         <p>This parameter is not returned by <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_DescribeImageAttribute\">DescribeImageAttribute</a>.</p>\n         <p>For <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateImage\">CreateImage</a> and <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_RegisterImage\">RegisterImage</a>, whether you\n         can include this parameter, and the allowed values differ depending on the type of block\n         device mapping you are creating.</p>\n         <ul>\n            <li>\n               <p>If you are creating a block device mapping for a <b>new (empty)\n                  volume</b>, you can include this parameter, and specify either\n                  <code>true</code> for an encrypted volume, or <code>false</code> for an\n               unencrypted volume. If you omit this parameter, it defaults to <code>false</code>\n               (unencrypted).</p>\n            </li>\n            <li>\n               <p>If you are creating a block device mapping from an <b>existing encrypted or\n                  unencrypted snapshot</b>, you must omit this parameter. If you include this\n               parameter, the request will fail, regardless of the value that you specify.</p>\n            </li>\n            <li>\n               <p>If you are creating a block device mapping from an <b>existing unencrypted\n                  volume</b>, you can include this parameter, but you must specify\n                  <code>false</code>. If you specify <code>true</code>, the request will fail. In\n               this case, we recommend that you omit the parameter.</p>\n            </li>\n            <li>\n               <p>If you are creating a block device mapping from an <b>existing encrypted\n                  volume</b>, you can include this parameter, and specify either\n                  <code>true</code> or <code>false</code>. However, if you specify\n                  <code>false</code>, the parameter is ignored and the block device mapping is\n               always encrypted. In this case, we recommend that you omit the parameter.</p>\n            </li>\n         </ul>"}))
    FleetEbsBlockDeviceRequest.add_member(:delete_on_termination, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DeleteOnTermination', traits: {"smithy.api#documentation" => "<p>Indicates whether the EBS volume is deleted on instance termination. For more\n         information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/preserving-volumes-on-termination.html\">Preserve data when\n            an instance is terminated</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    FleetEbsBlockDeviceRequest.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The number of I/O operations per second (IOPS). For <code>gp3</code>, <code>io1</code>, and <code>io2</code> volumes,\n         this represents the number of IOPS that are provisioned for the volume. For <code>gp2</code>\n         volumes, this represents the baseline performance of the volume and the rate at which\n         the volume accumulates I/O credits for bursting.</p>\n         <p>The following are the supported values for each volume type:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>gp3</code>: 3,000 - 16,000 IOPS</p>\n            </li>\n            <li>\n               <p>\n                  <code>io1</code>: 100 - 64,000 IOPS</p>\n            </li>\n            <li>\n               <p>\n                  <code>io2</code>: 100 - 256,000 IOPS</p>\n            </li>\n         </ul>\n         <p>For <code>io2</code> volumes, you can achieve up to 256,000 IOPS on \n<a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html#ec2-nitro-instances\">instances \nbuilt on the Nitro System</a>. On other instances, you can achieve performance up to 32,000 IOPS.</p>\n         <p>This parameter is required for <code>io1</code> and <code>io2</code> volumes. The default for <code>gp3</code> volumes\n         is 3,000 IOPS.</p>"}))
    FleetEbsBlockDeviceRequest.add_member(:throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Throughput', traits: {"smithy.api#documentation" => "<p>The throughput that the volume supports, in MiB/s.</p>\n         <p>This parameter is valid only for <code>gp3</code> volumes.</p>\n         <p>Valid Range: Minimum value of 125. Maximum value of 1000.</p>"}))
    FleetEbsBlockDeviceRequest.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyId, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>Identifier (key ID, key alias, key ARN, or alias ARN) of the customer managed KMS key \n         to use for EBS encryption.</p>\n         <p>This parameter is only supported on <code>BlockDeviceMapping</code> objects called by\n            <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateFleet.html\">CreateFleet</a>, <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_RequestSpotInstances.html\">RequestSpotInstances</a>, and <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_RunInstances.html\">RunInstances</a>.</p>"}))
    FleetEbsBlockDeviceRequest.add_member(:snapshot_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotId, location_name: 'SnapshotId', traits: {"smithy.api#documentation" => "<p>The ID of the snapshot.</p>"}))
    FleetEbsBlockDeviceRequest.add_member(:volume_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'VolumeSize', traits: {"smithy.api#documentation" => "<p>The size of the volume, in GiBs. You must specify either a snapshot ID or a volume\n         size. If you specify a snapshot, the default is the snapshot size. You can specify a\n         volume size that is equal to or larger than the snapshot size.</p>\n         <p>The following are the supported sizes for each volume type:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>gp2</code> and <code>gp3</code>: 1 - 16,384 GiB</p>\n            </li>\n            <li>\n               <p>\n                  <code>io1</code>: 4 - 16,384 GiB</p>\n            </li>\n            <li>\n               <p>\n                  <code>io2</code>: 4 - 65,536 GiB</p>\n            </li>\n            <li>\n               <p>\n                  <code>st1</code> and <code>sc1</code>: 125 - 16,384 GiB</p>\n            </li>\n            <li>\n               <p>\n                  <code>standard</code>: 1 - 1024 GiB</p>\n            </li>\n         </ul>"}))
    FleetEbsBlockDeviceRequest.add_member(:volume_type, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeType, location_name: 'VolumeType', traits: {"smithy.api#documentation" => "<p>The volume type. For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/ebs-volume-types.html\">Amazon EBS volume types</a> in the\n         <i>Amazon EBS User Guide</i>.</p>"}))
    FleetEbsBlockDeviceRequest.type = Types::FleetEbsBlockDeviceRequest
