    FleetEventType.add_member(:fleet_change, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FLEET_CHANGE', traits: {"smithy.api#enumValue" => "fleet-change"}))
