    FleetExcessCapacityTerminationPolicy.add_member(:termination, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'TERMINATION', traits: {"smithy.api#enumValue" => "termination"}))
