    FleetLaunchTemplateConfig.add_member(:launch_template_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetLaunchTemplateSpecification, location_name: 'LaunchTemplateSpecification', traits: {"aws.protocols#ec2QueryName" => "LaunchTemplateSpecification", "smithy.api#documentation" => "<p>The launch template.</p>", "smithy.api#xmlName" => "launchTemplateSpecification"}))
    FleetLaunchTemplateConfig.add_member(:overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetLaunchTemplateOverridesList, location_name: 'Overrides', traits: {"aws.protocols#ec2QueryName" => "Overrides", "smithy.api#documentation" => "<p>Any parameters that you specify override the same parameters in the launch\n         template.</p>", "smithy.api#xmlName" => "overrides"}))
    FleetLaunchTemplateConfig.type = Types::FleetLaunchTemplateConfig
    FleetLaunchTemplateConfigList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: FleetLaunchTemplateConfig, traits: {"smithy.api#xmlName" => "item"})
    FleetLaunchTemplateConfigListRequest.member = Smithy::Schema::Shapes::ShapeRef.new(shape: FleetLaunchTemplateConfigRequest, traits: {"smithy.api#xmlName" => "item"})
    FleetLaunchTemplateConfigRequest.add_member(:launch_template_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetLaunchTemplateSpecificationRequest, location_name: 'LaunchTemplateSpecification', traits: {"smithy.api#documentation" => "<p>The launch template to use. You must specify either the launch template ID or launch\n         template name in the request. </p>"}))
    FleetLaunchTemplateConfigRequest.add_member(:overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetLaunchTemplateOverridesListRequest, location_name: 'Overrides', traits: {"smithy.api#documentation" => "<p>Any parameters that you specify override the same parameters in the launch\n         template.</p>\n         <p>For fleets of type <code>request</code> and <code>maintain</code>, a maximum of 300\n         items is allowed across all launch templates.</p>"}))
    FleetLaunchTemplateConfigRequest.type = Types::FleetLaunchTemplateConfigRequest
    FleetLaunchTemplateOverrides.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceType, location_name: 'InstanceType', traits: {"aws.protocols#ec2QueryName" => "InstanceType", "smithy.api#documentation" => "<p>The instance type.</p>\n         <p>\n            <code>mac1.metal</code> is not supported as a launch template override.</p>\n         <note>\n            <p>If you specify <code>InstanceType</code>, you can't specify\n               <code>InstanceRequirements</code>.</p>\n         </note>", "smithy.api#xmlName" => "instanceType"}))
    FleetLaunchTemplateOverrides.add_member(:max_price, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MaxPrice', traits: {"aws.protocols#ec2QueryName" => "MaxPrice", "smithy.api#documentation" => "<p>The maximum price per unit hour that you are willing to pay for a Spot Instance. We do not \n         recommend using this parameter because it can lead to increased interruptions. If you \n         do not specify this parameter, you will pay the current Spot price.\n      </p>\n         <important>\n            <p>If you specify a maximum price, your instances will be interrupted more frequently \n         than if you do not specify this parameter.</p>\n            <p>If you specify a maximum price, it must be more than USD $0.001. Specifying a value\n         below USD $0.001 will result in an <code>InvalidParameterValue</code> error\n         message.</p>\n         </important>", "smithy.api#xmlName" => "maxPrice"}))
    FleetLaunchTemplateOverrides.add_member(:subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SubnetId', traits: {"aws.protocols#ec2QueryName" => "SubnetId", "smithy.api#documentation" => "<p>The ID of the subnet in which to launch the instances.</p>", "smithy.api#xmlName" => "subnetId"}))
    FleetLaunchTemplateOverrides.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZoneName, location_name: 'AvailabilityZone', traits: {"aws.protocols#ec2QueryName" => "AvailabilityZone", "smithy.api#documentation" => "<p>The Availability Zone in which to launch the instances.</p>", "smithy.api#xmlName" => "availabilityZone"}))
    FleetLaunchTemplateOverrides.add_member(:weighted_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'WeightedCapacity', traits: {"aws.protocols#ec2QueryName" => "WeightedCapacity", "smithy.api#documentation" => "<p>The number of units provided by the specified instance type. These are the same units\n         that you chose to set the target capacity in terms of instances, or a performance\n         characteristic such as vCPUs, memory, or I/O.</p>\n         <p>If the target capacity divided by this value is not a whole number, Amazon EC2 rounds the\n         number of instances to the next whole number. If this value is not specified, the default\n         is 1.</p>\n         <note>\n            <p>When specifying weights, the price used in the <code>lowest-price</code> and\n            <code>price-capacity-optimized</code> allocation strategies is per\n            <i>unit</i> hour (where the instance price is divided by the specified\n            weight). However, if all the specified weights are above the requested\n            <code>TargetCapacity</code>, resulting in only 1 instance being launched, the price\n            used is per <i>instance</i> hour.</p>\n         </note>", "smithy.api#xmlName" => "weightedCapacity"}))
    FleetLaunchTemplateOverrides.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'Priority', traits: {"aws.protocols#ec2QueryName" => "Priority", "smithy.api#documentation" => "<p>The priority for the launch template override. The highest priority is launched\n         first.</p>\n         <p>If the On-Demand <code>AllocationStrategy</code> is set to <code>prioritized</code>,\n         EC2 Fleet uses priority to determine which launch template override to use first in fulfilling\n         On-Demand capacity.</p>\n         <p>If the Spot <code>AllocationStrategy</code> is set to\n            <code>capacity-optimized-prioritized</code>, EC2 Fleet uses priority on a best-effort basis\n         to determine which launch template override to use in fulfilling Spot capacity, but\n         optimizes for capacity first.</p>\n         <p>Valid values are whole numbers starting at <code>0</code>. The lower the number, the\n         higher the priority. If no number is set, the override has the lowest priority. You can set\n         the same priority for different launch template overrides.</p>", "smithy.api#xmlName" => "priority"}))
    FleetLaunchTemplateOverrides.add_member(:placement, Smithy::Schema::Shapes::ShapeRef.new(shape: PlacementResponse, location_name: 'Placement', traits: {"aws.protocols#ec2QueryName" => "Placement", "smithy.api#documentation" => "<p>The location where the instance launched, if applicable.</p>", "smithy.api#xmlName" => "placement"}))
    FleetLaunchTemplateOverrides.add_member(:instance_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRequirements, location_name: 'InstanceRequirements', traits: {"aws.protocols#ec2QueryName" => "InstanceRequirements", "smithy.api#documentation" => "<p>The attributes for the instance types. When you specify instance attributes, Amazon EC2 will\n         identify instance types with those attributes.</p>\n         <note>\n            <p>If you specify <code>InstanceRequirements</code>, you can't specify\n            <code>InstanceType</code>.</p>\n         </note>", "smithy.api#xmlName" => "instanceRequirements"}))
    FleetLaunchTemplateOverrides.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageId, location_name: 'ImageId', traits: {"aws.protocols#ec2QueryName" => "ImageId", "smithy.api#documentation" => "<p>The ID of the AMI in the format <code>ami-17characters00000</code>.</p>\n         <p>Alternatively, you can specify a Systems Manager parameter, using one of the following\n         formats. The Systems Manager parameter will resolve to an AMI ID on launch.</p>\n         <p>To reference a public parameter:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>public-parameter</i>\n                  </code>\n               </p>\n            </li>\n         </ul>\n         <p>To reference a parameter stored in the same account:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-name</i>\n                  </code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-name:version-number</i>\n                  </code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-name:label</i>\n                  </code>\n               </p>\n            </li>\n         </ul>\n         <p>To reference a parameter shared from another Amazon Web Services account:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-ARN</i>\n                  </code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-ARN:version-number</i>\n                  </code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-ARN:label</i>\n                  </code>\n               </p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/create-launch-template.html#use-an-ssm-parameter-instead-of-an-ami-id\">Use a Systems Manager parameter instead of an AMI ID</a> in the\n            <i>Amazon EC2 User Guide</i>.</p>\n         <note>\n            <p>This parameter is only available for fleets of type <code>instant</code>. For fleets\n            of type <code>maintain</code> and <code>request</code>, you must specify the AMI ID in\n            the launch template.</p>\n         </note>", "smithy.api#xmlName" => "imageId"}))
    FleetLaunchTemplateOverrides.add_member(:block_device_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceMappingResponseList, location_name: 'BlockDeviceMappings', traits: {"aws.protocols#ec2QueryName" => "BlockDeviceMappingSet", "smithy.api#documentation" => "<p>The block device mappings, which define the EBS volumes and instance store volumes to\n         attach to the instance at launch.</p>\n         <p>Supported only for fleets of type <code>instant</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/block-device-mapping-concepts.html\">Block device mappings\n            for volumes on Amazon EC2 instances</a> in the <i>Amazon EC2 User\n         Guide</i>.</p>", "smithy.api#xmlName" => "blockDeviceMappingSet"}))
