    FleetLaunchTemplateOverridesListRequest.member = Smithy::Schema::Shapes::ShapeRef.new(shape: FleetLaunchTemplateOverridesRequest, traits: {"smithy.api#xmlName" => "item"})
    FleetLaunchTemplateOverridesRequest.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceType, location_name: 'InstanceType', traits: {"smithy.api#documentation" => "<p>The instance type.</p>\n         <p>\n            <code>mac1.metal</code> is not supported as a launch template override.</p>\n         <note>\n            <p>If you specify <code>InstanceType</code>, you can't specify\n               <code>InstanceRequirements</code>.</p>\n         </note>"}))
    FleetLaunchTemplateOverridesRequest.add_member(:max_price, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MaxPrice', traits: {"smithy.api#documentation" => "<p>The maximum price per unit hour that you are willing to pay for a Spot Instance. We do not \n         recommend using this parameter because it can lead to increased interruptions. If you \n         do not specify this parameter, you will pay the current Spot price.\n      </p>\n         <important>\n            <p>If you specify a maximum price, your instances will be interrupted more \n            frequently than if you do not specify this parameter.</p>\n            <p>If you specify a maximum price, it must be more than USD $0.001. Specifying a value\n            below USD $0.001 will result in an <code>InvalidParameterValue</code> error\n            message.</p>\n         </important>"}))
    FleetLaunchTemplateOverridesRequest.add_member(:subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetId, location_name: 'SubnetId', traits: {"smithy.api#documentation" => "<p>The IDs of the subnets in which to launch the instances. Separate multiple subnet IDs using commas (for example, <code>subnet-1234abcdeexample1, subnet-0987cdef6example2</code>). A request of type <code>instant</code> can have only one subnet ID.</p>"}))
    FleetLaunchTemplateOverridesRequest.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZoneName, location_name: 'AvailabilityZone', traits: {"smithy.api#documentation" => "<p>The Availability Zone in which to launch the instances.</p>"}))
    FleetLaunchTemplateOverridesRequest.add_member(:weighted_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'WeightedCapacity', traits: {"smithy.api#documentation" => "<p>The number of units provided by the specified instance type. These are the same units\n         that you chose to set the target capacity in terms of instances, or a performance\n         characteristic such as vCPUs, memory, or I/O.</p>\n         <p>If the target capacity divided by this value is not a whole number, Amazon EC2 rounds the\n         number of instances to the next whole number. If this value is not specified, the default\n         is 1.</p>\n         <note>\n            <p>When specifying weights, the price used in the <code>lowest-price</code> and\n               <code>price-capacity-optimized</code> allocation strategies is per\n               <i>unit</i> hour (where the instance price is divided by the specified\n            weight). However, if all the specified weights are above the requested\n               <code>TargetCapacity</code>, resulting in only 1 instance being launched, the price\n            used is per <i>instance</i> hour.</p>\n         </note>"}))
    FleetLaunchTemplateOverridesRequest.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'Priority', traits: {"smithy.api#documentation" => "<p>The priority for the launch template override. The highest priority is launched\n         first.</p>\n         <p>If the On-Demand <code>AllocationStrategy</code> is set to <code>prioritized</code>,\n         EC2 Fleet uses priority to determine which launch template override to use first in fulfilling\n         On-Demand capacity.</p>\n         <p>If the Spot <code>AllocationStrategy</code> is set to\n            <code>capacity-optimized-prioritized</code>, EC2 Fleet uses priority on a best-effort basis\n         to determine which launch template override to use in fulfilling Spot capacity, but\n         optimizes for capacity first.</p>\n         <p>Valid values are whole numbers starting at <code>0</code>. The lower the number, the\n         higher the priority. If no number is set, the launch template override has the lowest\n         priority. You can set the same priority for different launch template overrides.</p>"}))
    FleetLaunchTemplateOverridesRequest.add_member(:placement, Smithy::Schema::Shapes::ShapeRef.new(shape: Placement, location_name: 'Placement', traits: {"smithy.api#documentation" => "<p>The location where the instance launched, if applicable.</p>"}))
    FleetLaunchTemplateOverridesRequest.add_member(:block_device_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetBlockDeviceMappingRequestList, location_name: 'BlockDeviceMappings', traits: {"smithy.api#documentation" => "<p>The block device mappings, which define the EBS volumes and instance store volumes to\n         attach to the instance at launch.</p>\n         <p>Supported only for fleets of type <code>instant</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/block-device-mapping-concepts.html\">Block device mappings\n            for volumes on Amazon EC2 instances</a> in the <i>Amazon EC2 User\n         Guide</i>.</p>", "smithy.api#xmlName" => "BlockDeviceMapping"}))
    FleetLaunchTemplateOverridesRequest.add_member(:instance_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRequirementsRequest, location_name: 'InstanceRequirements', traits: {"smithy.api#documentation" => "<p>The attributes for the instance types. When you specify instance attributes, Amazon EC2 will\n         identify instance types with those attributes.</p>\n         <note>\n            <p>If you specify <code>InstanceRequirements</code>, you can't specify\n            <code>InstanceType</code>.</p>\n         </note>"}))
    FleetLaunchTemplateOverridesRequest.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ImageId', traits: {"smithy.api#documentation" => "<p>The ID of the AMI in the format <code>ami-17characters00000</code>.</p>\n         <p>Alternatively, you can specify a Systems Manager parameter, using one of the following\n         formats. The Systems Manager parameter will resolve to an AMI ID on launch.</p>\n         <p>To reference a public parameter:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>public-parameter</i>\n                  </code>\n               </p>\n            </li>\n         </ul>\n         <p>To reference a parameter stored in the same account:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-name</i>\n                  </code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-name:version-number</i>\n                  </code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-name:label</i>\n                  </code>\n               </p>\n            </li>\n         </ul>\n         <p>To reference a parameter shared from another Amazon Web Services account:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-ARN</i>\n                  </code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-ARN:version-number</i>\n                  </code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>resolve:ssm:<i>parameter-ARN:label</i>\n                  </code>\n               </p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/create-launch-template.html#use-an-ssm-parameter-instead-of-an-ami-id\">Use a Systems Manager parameter instead of an AMI ID</a> in the\n         <i>Amazon EC2 User Guide</i>.</p>\n         <note>\n            <p>This parameter is only available for fleets of type <code>instant</code>. For fleets\n            of type <code>maintain</code> and <code>request</code>, you must specify the AMI ID in\n            the launch template.</p>\n         </note>"}))
    FleetLaunchTemplateOverridesRequest.type = Types::FleetLaunchTemplateOverridesRequest
    FleetLaunchTemplateSpecification.add_member(:launch_template_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LaunchTemplateId', traits: {"aws.protocols#ec2QueryName" => "LaunchTemplateId", "smithy.api#documentation" => "<p>The ID of the launch template.</p>\n         <p>You must specify the <code>LaunchTemplateId</code> or the <code>LaunchTemplateName</code>, but not both.</p>", "smithy.api#xmlName" => "launchTemplateId"}))
    FleetLaunchTemplateSpecification.add_member(:launch_template_name, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateName, location_name: 'LaunchTemplateName', traits: {"aws.protocols#ec2QueryName" => "LaunchTemplateName", "smithy.api#documentation" => "<p>The name of the launch template.</p>\n         <p>You must specify the <code>LaunchTemplateName</code> or the <code>LaunchTemplateId</code>, but not both.</p>", "smithy.api#xmlName" => "launchTemplateName"}))
    FleetLaunchTemplateSpecification.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Version', traits: {"aws.protocols#ec2QueryName" => "Version", "smithy.api#documentation" => "<p>The launch template version number, <code>$Latest</code>, or <code>$Default</code>.\n            You must specify a value, otherwise the request fails.</p>\n         <p>If the value is <code>$Latest</code>, Amazon EC2 uses the latest version of the launch\n            template.</p>\n         <p>If the value is <code>$Default</code>, Amazon EC2 uses the default version of the launch\n            template.</p>", "smithy.api#xmlName" => "version"}))
