    FleetSpotCapacityRebalance.add_member(:replacement_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetReplacementStrategy, location_name: 'ReplacementStrategy', traits: {"aws.protocols#ec2QueryName" => "ReplacementStrategy", "smithy.api#documentation" => "<p>The replacement strategy to use. Only available for fleets of type\n         <code>maintain</code>.</p>\n         <p>\n            <code>launch</code> - EC2 Fleet launches a new replacement Spot Instance when a\n         rebalance notification is emitted for an existing Spot Instance in the fleet. EC2 Fleet\n         does not terminate the instances that receive a rebalance notification. You can terminate\n         the old instances, or you can leave them running. You are charged for all instances while\n         they are running. </p>\n         <p>\n            <code>launch-before-terminate</code> - EC2 Fleet launches a new replacement Spot\n         Instance when a rebalance notification is emitted for an existing Spot Instance in the\n         fleet, and then, after a delay that you specify (in <code>TerminationDelay</code>),\n         terminates the instances that received a rebalance notification.</p>", "smithy.api#xmlName" => "replacementStrategy"}))
    FleetSpotCapacityRebalance.add_member(:termination_delay, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'TerminationDelay', traits: {"aws.protocols#ec2QueryName" => "TerminationDelay", "smithy.api#documentation" => "<p>The amount of time (in seconds) that Amazon EC2 waits before terminating the old Spot\n         Instance after launching a new replacement Spot Instance.</p>\n         <p>Required when <code>ReplacementStrategy</code> is set to <code>launch-before-terminate</code>.</p>\n         <p>Not valid when <code>ReplacementStrategy</code> is set to <code>launch</code>.</p>\n         <p>Valid values: Minimum value of <code>120</code> seconds. Maximum value of <code>7200</code> seconds.</p>", "smithy.api#xmlName" => "terminationDelay"}))
    FleetSpotCapacityRebalance.type = Types::FleetSpotCapacityRebalance
    FleetSpotCapacityRebalanceRequest.add_member(:replacement_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetReplacementStrategy, location_name: 'ReplacementStrategy', traits: {"smithy.api#documentation" => "<p>The replacement strategy to use. Only available for fleets of type\n         <code>maintain</code>.</p>\n         <p>\n            <code>launch</code> - EC2 Fleet launches a replacement Spot Instance when a rebalance\n         notification is emitted for an existing Spot Instance in the fleet. EC2 Fleet does not\n         terminate the instances that receive a rebalance notification. You can terminate the old\n         instances, or you can leave them running. You are charged for all instances while they are\n         running. </p>\n         <p>\n            <code>launch-before-terminate</code> - EC2 Fleet launches a replacement Spot Instance\n         when a rebalance notification is emitted for an existing Spot Instance in the fleet, and\n         then, after a delay that you specify (in <code>TerminationDelay</code>), terminates the\n         instances that received a rebalance notification.</p>"}))
    FleetSpotCapacityRebalanceRequest.add_member(:termination_delay, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'TerminationDelay', traits: {"smithy.api#documentation" => "<p>The amount of time (in seconds) that Amazon EC2 waits before terminating the old Spot\n         Instance after launching a new replacement Spot Instance.</p>\n         <p>Required when <code>ReplacementStrategy</code> is set to <code>launch-before-terminate</code>.</p>\n         <p>Not valid when <code>ReplacementStrategy</code> is set to <code>launch</code>.</p>\n         <p>Valid values: Minimum value of <code>120</code> seconds. Maximum value of <code>7200</code> seconds.</p>"}))
