    Image.add_member(:deprecation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DeprecationTime', traits: {"aws.protocols#ec2QueryName" => "DeprecationTime", "smithy.api#documentation" => "<p>The date and time to deprecate the AMI, in UTC, in the following format:\n        <i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z.\n      If you specified a value for seconds, Amazon EC2 rounds the seconds to the nearest minute.</p>", "smithy.api#xmlName" => "deprecationTime"}))
    Image.add_member(:imds_support, Smithy::Schema::Shapes::ShapeRef.new(shape: ImdsSupportValues, location_name: 'ImdsSupport', traits: {"aws.protocols#ec2QueryName" => "ImdsSupport", "smithy.api#documentation" => "<p>If <code>v2.0</code>, it indicates that IMDSv2 is specified in the AMI. Instances launched\n      from this AMI will have <code>HttpTokens</code> automatically set to <code>required</code> so\n      that, by default, the instance requires that IMDSv2 is used when requesting instance metadata.\n      In addition, <code>HttpPutResponseHopLimit</code> is set to <code>2</code>. For more\n      information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/configuring-IMDS-new-instances.html#configure-IMDS-new-instances-ami-configuration\">Configure the AMI</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "imdsSupport"}))
    Image.add_member(:source_instance_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceInstanceId', traits: {"aws.protocols#ec2QueryName" => "SourceInstanceId", "smithy.api#documentation" => "<p>The ID of the instance that the AMI was created from if the AMI was created using <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateImage.html\">CreateImage</a>. This field only appears if the AMI was created using\n      CreateImage.</p>", "smithy.api#xmlName" => "sourceInstanceId"}))
    Image.add_member(:deregistration_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DeregistrationProtection', traits: {"aws.protocols#ec2QueryName" => "DeregistrationProtection", "smithy.api#documentation" => "<p>Indicates whether deregistration protection is enabled for the AMI.</p>", "smithy.api#xmlName" => "deregistrationProtection"}))
    Image.add_member(:last_launched_time, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LastLaunchedTime', traits: {"aws.protocols#ec2QueryName" => "LastLaunchedTime", "smithy.api#documentation" => "<p>The date and time, in <a href=\"http://www.iso.org/iso/iso8601\">ISO 8601 date-time\n        format</a>, when the AMI was last used to launch an EC2 instance. When the AMI is used\n      to launch an instance, there is a 24-hour delay before that usage is reported.</p>\n         <note>\n            <p>\n               <code>lastLaunchedTime</code> data is available starting April 2017.</p>\n         </note>", "smithy.api#xmlName" => "lastLaunchedTime"}))
    Image.add_member(:image_allowed, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ImageAllowed', traits: {"aws.protocols#ec2QueryName" => "ImageAllowed", "smithy.api#documentation" => "<p>If <code>true</code>, the AMI satisfies the criteria for Allowed AMIs and can be\n      discovered and used in the account. If <code>false</code> and Allowed AMIs is set to\n      <code>enabled</code>, the AMI can't be discovered or used in the account. If\n      <code>false</code> and Allowed AMIs is set to <code>audit-mode</code>, the AMI can be\n      discovered and used in the account.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-allowed-amis.html\">Control the discovery and use of AMIs in\n      Amazon EC2 with Allowed AMIs</a> in\n      <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "imageAllowed"}))
    Image.add_member(:source_image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceImageId', traits: {"aws.protocols#ec2QueryName" => "SourceImageId", "smithy.api#documentation" => "<p>The ID of the source AMI from which the AMI was created.</p>", "smithy.api#xmlName" => "sourceImageId"}))
    Image.add_member(:source_image_region, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceImageRegion', traits: {"aws.protocols#ec2QueryName" => "SourceImageRegion", "smithy.api#documentation" => "<p>The Region of the source AMI.</p>", "smithy.api#xmlName" => "sourceImageRegion"}))
    Image.add_member(:free_tier_eligible, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'FreeTierEligible', traits: {"aws.protocols#ec2QueryName" => "FreeTierEligible", "smithy.api#documentation" => "<p>Indicates whether the image is eligible for Amazon Web Services Free Tier.</p>\n         <ul>\n            <li>\n               <p>If <code>true</code>, the AMI is eligible for Free Tier and can be used to launch\n          instances under the Free Tier limits.</p>\n            </li>\n            <li>\n               <p>If <code>false</code>, the AMI is not eligible for Free Tier.</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "freeTierEligible"}))
    Image.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ImageId', traits: {"aws.protocols#ec2QueryName" => "ImageId", "smithy.api#documentation" => "<p>The ID of the AMI.</p>", "smithy.api#xmlName" => "imageId"}))
