    Image.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageState, location_name: 'State', traits: {"aws.protocols#ec2QueryName" => "ImageState", "smithy.api#documentation" => "<p>The current state of the AMI. If the state is <code>available</code>, the image is\n      successfully registered and can be used to launch an instance.</p>", "smithy.api#xmlName" => "imageState"}))
