    Image.add_member(:public, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'Public', traits: {"aws.protocols#ec2QueryName" => "IsPublic", "smithy.api#documentation" => "<p>Indicates whether the image has public launch permissions. The value is <code>true</code>\n      if this image has public launch permissions or <code>false</code> if it has only implicit and\n      explicit launch permissions.</p>", "smithy.api#xmlName" => "isPublic"}))
