    InstanceNetworkInterfaceSpecification.add_member(:delete_on_termination, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DeleteOnTermination', traits: {"aws.protocols#ec2QueryName" => "DeleteOnTermination", "smithy.api#documentation" => "<p>If set to <code>true</code>, the interface is deleted when the instance is terminated.\n            You can specify <code>true</code> only if creating a new network interface when\n            launching an instance.</p>", "smithy.api#xmlName" => "deleteOnTermination"}))
    InstanceNetworkInterfaceSpecification.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"aws.protocols#ec2QueryName" => "Description", "smithy.api#documentation" => "<p>The description of the network interface. Applies only if creating a network interface\n            when launching an instance.</p>", "smithy.api#xmlName" => "description"}))
    InstanceNetworkInterfaceSpecification.add_member(:device_index, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'DeviceIndex', traits: {"aws.protocols#ec2QueryName" => "DeviceIndex", "smithy.api#documentation" => "<p>The position of the network interface in the attachment order. A primary network\n            interface has a device index of 0.</p>\n         <p>If you specify a network interface when launching an instance, you must specify the\n            device index.</p>", "smithy.api#xmlName" => "deviceIndex"}))
    InstanceNetworkInterfaceSpecification.add_member(:groups, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIdStringList, location_name: 'Groups', traits: {"smithy.api#documentation" => "<p>The IDs of the security groups for the network interface. Applies only if creating a\n            network interface when launching an instance.</p>", "smithy.api#xmlName" => "SecurityGroupId"}))
    InstanceNetworkInterfaceSpecification.add_member(:ipv6_address_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Ipv6AddressCount', traits: {"aws.protocols#ec2QueryName" => "Ipv6AddressCount", "smithy.api#documentation" => "<p>A number of IPv6 addresses to assign to the network interface. Amazon EC2 chooses the\n            IPv6 addresses from the range of the subnet. You cannot specify this option and the\n            option to assign specific IPv6 addresses in the same request. You can specify this\n            option if you've specified a minimum number of instances to launch.</p>", "smithy.api#xmlName" => "ipv6AddressCount"}))
    InstanceNetworkInterfaceSpecification.add_member(:ipv6_addresses, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceIpv6AddressList, location_name: 'Ipv6Addresses', traits: {"aws.protocols#ec2QueryName" => "Ipv6Addresses", "smithy.api#documentation" => "<p>The IPv6 addresses to assign to the network interface. You cannot specify this option\n            and the option to assign a number of IPv6 addresses in the same request. You cannot\n            specify this option if you've specified a minimum number of instances to launch.</p>", "smithy.api#xmlName" => "ipv6AddressesSet"}))
    InstanceNetworkInterfaceSpecification.add_member(:network_interface_id, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkInterfaceId, location_name: 'NetworkInterfaceId', traits: {"aws.protocols#ec2QueryName" => "NetworkInterfaceId", "smithy.api#documentation" => "<p>The ID of the network interface.</p>\n         <p>If you are creating a Spot Fleet, omit this parameter because you can’t specify a\n            network interface ID in a launch specification.</p>", "smithy.api#xmlName" => "networkInterfaceId"}))
    InstanceNetworkInterfaceSpecification.add_member(:private_ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PrivateIpAddress', traits: {"aws.protocols#ec2QueryName" => "PrivateIpAddress", "smithy.api#documentation" => "<p>The private IPv4 address of the network interface. Applies only if creating a network\n            interface when launching an instance. You cannot specify this option if you're launching\n            more than one instance in a <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_RunInstances.html\">RunInstances</a>\n            request.</p>", "smithy.api#xmlName" => "privateIpAddress"}))
    InstanceNetworkInterfaceSpecification.add_member(:private_ip_addresses, Smithy::Schema::Shapes::ShapeRef.new(shape: PrivateIpAddressSpecificationList, location_name: 'PrivateIpAddresses', traits: {"aws.protocols#ec2QueryName" => "PrivateIpAddresses", "smithy.api#documentation" => "<p>The private IPv4 addresses to assign to the network interface. Only one private IPv4\n            address can be designated as primary. You cannot specify this option if you're launching\n            more than one instance in a <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_RunInstances.html\">RunInstances</a>\n            request.</p>", "smithy.api#xmlName" => "privateIpAddressesSet"}))
    InstanceNetworkInterfaceSpecification.add_member(:secondary_private_ip_address_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'SecondaryPrivateIpAddressCount', traits: {"aws.protocols#ec2QueryName" => "SecondaryPrivateIpAddressCount", "smithy.api#documentation" => "<p>The number of secondary private IPv4 addresses. You can’t specify this parameter and\n            also specify a secondary private IP address using the <code>PrivateIpAddress</code>\n            parameter.</p>", "smithy.api#xmlName" => "secondaryPrivateIpAddressCount"}))
    InstanceNetworkInterfaceSpecification.add_member(:subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SubnetId', traits: {"aws.protocols#ec2QueryName" => "SubnetId", "smithy.api#documentation" => "<p>The ID of the subnet associated with the network interface. Applies only if creating a\n            network interface when launching an instance.</p>", "smithy.api#xmlName" => "subnetId"}))
    InstanceNetworkInterfaceSpecification.add_member(:associate_carrier_ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AssociateCarrierIpAddress', traits: {"smithy.api#documentation" => "<p>Indicates whether to assign a carrier IP address to the network interface.</p>\n         <p>You can only assign a carrier IP address to a network interface that is in a subnet in\n            a Wavelength Zone. For more information about carrier IP addresses, see <a href=\"https://docs.aws.amazon.com/wavelength/latest/developerguide/how-wavelengths-work.html#provider-owned-ip\">Carrier IP address</a> in the <i>Amazon Web Services Wavelength Developer\n                Guide</i>.</p>"}))
    InstanceNetworkInterfaceSpecification.add_member(:interface_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'InterfaceType', traits: {"smithy.api#documentation" => "<p>The type of network interface.</p>\n         <p>If you specify <code>efa-only</code>, do not assign any IP addresses to the network\n            interface. EFA-only network interfaces do not support IP addresses.</p>\n         <p>Valid values: <code>interface</code> | <code>efa</code> | <code>efa-only</code>\n         </p>"}))
    InstanceNetworkInterfaceSpecification.add_member(:network_card_index, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'NetworkCardIndex', traits: {"smithy.api#documentation" => "<p>The index of the network card. Some instance types support multiple network cards. The\n            primary network interface must be assigned to network card index 0. The default is\n            network card index 0.</p>\n         <p>If you are using <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_RequestSpotInstances.html\">RequestSpotInstances</a> to create Spot Instances, omit this parameter because\n            you can’t specify the network card index when using this API. To specify the network\n            card index, use <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_RunInstances.html\">RunInstances</a>.</p>"}))
    InstanceNetworkInterfaceSpecification.add_member(:ipv4_prefixes, Smithy::Schema::Shapes::ShapeRef.new(shape: Ipv4PrefixList, location_name: 'Ipv4Prefixes', traits: {"smithy.api#documentation" => "<p>The IPv4 delegated prefixes to be assigned to the network interface. You cannot use\n            this option if you use the <code>Ipv4PrefixCount</code> option.</p>", "smithy.api#xmlName" => "Ipv4Prefix"}))
    InstanceNetworkInterfaceSpecification.add_member(:ipv4_prefix_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Ipv4PrefixCount', traits: {"smithy.api#documentation" => "<p>The number of IPv4 delegated prefixes to be automatically assigned to the network\n            interface. You cannot use this option if you use the <code>Ipv4Prefix</code>\n            option.</p>"}))
    InstanceNetworkInterfaceSpecification.add_member(:ipv6_prefixes, Smithy::Schema::Shapes::ShapeRef.new(shape: Ipv6PrefixList, location_name: 'Ipv6Prefixes', traits: {"smithy.api#documentation" => "<p>The IPv6 delegated prefixes to be assigned to the network interface. You cannot use\n            this option if you use the <code>Ipv6PrefixCount</code> option.</p>", "smithy.api#xmlName" => "Ipv6Prefix"}))
    InstanceNetworkInterfaceSpecification.add_member(:ipv6_prefix_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Ipv6PrefixCount', traits: {"smithy.api#documentation" => "<p>The number of IPv6 delegated prefixes to be automatically assigned to the network\n            interface. You cannot use this option if you use the <code>Ipv6Prefix</code>\n            option.</p>"}))
    InstanceNetworkInterfaceSpecification.add_member(:primary_ipv6, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'PrimaryIpv6', traits: {"smithy.api#documentation" => "<p>The primary IPv6 address of the network interface. When you enable an IPv6 GUA address to be a primary IPv6, the first IPv6 GUA will be made the primary IPv6 address until the instance is terminated or the network interface is detached. For more information about primary IPv6 addresses, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_RunInstances.html\">RunInstances</a>.</p>"}))
    InstanceNetworkInterfaceSpecification.add_member(:ena_srd_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: EnaSrdSpecificationRequest, location_name: 'EnaSrdSpecification', traits: {"smithy.api#documentation" => "<p>Specifies the ENA Express settings for the network interface that's attached to\n            the instance.</p>"}))
    InstanceNetworkInterfaceSpecification.add_member(:connection_tracking_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectionTrackingSpecificationRequest, location_name: 'ConnectionTrackingSpecification', traits: {"smithy.api#documentation" => "<p>A security group connection tracking specification that enables you to set the timeout\n            for connection tracking on an Elastic network interface. For more information, see\n                <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/security-group-connection-tracking.html#connection-tracking-timeouts\">Connection tracking timeouts</a> in the\n            <i>Amazon EC2 User Guide</i>.</p>"}))
    InstanceNetworkInterfaceSpecification.add_member(:ena_queue_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'EnaQueueCount', traits: {"smithy.api#documentation" => "<p>The number of ENA queues to be created with the instance.</p>"}))
    InstanceNetworkInterfaceSpecification.type = Types::InstanceNetworkInterfaceSpecification
    InstanceNetworkInterfaceSpecificationList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceNetworkInterfaceSpecification, traits: {"smithy.api#xmlName" => "item"})
    InstanceNetworkPerformanceOptions.add_member(:bandwidth_weighting, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceBandwidthWeighting, location_name: 'BandwidthWeighting', traits: {"aws.protocols#ec2QueryName" => "BandwidthWeighting", "smithy.api#documentation" => "<p>When you configure network bandwidth weighting, you can boost your baseline bandwidth for either \n    \t\tnetworking or EBS by up to 25%. The total available baseline bandwidth for your instance remains \n    \t\tthe same. The default option uses the standard bandwidth configuration for your instance type.</p>", "smithy.api#xmlName" => "bandwidthWeighting"}))
    InstanceNetworkPerformanceOptions.type = Types::InstanceNetworkPerformanceOptions
    InstanceNetworkPerformanceOptionsRequest.add_member(:bandwidth_weighting, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceBandwidthWeighting, location_name: 'BandwidthWeighting', traits: {"smithy.api#documentation" => "<p>Specify the bandwidth weighting option to boost the associated type of baseline bandwidth, \n    \t\tas follows:</p>\n         <dl>\n            <dt>default</dt>\n            <dd>\n               <p>This option uses the standard bandwidth configuration for your instance type.</p>\n            </dd>\n            <dt>vpc-1</dt>\n            <dd>\n               <p>This option boosts your networking baseline bandwidth and reduces your EBS baseline \n    \t\t\t\t\tbandwidth.</p>\n            </dd>\n            <dt>ebs-1</dt>\n            <dd>\n               <p>This option boosts your EBS baseline bandwidth and reduces your networking baseline \n    \t\t\t\t\tbandwidth.</p>\n            </dd>\n         </dl>"}))
    InstanceNetworkPerformanceOptionsRequest.type = Types::InstanceNetworkPerformanceOptionsRequest
    InstancePrivateIpAddress.add_member(:association, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceNetworkInterfaceAssociation, location_name: 'Association', traits: {"aws.protocols#ec2QueryName" => "Association", "smithy.api#documentation" => "<p>The association information for an Elastic IP address for the network\n            interface.</p>", "smithy.api#xmlName" => "association"}))
    InstancePrivateIpAddress.add_member(:primary, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'Primary', traits: {"aws.protocols#ec2QueryName" => "Primary", "smithy.api#documentation" => "<p>Indicates whether this IPv4 address is the primary private IP address of the network\n            interface.</p>", "smithy.api#xmlName" => "primary"}))
    InstancePrivateIpAddress.add_member(:private_dns_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PrivateDnsName', traits: {"aws.protocols#ec2QueryName" => "PrivateDnsName", "smithy.api#documentation" => "<p>The private IPv4 DNS name.</p>", "smithy.api#xmlName" => "privateDnsName"}))
    InstancePrivateIpAddress.add_member(:private_ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PrivateIpAddress', traits: {"aws.protocols#ec2QueryName" => "PrivateIpAddress", "smithy.api#documentation" => "<p>The private IPv4 address of the network interface.</p>", "smithy.api#xmlName" => "privateIpAddress"}))
    InstancePrivateIpAddress.type = Types::InstancePrivateIpAddress
    InstancePrivateIpAddressList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: InstancePrivateIpAddress, traits: {"smithy.api#xmlName" => "item"})
    InstanceRebootMigrationState.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'disabled', traits: {"smithy.api#enumValue" => "disabled"}))
    InstanceRebootMigrationState.add_member(:default, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'default', traits: {"smithy.api#enumValue" => "default"}))
    InstanceRequirements.add_member(:v_cpu_count, Smithy::Schema::Shapes::ShapeRef.new(shape: VCpuCountRange, location_name: 'VCpuCount', traits: {"aws.protocols#ec2QueryName" => "VCpuCount", "smithy.api#documentation" => "<p>The minimum and maximum number of vCPUs.</p>", "smithy.api#xmlName" => "vCpuCount"}))
    InstanceRequirements.add_member(:memory_mi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: MemoryMiB, location_name: 'MemoryMiB', traits: {"aws.protocols#ec2QueryName" => "MemoryMiB", "smithy.api#documentation" => "<p>The minimum and maximum amount of memory, in MiB.</p>", "smithy.api#xmlName" => "memoryMiB"}))
    InstanceRequirements.add_member(:cpu_manufacturers, Smithy::Schema::Shapes::ShapeRef.new(shape: CpuManufacturerSet, location_name: 'CpuManufacturers', traits: {"aws.protocols#ec2QueryName" => "CpuManufacturerSet", "smithy.api#documentation" => "<p>The CPU manufacturers to include.</p>\n         <ul>\n            <li>\n               <p>For instance types with Intel CPUs, specify <code>intel</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with AMD CPUs, specify <code>amd</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Amazon Web Services CPUs, specify <code>amazon-web-services</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Apple CPUs, specify <code>apple</code>.</p>\n            </li>\n         </ul>\n         <note>\n            <p>Don't confuse the CPU manufacturer with the CPU architecture. Instances will \n         be launched with a compatible CPU architecture based on the Amazon Machine Image (AMI) that you \n         specify in your launch template.</p>\n         </note>\n         <p>Default: Any manufacturer</p>", "smithy.api#xmlName" => "cpuManufacturerSet"}))
    InstanceRequirements.add_member(:memory_gi_b_per_v_cpu, Smithy::Schema::Shapes::ShapeRef.new(shape: MemoryGiBPerVCpu, location_name: 'MemoryGiBPerVCpu', traits: {"aws.protocols#ec2QueryName" => "MemoryGiBPerVCpu", "smithy.api#documentation" => "<p>The minimum and maximum amount of memory per vCPU, in GiB.</p>\n         <p>Default: No minimum or maximum limits</p>", "smithy.api#xmlName" => "memoryGiBPerVCpu"}))
    InstanceRequirements.add_member(:excluded_instance_types, Smithy::Schema::Shapes::ShapeRef.new(shape: ExcludedInstanceTypeSet, location_name: 'ExcludedInstanceTypes', traits: {"aws.protocols#ec2QueryName" => "ExcludedInstanceTypeSet", "smithy.api#documentation" => "<p>The instance types to exclude.</p>\n         <p>You can use strings with one or more wild cards, represented by\n      an asterisk (<code>*</code>), to exclude an instance type, size, or generation. The\n      following are examples: <code>m5.8xlarge</code>, <code>c5*.*</code>, <code>m5a.*</code>,\n      <code>r*</code>, <code>*3*</code>.</p>\n         <p>For example, if you specify <code>c5*</code>,Amazon EC2 will exclude the entire C5 instance\n      family, which includes all C5a and C5n instance types. If you specify\n      <code>m5a.*</code>, Amazon EC2 will exclude all the M5a instance types, but not the M5n\n      instance types.</p>\n         <note>\n            <p>If you specify <code>ExcludedInstanceTypes</code>, you can't specify <code>AllowedInstanceTypes</code>.</p>\n         </note>\n         <p>Default: No excluded instance types</p>", "smithy.api#xmlName" => "excludedInstanceTypeSet"}))
    InstanceRequirements.add_member(:instance_generations, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceGenerationSet, location_name: 'InstanceGenerations', traits: {"aws.protocols#ec2QueryName" => "InstanceGenerationSet", "smithy.api#documentation" => "<p>Indicates whether current or previous generation instance types are included. The\n      current generation instance types are recommended for use. Current generation instance types are\n      typically the latest two to three generations in each instance family. For more\n      information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html\">Instance types</a> in the\n      <i>Amazon EC2 User Guide</i>.</p>\n         <p>For current generation instance types, specify <code>current</code>.</p>\n         <p>For previous generation instance types, specify <code>previous</code>.</p>\n         <p>Default: Current and previous generation instance types</p>", "smithy.api#xmlName" => "instanceGenerationSet"}))
    InstanceRequirements.add_member(:spot_max_price_percentage_over_lowest_price, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'SpotMaxPricePercentageOverLowestPrice', traits: {"aws.protocols#ec2QueryName" => "SpotMaxPricePercentageOverLowestPrice", "smithy.api#documentation" => "<p>[Price protection] The price protection threshold for Spot Instances, as a percentage higher than\n         an identified Spot price. The identified Spot price is the Spot price of the lowest priced\n         current generation C, M, or R instance type with your specified attributes. If no current\n         generation C, M, or R instance type matches your attributes, then the identified Spot price\n         is from the lowest priced current generation instance types, and failing that, from the\n         lowest priced previous generation instance types that match your attributes. When Amazon EC2\n         selects instance types with your attributes, it will exclude instance types whose Spot\n         price exceeds your specified threshold.</p>\n         <p>The parameter accepts an integer, which Amazon EC2 interprets as a percentage.</p>\n         <p>If you set <code>TargetCapacityUnitType</code> to <code>vcpu</code> or\n            <code>memory-mib</code>, the price protection threshold is applied based on the per-vCPU\n         or per-memory price instead of the per-instance price.</p>\n         <p>This parameter is not supported for <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetSpotPlacementScores.html\">GetSpotPlacementScores</a> and <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetInstanceTypesFromInstanceRequirements.html\">GetInstanceTypesFromInstanceRequirements</a>.</p>\n         <note>\n            <p>Only one of <code>SpotMaxPricePercentageOverLowestPrice</code> or\n               <code>MaxSpotPriceAsPercentageOfOptimalOnDemandPrice</code> can be specified. If you\n            don't specify either, Amazon EC2 will automatically apply optimal price protection to\n            consistently select from a wide range of instance types. To indicate no price protection\n            threshold for Spot Instances, meaning you want to consider all instance types that match your\n            attributes, include one of these parameters and specify a high value, such as\n               <code>999999</code>.</p>\n         </note>\n         <p>Default: <code>100</code>\n         </p>", "smithy.api#xmlName" => "spotMaxPricePercentageOverLowestPrice"}))
    InstanceRequirements.add_member(:on_demand_max_price_percentage_over_lowest_price, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'OnDemandMaxPricePercentageOverLowestPrice', traits: {"aws.protocols#ec2QueryName" => "OnDemandMaxPricePercentageOverLowestPrice", "smithy.api#documentation" => "<p>[Price protection] The price protection threshold for On-Demand Instances, as a percentage higher\n         than an identified On-Demand price. The identified On-Demand price is the price of the\n         lowest priced current generation C, M, or R instance type with your specified attributes.\n         When Amazon EC2 selects instance types with your attributes, it will exclude instance types\n         whose price exceeds your specified threshold.</p>\n         <p>The parameter accepts an integer, which Amazon EC2 interprets as a percentage.</p>\n         <p>To turn off price protection, specify a high value, such as <code>999999</code>.</p>\n         <p>This parameter is not supported for <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetSpotPlacementScores.html\">GetSpotPlacementScores</a> and <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetInstanceTypesFromInstanceRequirements.html\">GetInstanceTypesFromInstanceRequirements</a>.</p>\n         <note>\n            <p>If you set <code>TargetCapacityUnitType</code> to <code>vcpu</code> or\n         <code>memory-mib</code>, the price protection threshold is applied based on the\n         per-vCPU or per-memory price instead of the per-instance price.</p>\n         </note>\n         <p>Default: <code>20</code>\n         </p>", "smithy.api#xmlName" => "onDemandMaxPricePercentageOverLowestPrice"}))
    InstanceRequirements.add_member(:bare_metal, Smithy::Schema::Shapes::ShapeRef.new(shape: BareMetal, location_name: 'BareMetal', traits: {"aws.protocols#ec2QueryName" => "BareMetal", "smithy.api#documentation" => "<p>Indicates whether bare metal instance types must be included, excluded, or required.</p>\n         <ul>\n            <li>\n               <p>To include bare metal instance types, specify <code>included</code>.</p>\n            </li>\n            <li>\n               <p>To require only bare metal instance types, specify <code>required</code>.</p>\n            </li>\n            <li>\n               <p>To exclude bare metal instance types, specify <code>excluded</code>.</p>\n            </li>\n         </ul>\n         <p>Default: <code>excluded</code>\n         </p>", "smithy.api#xmlName" => "bareMetal"}))
    InstanceRequirements.add_member(:burstable_performance, Smithy::Schema::Shapes::ShapeRef.new(shape: BurstablePerformance, location_name: 'BurstablePerformance', traits: {"aws.protocols#ec2QueryName" => "BurstablePerformance", "smithy.api#documentation" => "<p>Indicates whether burstable performance T instance types are included, excluded, or required. For more information, see \n      <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/burstable-performance-instances.html\">Burstable performance instances</a>.</p>\n         <ul>\n            <li>\n               <p>To include burstable performance instance types, specify <code>included</code>.</p>\n            </li>\n            <li>\n               <p>To require only burstable performance instance types, specify <code>required</code>.</p>\n            </li>\n            <li>\n               <p>To exclude burstable performance instance types, specify <code>excluded</code>.</p>\n            </li>\n         </ul>\n         <p>Default: <code>excluded</code>\n         </p>", "smithy.api#xmlName" => "burstablePerformance"}))
    InstanceRequirements.add_member(:require_hibernate_support, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'RequireHibernateSupport', traits: {"aws.protocols#ec2QueryName" => "RequireHibernateSupport", "smithy.api#documentation" => "<p>Indicates whether instance types must support hibernation for On-Demand\n         Instances.</p>\n         <p>This parameter is not supported for <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetSpotPlacementScores.html\">GetSpotPlacementScores</a>.</p>\n         <p>Default: <code>false</code>\n         </p>", "smithy.api#xmlName" => "requireHibernateSupport"}))
    InstanceRequirements.add_member(:network_interface_count, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkInterfaceCount, location_name: 'NetworkInterfaceCount', traits: {"aws.protocols#ec2QueryName" => "NetworkInterfaceCount", "smithy.api#documentation" => "<p>The minimum and maximum number of network interfaces.</p>\n         <p>Default: No minimum or maximum limits</p>", "smithy.api#xmlName" => "networkInterfaceCount"}))
    InstanceRequirements.add_member(:local_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: LocalStorage, location_name: 'LocalStorage', traits: {"aws.protocols#ec2QueryName" => "LocalStorage", "smithy.api#documentation" => "<p>Indicates whether instance types with instance store volumes are included, excluded, or required. For more information,\n            <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/InstanceStorage.html\">Amazon\n            EC2 instance store</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <ul>\n            <li>\n               <p>To include instance types with instance store volumes, specify\n               <code>included</code>.</p>\n            </li>\n            <li>\n               <p>To require only instance types with instance store volumes, specify\n                  <code>required</code>.</p>\n            </li>\n            <li>\n               <p>To exclude instance types with instance store volumes, specify\n               <code>excluded</code>.</p>\n            </li>\n         </ul>\n         <p>Default: <code>included</code>\n         </p>", "smithy.api#xmlName" => "localStorage"}))
    InstanceRequirements.add_member(:local_storage_types, Smithy::Schema::Shapes::ShapeRef.new(shape: LocalStorageTypeSet, location_name: 'LocalStorageTypes', traits: {"aws.protocols#ec2QueryName" => "LocalStorageTypeSet", "smithy.api#documentation" => "<p>The type of local storage that is required.</p>\n         <ul>\n            <li>\n               <p>For instance types with hard disk drive (HDD) storage, specify <code>hdd</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with solid state drive (SSD) storage, specify\n               <code>ssd</code>.</p>\n            </li>\n         </ul>\n         <p>Default: <code>hdd</code> and <code>ssd</code>\n         </p>", "smithy.api#xmlName" => "localStorageTypeSet"}))
    InstanceRequirements.add_member(:total_local_storage_gb, Smithy::Schema::Shapes::ShapeRef.new(shape: TotalLocalStorageGB, location_name: 'TotalLocalStorageGB', traits: {"aws.protocols#ec2QueryName" => "TotalLocalStorageGB", "smithy.api#documentation" => "<p>The minimum and maximum amount of total local storage, in GB.</p>\n         <p>Default: No minimum or maximum limits</p>", "smithy.api#xmlName" => "totalLocalStorageGB"}))
    InstanceRequirements.add_member(:baseline_ebs_bandwidth_mbps, Smithy::Schema::Shapes::ShapeRef.new(shape: BaselineEbsBandwidthMbps, location_name: 'BaselineEbsBandwidthMbps', traits: {"aws.protocols#ec2QueryName" => "BaselineEbsBandwidthMbps", "smithy.api#documentation" => "<p>The minimum and maximum baseline bandwidth to Amazon EBS, in Mbps. For more information, see\n            <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ebs-optimized.html\">Amazon\n            EBS–optimized instances</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <p>Default: No minimum or maximum limits</p>", "smithy.api#xmlName" => "baselineEbsBandwidthMbps"}))
    InstanceRequirements.add_member(:accelerator_types, Smithy::Schema::Shapes::ShapeRef.new(shape: AcceleratorTypeSet, location_name: 'AcceleratorTypes', traits: {"aws.protocols#ec2QueryName" => "AcceleratorTypeSet", "smithy.api#documentation" => "<p>The accelerator types that must be on the instance type.</p>\n         <ul>\n            <li>\n               <p>For instance types with FPGA accelerators, specify <code>fpga</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with GPU accelerators, specify <code>gpu</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Inference accelerators, specify <code>inference</code>.</p>\n            </li>\n         </ul>\n         <p>Default: Any accelerator type</p>", "smithy.api#xmlName" => "acceleratorTypeSet"}))
    InstanceRequirements.add_member(:accelerator_count, Smithy::Schema::Shapes::ShapeRef.new(shape: AcceleratorCount, location_name: 'AcceleratorCount', traits: {"aws.protocols#ec2QueryName" => "AcceleratorCount", "smithy.api#documentation" => "<p>The minimum and maximum number of accelerators (GPUs, FPGAs, or Amazon Web Services Inferentia chips) on\n         an instance.</p>\n         <p>To exclude accelerator-enabled instance types, set <code>Max</code> to <code>0</code>.</p>\n         <p>Default: No minimum or maximum limits</p>", "smithy.api#xmlName" => "acceleratorCount"}))
    InstanceRequirements.add_member(:accelerator_manufacturers, Smithy::Schema::Shapes::ShapeRef.new(shape: AcceleratorManufacturerSet, location_name: 'AcceleratorManufacturers', traits: {"aws.protocols#ec2QueryName" => "AcceleratorManufacturerSet", "smithy.api#documentation" => "<p>Indicates whether instance types must have accelerators by specific manufacturers.</p>\n         <ul>\n            <li>\n               <p>For instance types with Amazon Web Services devices, specify <code>amazon-web-services</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with AMD devices, specify <code>amd</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Habana devices, specify <code>habana</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA devices, specify <code>nvidia</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Xilinx devices, specify <code>xilinx</code>.</p>\n            </li>\n         </ul>\n         <p>Default: Any manufacturer</p>", "smithy.api#xmlName" => "acceleratorManufacturerSet"}))
    InstanceRequirements.add_member(:accelerator_names, Smithy::Schema::Shapes::ShapeRef.new(shape: AcceleratorNameSet, location_name: 'AcceleratorNames', traits: {"aws.protocols#ec2QueryName" => "AcceleratorNameSet", "smithy.api#documentation" => "<p>The accelerators that must be on the instance type.</p>\n         <ul>\n            <li>\n               <p>For instance types with NVIDIA A10G GPUs, specify <code>a10g</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA A100 GPUs, specify <code>a100</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA H100 GPUs, specify <code>h100</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Amazon Web Services Inferentia chips, specify <code>inferentia</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA GRID K520 GPUs, specify <code>k520</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA K80 GPUs, specify <code>k80</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA M60 GPUs, specify <code>m60</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with AMD Radeon Pro V520 GPUs, specify <code>radeon-pro-v520</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA T4 GPUs, specify <code>t4</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA T4G GPUs, specify <code>t4g</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Xilinx VU9P FPGAs, specify <code>vu9p</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA V100 GPUs, specify <code>v100</code>.</p>\n            </li>\n         </ul>\n         <p>Default: Any accelerator</p>", "smithy.api#xmlName" => "acceleratorNameSet"}))
    InstanceRequirements.add_member(:accelerator_total_memory_mi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: AcceleratorTotalMemoryMiB, location_name: 'AcceleratorTotalMemoryMiB', traits: {"aws.protocols#ec2QueryName" => "AcceleratorTotalMemoryMiB", "smithy.api#documentation" => "<p>The minimum and maximum amount of total accelerator memory, in MiB.</p>\n         <p>Default: No minimum or maximum limits</p>", "smithy.api#xmlName" => "acceleratorTotalMemoryMiB"}))
    InstanceRequirements.add_member(:network_bandwidth_gbps, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkBandwidthGbps, location_name: 'NetworkBandwidthGbps', traits: {"aws.protocols#ec2QueryName" => "NetworkBandwidthGbps", "smithy.api#documentation" => "<p>The minimum and maximum amount of network bandwidth, in gigabits per second (Gbps).</p>\n         <p>Default: No minimum or maximum limits</p>", "smithy.api#xmlName" => "networkBandwidthGbps"}))
    InstanceRequirements.add_member(:allowed_instance_types, Smithy::Schema::Shapes::ShapeRef.new(shape: AllowedInstanceTypeSet, location_name: 'AllowedInstanceTypes', traits: {"aws.protocols#ec2QueryName" => "AllowedInstanceTypeSet", "smithy.api#documentation" => "<p>The instance types to apply your specified attributes against. All other instance types \n         are ignored, even if they match your specified attributes.</p>\n         <p>You can use strings with one or more wild cards, represented by\n         an asterisk (<code>*</code>), to allow an instance type, size, or generation. The\n         following are examples: <code>m5.8xlarge</code>, <code>c5*.*</code>, <code>m5a.*</code>,\n         <code>r*</code>, <code>*3*</code>.</p>\n         <p>For example, if you specify <code>c5*</code>,Amazon EC2 will allow the entire C5 instance\n         family, which includes all C5a and C5n instance types. If you specify\n         <code>m5a.*</code>, Amazon EC2 will allow all the M5a instance types, but not the M5n\n         instance types.</p>\n         <note>\n            <p>If you specify <code>AllowedInstanceTypes</code>, you can't specify <code>ExcludedInstanceTypes</code>.</p>\n         </note>\n         <p>Default: All instance types</p>", "smithy.api#xmlName" => "allowedInstanceTypeSet"}))
    InstanceRequirements.add_member(:max_spot_price_as_percentage_of_optimal_on_demand_price, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'MaxSpotPriceAsPercentageOfOptimalOnDemandPrice', traits: {"aws.protocols#ec2QueryName" => "MaxSpotPriceAsPercentageOfOptimalOnDemandPrice", "smithy.api#documentation" => "<p>[Price protection] The price protection threshold for Spot Instances, as a percentage of an\n         identified On-Demand price. The identified On-Demand price is the price of the lowest\n         priced current generation C, M, or R instance type with your specified attributes. If no\n         current generation C, M, or R instance type matches your attributes, then the identified\n         price is from the lowest priced current generation instance types, and failing that, from\n         the lowest priced previous generation instance types that match your attributes. When Amazon EC2\n         selects instance types with your attributes, it will exclude instance types whose price\n         exceeds your specified threshold.</p>\n         <p>The parameter accepts an integer, which Amazon EC2 interprets as a percentage.</p>\n         <p>If you set <code>TargetCapacityUnitType</code> to <code>vcpu</code> or\n            <code>memory-mib</code>, the price protection threshold is based on the per vCPU or per\n         memory price instead of the per instance price.</p>\n         <note>\n            <p>Only one of <code>SpotMaxPricePercentageOverLowestPrice</code> or\n               <code>MaxSpotPriceAsPercentageOfOptimalOnDemandPrice</code> can be specified. If you\n            don't specify either, Amazon EC2 will automatically apply optimal price protection to\n            consistently select from a wide range of instance types. To indicate no price protection\n            threshold for Spot Instances, meaning you want to consider all instance types that match your\n            attributes, include one of these parameters and specify a high value, such as\n               <code>999999</code>.</p>\n         </note>", "smithy.api#xmlName" => "maxSpotPriceAsPercentageOfOptimalOnDemandPrice"}))
    InstanceRequirements.add_member(:baseline_performance_factors, Smithy::Schema::Shapes::ShapeRef.new(shape: BaselinePerformanceFactors, location_name: 'BaselinePerformanceFactors', traits: {"aws.protocols#ec2QueryName" => "BaselinePerformanceFactors", "smithy.api#documentation" => "<p>The baseline performance to consider, using an instance family as a baseline reference.\n         The instance family establishes the lowest acceptable level of performance. Amazon EC2 uses this\n         baseline to guide instance type selection, but there is no guarantee that the selected\n         instance types will always exceed the baseline for every application. Currently, this\n         parameter only supports CPU performance as a baseline performance factor. For more\n         information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-fleet-attribute-based-instance-type-selection.html#ec2fleet-abis-performance-protection\">Performance protection</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "baselinePerformanceFactors"}))
    InstanceRequirements.type = Types::InstanceRequirements
    InstanceRequirementsRequest.add_member(:v_cpu_count, Smithy::Schema::Shapes::ShapeRef.new(shape: VCpuCountRangeRequest, location_name: 'VCpuCount', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The minimum and maximum number of vCPUs.</p>", "smithy.api#required" => {}}))
    InstanceRequirementsRequest.add_member(:memory_mi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: MemoryMiBRequest, location_name: 'MemoryMiB', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The minimum and maximum amount of memory, in MiB.</p>", "smithy.api#required" => {}}))
    InstanceRequirementsRequest.add_member(:cpu_manufacturers, Smithy::Schema::Shapes::ShapeRef.new(shape: CpuManufacturerSet, location_name: 'CpuManufacturers', traits: {"smithy.api#documentation" => "<p>The CPU manufacturers to include.</p>\n         <ul>\n            <li>\n               <p>For instance types with Intel CPUs, specify <code>intel</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with AMD CPUs, specify <code>amd</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Amazon Web Services CPUs, specify <code>amazon-web-services</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Apple CPUs, specify <code>apple</code>.</p>\n            </li>\n         </ul>\n         <note>\n            <p>Don't confuse the CPU manufacturer with the CPU architecture. Instances will \n         be launched with a compatible CPU architecture based on the Amazon Machine Image (AMI) that you \n         specify in your launch template.</p>\n         </note>\n         <p>Default: Any manufacturer</p>", "smithy.api#xmlName" => "CpuManufacturer"}))
    InstanceRequirementsRequest.add_member(:memory_gi_b_per_v_cpu, Smithy::Schema::Shapes::ShapeRef.new(shape: MemoryGiBPerVCpuRequest, location_name: 'MemoryGiBPerVCpu', traits: {"smithy.api#documentation" => "<p>The minimum and maximum amount of memory per vCPU, in GiB.</p>\n         <p>Default: No minimum or maximum limits</p>"}))
    InstanceRequirementsRequest.add_member(:excluded_instance_types, Smithy::Schema::Shapes::ShapeRef.new(shape: ExcludedInstanceTypeSet, location_name: 'ExcludedInstanceTypes', traits: {"smithy.api#documentation" => "<p>The instance types to exclude.</p>\n         <p>You can use strings with one or more wild cards, represented by\n         an asterisk (<code>*</code>), to exclude an instance family, type, size, or generation. The\n         following are examples: <code>m5.8xlarge</code>, <code>c5*.*</code>, <code>m5a.*</code>,\n            <code>r*</code>, <code>*3*</code>.</p>\n         <p>For example, if you specify <code>c5*</code>,Amazon EC2 will exclude the entire C5 instance\n      family, which includes all C5a and C5n instance types. If you specify\n      <code>m5a.*</code>, Amazon EC2 will exclude all the M5a instance types, but not the M5n\n      instance types.</p>\n         <note>\n            <p>If you specify <code>ExcludedInstanceTypes</code>, you can't specify <code>AllowedInstanceTypes</code>.</p>\n         </note>\n         <p>Default: No excluded instance types</p>", "smithy.api#xmlName" => "ExcludedInstanceType"}))
    InstanceRequirementsRequest.add_member(:instance_generations, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceGenerationSet, location_name: 'InstanceGenerations', traits: {"smithy.api#documentation" => "<p>Indicates whether current or previous generation instance types are included. The\n      current generation instance types are recommended for use. Current generation instance types are\n      typically the latest two to three generations in each instance family. For more\n      information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html\">Instance types</a> in the\n      <i>Amazon EC2 User Guide</i>.</p>\n         <p>For current generation instance types, specify <code>current</code>.</p>\n         <p>For previous generation instance types, specify <code>previous</code>.</p>\n         <p>Default: Current and previous generation instance types</p>", "smithy.api#xmlName" => "InstanceGeneration"}))
    InstanceRequirementsRequest.add_member(:spot_max_price_percentage_over_lowest_price, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'SpotMaxPricePercentageOverLowestPrice', traits: {"smithy.api#documentation" => "<p>[Price protection] The price protection threshold for Spot Instances, as a percentage higher than\n         an identified Spot price. The identified Spot price is the Spot price of the lowest priced\n         current generation C, M, or R instance type with your specified attributes. If no current\n         generation C, M, or R instance type matches your attributes, then the identified Spot price\n         is from the lowest priced current generation instance types, and failing that, from the\n         lowest priced previous generation instance types that match your attributes. When Amazon EC2\n         selects instance types with your attributes, it will exclude instance types whose Spot\n         price exceeds your specified threshold.</p>\n         <p>The parameter accepts an integer, which Amazon EC2 interprets as a percentage.</p>\n         <p>If you set <code>TargetCapacityUnitType</code> to <code>vcpu</code> or\n         <code>memory-mib</code>, the price protection threshold is applied based on the\n         per-vCPU or per-memory price instead of the per-instance price.</p>\n         <p>This parameter is not supported for <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetSpotPlacementScores.html\">GetSpotPlacementScores</a> and <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetInstanceTypesFromInstanceRequirements.html\">GetInstanceTypesFromInstanceRequirements</a>.</p>\n         <note>\n            <p>Only one of <code>SpotMaxPricePercentageOverLowestPrice</code> or\n               <code>MaxSpotPriceAsPercentageOfOptimalOnDemandPrice</code> can be specified. If you\n            don't specify either, Amazon EC2 will automatically apply optimal price protection to\n            consistently select from a wide range of instance types. To indicate no price protection\n            threshold for Spot Instances, meaning you want to consider all instance types that match your\n            attributes, include one of these parameters and specify a high value, such as\n               <code>999999</code>.</p>\n         </note>\n         <p>Default: <code>100</code>\n         </p>"}))
    InstanceRequirementsRequest.add_member(:on_demand_max_price_percentage_over_lowest_price, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'OnDemandMaxPricePercentageOverLowestPrice', traits: {"smithy.api#documentation" => "<p>[Price protection] The price protection threshold for On-Demand Instances, as a percentage higher than\n         an identified On-Demand price. The identified On-Demand price is the price of the lowest\n         priced current generation C, M, or R instance type with your specified attributes. When\n         Amazon EC2 selects instance types with your attributes, it will exclude instance types whose\n         price exceeds your specified threshold.</p>\n         <p>The parameter accepts an integer, which Amazon EC2 interprets as a percentage.</p>\n         <p>To indicate no price protection threshold, specify a high value, such as\n            <code>999999</code>.</p>\n         <p>This parameter is not supported for <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetSpotPlacementScores.html\">GetSpotPlacementScores</a> and <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetInstanceTypesFromInstanceRequirements.html\">GetInstanceTypesFromInstanceRequirements</a>.</p>\n         <note>\n            <p>If you set <code>TargetCapacityUnitType</code> to <code>vcpu</code> or\n         <code>memory-mib</code>, the price protection threshold is applied based on the\n         per-vCPU or per-memory price instead of the per-instance price.</p>\n         </note>\n         <p>Default: <code>20</code>\n         </p>"}))
    InstanceRequirementsRequest.add_member(:bare_metal, Smithy::Schema::Shapes::ShapeRef.new(shape: BareMetal, location_name: 'BareMetal', traits: {"smithy.api#documentation" => "<p>Indicates whether bare metal instance types must be included, excluded, or required.</p>\n         <ul>\n            <li>\n               <p>To include bare metal instance types, specify <code>included</code>.</p>\n            </li>\n            <li>\n               <p>To require only bare metal instance types, specify <code>required</code>.</p>\n            </li>\n            <li>\n               <p>To exclude bare metal instance types, specify <code>excluded</code>.</p>\n            </li>\n         </ul>\n         <p>Default: <code>excluded</code>\n         </p>"}))
    InstanceRequirementsRequest.add_member(:burstable_performance, Smithy::Schema::Shapes::ShapeRef.new(shape: BurstablePerformance, location_name: 'BurstablePerformance', traits: {"smithy.api#documentation" => "<p>Indicates whether burstable performance T instance types are included, excluded, or required. For more information, see \n      <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/burstable-performance-instances.html\">Burstable performance instances</a>.</p>\n         <ul>\n            <li>\n               <p>To include burstable performance instance types, specify <code>included</code>.</p>\n            </li>\n            <li>\n               <p>To require only burstable performance instance types, specify <code>required</code>.</p>\n            </li>\n            <li>\n               <p>To exclude burstable performance instance types, specify <code>excluded</code>.</p>\n            </li>\n         </ul>\n         <p>Default: <code>excluded</code>\n         </p>"}))
    InstanceRequirementsRequest.add_member(:require_hibernate_support, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'RequireHibernateSupport', traits: {"smithy.api#documentation" => "<p>Indicates whether instance types must support hibernation for On-Demand Instances.</p>\n         <p>This parameter is not supported for <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetSpotPlacementScores.html\">GetSpotPlacementScores</a>.</p>\n         <p>Default: <code>false</code>\n         </p>"}))
    InstanceRequirementsRequest.add_member(:network_interface_count, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkInterfaceCountRequest, location_name: 'NetworkInterfaceCount', traits: {"smithy.api#documentation" => "<p>The minimum and maximum number of network interfaces.</p>\n         <p>Default: No minimum or maximum limits</p>"}))
    InstanceRequirementsRequest.add_member(:local_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: LocalStorage, location_name: 'LocalStorage', traits: {"smithy.api#documentation" => "<p>Indicates whether instance types with instance store volumes are included, excluded, or required. For more information,\n      <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/InstanceStorage.html\">Amazon\n         EC2 instance store</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <ul>\n            <li>\n               <p>To include instance types with instance store volumes, specify\n                  <code>included</code>.</p>\n            </li>\n            <li>\n               <p>To require only instance types with instance store volumes, specify\n                  <code>required</code>.</p>\n            </li>\n            <li>\n               <p>To exclude instance types with instance store volumes, specify\n                  <code>excluded</code>.</p>\n            </li>\n         </ul>\n         <p>Default: <code>included</code>\n         </p>"}))
    InstanceRequirementsRequest.add_member(:local_storage_types, Smithy::Schema::Shapes::ShapeRef.new(shape: LocalStorageTypeSet, location_name: 'LocalStorageTypes', traits: {"smithy.api#documentation" => "<p>The type of local storage that is required.</p>\n         <ul>\n            <li>\n               <p>For instance types with hard disk drive (HDD) storage, specify <code>hdd</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with solid state drive (SSD) storage, specify\n               <code>ssd</code>.</p>\n            </li>\n         </ul>\n         <p>Default: <code>hdd</code> and <code>ssd</code>\n         </p>", "smithy.api#xmlName" => "LocalStorageType"}))
    InstanceRequirementsRequest.add_member(:total_local_storage_gb, Smithy::Schema::Shapes::ShapeRef.new(shape: TotalLocalStorageGBRequest, location_name: 'TotalLocalStorageGB', traits: {"smithy.api#documentation" => "<p>The minimum and maximum amount of total local storage, in GB.</p>\n         <p>Default: No minimum or maximum limits</p>"}))
    InstanceRequirementsRequest.add_member(:baseline_ebs_bandwidth_mbps, Smithy::Schema::Shapes::ShapeRef.new(shape: BaselineEbsBandwidthMbpsRequest, location_name: 'BaselineEbsBandwidthMbps', traits: {"smithy.api#documentation" => "<p>The minimum and maximum baseline bandwidth to Amazon EBS, in Mbps. For more information, see\n            <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ebs-optimized.html\">Amazon\n            EBS–optimized instances</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <p>Default: No minimum or maximum limits</p>"}))
    InstanceRequirementsRequest.add_member(:accelerator_types, Smithy::Schema::Shapes::ShapeRef.new(shape: AcceleratorTypeSet, location_name: 'AcceleratorTypes', traits: {"smithy.api#documentation" => "<p>The accelerator types that must be on the instance type.</p>\n         <ul>\n            <li>\n               <p>For instance types with FPGA accelerators, specify <code>fpga</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with GPU accelerators, specify <code>gpu</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Inference accelerators, specify <code>inference</code>.</p>\n            </li>\n         </ul>\n         <p>Default: Any accelerator type</p>", "smithy.api#xmlName" => "AcceleratorType"}))
    InstanceRequirementsRequest.add_member(:accelerator_count, Smithy::Schema::Shapes::ShapeRef.new(shape: AcceleratorCountRequest, location_name: 'AcceleratorCount', traits: {"smithy.api#documentation" => "<p>The minimum and maximum number of accelerators (GPUs, FPGAs, or Amazon Web Services Inferentia chips) on\n         an instance.</p>\n         <p>To exclude accelerator-enabled instance types, set <code>Max</code> to <code>0</code>.</p>\n         <p>Default: No minimum or maximum limits</p>"}))
    InstanceRequirementsRequest.add_member(:accelerator_manufacturers, Smithy::Schema::Shapes::ShapeRef.new(shape: AcceleratorManufacturerSet, location_name: 'AcceleratorManufacturers', traits: {"smithy.api#documentation" => "<p>Indicates whether instance types must have accelerators by specific manufacturers.</p>\n         <ul>\n            <li>\n               <p>For instance types with Amazon Web Services devices, specify <code>amazon-web-services</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with AMD devices, specify <code>amd</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Habana devices, specify <code>habana</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA devices, specify <code>nvidia</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Xilinx devices, specify <code>xilinx</code>.</p>\n            </li>\n         </ul>\n         <p>Default: Any manufacturer</p>", "smithy.api#xmlName" => "AcceleratorManufacturer"}))
    InstanceRequirementsRequest.add_member(:accelerator_names, Smithy::Schema::Shapes::ShapeRef.new(shape: AcceleratorNameSet, location_name: 'AcceleratorNames', traits: {"smithy.api#documentation" => "<p>The accelerators that must be on the instance type.</p>\n         <ul>\n            <li>\n               <p>For instance types with NVIDIA A10G GPUs, specify <code>a10g</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA A100 GPUs, specify <code>a100</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA H100 GPUs, specify <code>h100</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Amazon Web Services Inferentia chips, specify <code>inferentia</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA GRID K520 GPUs, specify <code>k520</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA K80 GPUs, specify <code>k80</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA M60 GPUs, specify <code>m60</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with AMD Radeon Pro V520 GPUs, specify <code>radeon-pro-v520</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA T4 GPUs, specify <code>t4</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA T4G GPUs, specify <code>t4g</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with Xilinx VU9P FPGAs, specify <code>vu9p</code>.</p>\n            </li>\n            <li>\n               <p>For instance types with NVIDIA V100 GPUs, specify <code>v100</code>.</p>\n            </li>\n         </ul>\n         <p>Default: Any accelerator</p>", "smithy.api#xmlName" => "AcceleratorName"}))
    InstanceRequirementsRequest.add_member(:accelerator_total_memory_mi_b, Smithy::Schema::Shapes::ShapeRef.new(shape: AcceleratorTotalMemoryMiBRequest, location_name: 'AcceleratorTotalMemoryMiB', traits: {"smithy.api#documentation" => "<p>The minimum and maximum amount of total accelerator memory, in MiB.</p>\n         <p>Default: No minimum or maximum limits</p>"}))
    InstanceRequirementsRequest.add_member(:network_bandwidth_gbps, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkBandwidthGbpsRequest, location_name: 'NetworkBandwidthGbps', traits: {"smithy.api#documentation" => "<p>The minimum and maximum amount of baseline network bandwidth, in gigabits per second \n          (Gbps). For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-instance-network-bandwidth.html\">Amazon EC2 instance network bandwidth</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <p>Default: No minimum or maximum limits</p>"}))
    InstanceRequirementsRequest.add_member(:allowed_instance_types, Smithy::Schema::Shapes::ShapeRef.new(shape: AllowedInstanceTypeSet, location_name: 'AllowedInstanceTypes', traits: {"smithy.api#documentation" => "<p>The instance types to apply your specified attributes against. All other instance types \n         are ignored, even if they match your specified attributes.</p>\n         <p>You can use strings with one or more wild cards, represented by\n         an asterisk (<code>*</code>), to allow an instance type, size, or generation. The\n         following are examples: <code>m5.8xlarge</code>, <code>c5*.*</code>, <code>m5a.*</code>,\n         <code>r*</code>, <code>*3*</code>.</p>\n         <p>For example, if you specify <code>c5*</code>,Amazon EC2 will allow the entire C5 instance\n         family, which includes all C5a and C5n instance types. If you specify\n         <code>m5a.*</code>, Amazon EC2 will allow all the M5a instance types, but not the M5n\n         instance types.</p>\n         <note>\n            <p>If you specify <code>AllowedInstanceTypes</code>, you can't specify <code>ExcludedInstanceTypes</code>.</p>\n         </note>\n         <p>Default: All instance types</p>", "smithy.api#xmlName" => "AllowedInstanceType"}))
    InstanceRequirementsRequest.add_member(:max_spot_price_as_percentage_of_optimal_on_demand_price, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'MaxSpotPriceAsPercentageOfOptimalOnDemandPrice', traits: {"smithy.api#documentation" => "<p>[Price protection] The price protection threshold for Spot Instances, as a percentage of an\n         identified On-Demand price. The identified On-Demand price is the price of the lowest\n         priced current generation C, M, or R instance type with your specified attributes. If no\n         current generation C, M, or R instance type matches your attributes, then the identified\n         price is from the lowest priced current generation instance types, and failing that, from\n         the lowest priced previous generation instance types that match your attributes. When Amazon EC2\n         selects instance types with your attributes, it will exclude instance types whose price\n         exceeds your specified threshold.</p>\n         <p>The parameter accepts an integer, which Amazon EC2 interprets as a percentage.</p>\n         <p>If you set <code>TargetCapacityUnitType</code> to <code>vcpu</code> or\n         <code>memory-mib</code>, the price protection threshold is based on the per vCPU or per\n         memory price instead of the per instance price.</p>\n         <note>\n            <p>Only one of <code>SpotMaxPricePercentageOverLowestPrice</code> or\n               <code>MaxSpotPriceAsPercentageOfOptimalOnDemandPrice</code> can be specified. If you\n            don't specify either, Amazon EC2 will automatically apply optimal price protection to\n            consistently select from a wide range of instance types. To indicate no price protection\n            threshold for Spot Instances, meaning you want to consider all instance types that match your\n            attributes, include one of these parameters and specify a high value, such as\n               <code>999999</code>.</p>\n         </note>"}))
    InstanceRequirementsRequest.add_member(:baseline_performance_factors, Smithy::Schema::Shapes::ShapeRef.new(shape: BaselinePerformanceFactorsRequest, location_name: 'BaselinePerformanceFactors', traits: {"smithy.api#documentation" => "<p>The baseline performance to consider, using an instance family as a baseline reference.\n         The instance family establishes the lowest acceptable level of performance. Amazon EC2 uses this\n         baseline to guide instance type selection, but there is no guarantee that the selected\n         instance types will always exceed the baseline for every application. Currently, this\n         parameter only supports CPU performance as a baseline performance factor. For more\n         information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-fleet-attribute-based-instance-type-selection.html#ec2fleet-abis-performance-protection\">Performance protection</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
