    InstanceSpecification.add_member(:exclude_boot_volume, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ExcludeBootVolume', traits: {"smithy.api#documentation" => "<p>Excludes the root volume from being snapshotted.</p>"}))
    InstanceSpecification.add_member(:exclude_data_volume_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeIdStringList, location_name: 'ExcludeDataVolumeIds', traits: {"smithy.api#documentation" => "<p>The IDs of the data (non-root) volumes to exclude from the multi-volume snapshot set. \n      If you specify the ID of the root volume, the request fails. To exclude the root volume, \n      use <b>ExcludeBootVolume</b>.</p>\n         <p>You can specify up to 40 volume IDs per request.</p>", "smithy.api#xmlName" => "ExcludeDataVolumeId"}))
