    IpPermission.add_member(:ip_protocol, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'IpProtocol', traits: {"aws.protocols#ec2QueryName" => "IpProtocol", "smithy.api#documentation" => "<p>The IP protocol name (<code>tcp</code>, <code>udp</code>, <code>icmp</code>, <code>icmpv6</code>) \n        or number (see <a href=\"http://www.iana.org/assignments/protocol-numbers/protocol-numbers.xhtml\">Protocol Numbers</a>).</p>\n         <p>Use <code>-1</code> to specify all protocols. When authorizing\n        security group rules, specifying <code>-1</code> or a protocol number other than\n        <code>tcp</code>, <code>udp</code>, <code>icmp</code>, or <code>icmpv6</code> allows\n        traffic on all ports, regardless of any port range you specify. For <code>tcp</code>,\n        <code>udp</code>, and <code>icmp</code>, you must specify a port range. For <code>icmpv6</code>,\n        the port range is optional; if you omit the port range, traffic for all types and codes is allowed.</p>", "smithy.api#xmlName" => "ipProtocol"}))
    IpPermission.add_member(:from_port, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'FromPort', traits: {"aws.protocols#ec2QueryName" => "FromPort", "smithy.api#documentation" => "<p>If the protocol is TCP or UDP, this is the start of the port range.\n        If the protocol is ICMP or ICMPv6, this is the ICMP type or -1 (all ICMP types).</p>", "smithy.api#xmlName" => "fromPort"}))
    IpPermission.add_member(:to_port, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ToPort', traits: {"aws.protocols#ec2QueryName" => "ToPort", "smithy.api#documentation" => "<p>If the protocol is TCP or UDP, this is the end of the port range.\n          If the protocol is ICMP or ICMPv6, this is the ICMP code or -1 (all ICMP codes). \n          If the start port is -1 (all ICMP types), then the end port must be -1 (all ICMP codes).</p>", "smithy.api#xmlName" => "toPort"}))
    IpPermission.add_member(:user_id_group_pairs, Smithy::Schema::Shapes::ShapeRef.new(shape: UserIdGroupPairList, location_name: 'UserIdGroupPairs', traits: {"aws.protocols#ec2QueryName" => "Groups", "smithy.api#documentation" => "<p>The security group and Amazon Web Services account ID pairs.</p>", "smithy.api#xmlName" => "groups"}))
    IpPermission.add_member(:ip_ranges, Smithy::Schema::Shapes::ShapeRef.new(shape: IpRangeList, location_name: 'IpRanges', traits: {"aws.protocols#ec2QueryName" => "IpRanges", "smithy.api#documentation" => "<p>The IPv4 address ranges.</p>", "smithy.api#xmlName" => "ipRanges"}))
