    Ipam.add_member(:scope_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ScopeCount', traits: {"aws.protocols#ec2QueryName" => "ScopeCount", "smithy.api#documentation" => "<p>The number of scopes in the IPAM. The scope quota is 5. For more information on quotas, see <a href=\"https://docs.aws.amazon.com/vpc/latest/ipam/quotas-ipam.html\">Quotas in IPAM</a> in the <i>Amazon VPC IPAM User Guide</i>.\n      </p>", "smithy.api#xmlName" => "scopeCount"}))
    Ipam.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"aws.protocols#ec2QueryName" => "Description", "smithy.api#documentation" => "<p>The description for the IPAM.</p>", "smithy.api#xmlName" => "description"}))
    Ipam.add_member(:operating_regions, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamOperatingRegionSet, location_name: 'OperatingRegions', traits: {"aws.protocols#ec2QueryName" => "OperatingRegionSet", "smithy.api#documentation" => "<p>The operating Regions for an IPAM. Operating Regions are Amazon Web Services Regions where the IPAM is allowed to manage IP address CIDRs. IPAM only discovers and monitors resources in the Amazon Web Services Regions you select as operating Regions.</p>\n         <p>For more information about operating Regions, see <a href=\"https://docs.aws.amazon.com/vpc/latest/ipam/create-ipam.html\">Create an IPAM</a> in the <i>Amazon VPC IPAM User Guide</i>.</p>", "smithy.api#xmlName" => "operatingRegionSet"}))
