    IpamPool.add_member(:source_ipam_pool_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamPoolId, location_name: 'SourceIpamPoolId', traits: {"aws.protocols#ec2QueryName" => "SourceIpamPoolId", "smithy.api#documentation" => "<p>The ID of the source IPAM pool. You can use this option to create an IPAM pool within an existing source pool.</p>", "smithy.api#xmlName" => "sourceIpamPoolId"}))
    IpamPool.add_member(:ipam_pool_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'IpamPoolArn', traits: {"aws.protocols#ec2QueryName" => "IpamPoolArn", "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IPAM pool.</p>", "smithy.api#xmlName" => "ipamPoolArn"}))
    IpamPool.add_member(:ipam_scope_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'IpamScopeArn', traits: {"aws.protocols#ec2QueryName" => "IpamScopeArn", "smithy.api#documentation" => "<p>The ARN of the scope of the IPAM pool.</p>", "smithy.api#xmlName" => "ipamScopeArn"}))
    IpamPool.add_member(:ipam_scope_type, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamScopeType, location_name: 'IpamScopeType', traits: {"aws.protocols#ec2QueryName" => "IpamScopeType", "smithy.api#documentation" => "<p>In IPAM, a scope is the highest-level container within IPAM. An IPAM contains two default scopes. Each scope represents the IP space for a single network. The private scope is intended for all private IP address space. The public scope is intended for all public IP address space. Scopes enable you to reuse IP addresses across multiple unconnected networks without causing IP address overlap or conflict.</p>", "smithy.api#xmlName" => "ipamScopeType"}))
    IpamPool.add_member(:ipam_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'IpamArn', traits: {"aws.protocols#ec2QueryName" => "IpamArn", "smithy.api#documentation" => "<p>The ARN of the IPAM.</p>", "smithy.api#xmlName" => "ipamArn"}))
    IpamPool.add_member(:ipam_region, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'IpamRegion', traits: {"aws.protocols#ec2QueryName" => "IpamRegion", "smithy.api#documentation" => "<p>The Amazon Web Services Region of the IPAM pool.</p>", "smithy.api#xmlName" => "ipamRegion"}))
    IpamPool.add_member(:locale, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Locale', traits: {"aws.protocols#ec2QueryName" => "Locale", "smithy.api#documentation" => "<p>The locale of the IPAM pool.</p>\n         <p>The locale for the pool should be one of the following:</p>\n         <ul>\n            <li>\n               <p>An Amazon Web Services Region where you want this IPAM pool to be available for allocations.</p>\n            </li>\n            <li>\n               <p>The network border group for an Amazon Web Services Local Zone where you want this IPAM pool to be available for allocations (<a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-byoip.html#byoip-zone-avail\">supported Local Zones</a>). This option is only available for IPAM IPv4 pools in the public scope.</p>\n            </li>\n         </ul>\n         <p>If you choose an Amazon Web Services Region for locale that has not been configured as an operating Region for the IPAM, you'll get an error.</p>", "smithy.api#xmlName" => "locale"}))
    IpamPool.add_member(:pool_depth, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'PoolDepth', traits: {"aws.protocols#ec2QueryName" => "PoolDepth", "smithy.api#documentation" => "<p>The depth of pools in your IPAM pool. The pool depth quota is 10. For more information, see <a href=\"https://docs.aws.amazon.com/vpc/latest/ipam/quotas-ipam.html\">Quotas in IPAM</a> in the <i>Amazon VPC IPAM User Guide</i>.\n      </p>", "smithy.api#xmlName" => "poolDepth"}))
    IpamPool.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamPoolState, location_name: 'State', traits: {"aws.protocols#ec2QueryName" => "State", "smithy.api#documentation" => "<p>The state of the IPAM pool.</p>", "smithy.api#xmlName" => "state"}))
    IpamPool.add_member(:state_message, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StateMessage', traits: {"aws.protocols#ec2QueryName" => "StateMessage", "smithy.api#documentation" => "<p>The state message.</p>", "smithy.api#xmlName" => "stateMessage"}))
    IpamPool.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"aws.protocols#ec2QueryName" => "Description", "smithy.api#documentation" => "<p>The description of the IPAM pool.</p>", "smithy.api#xmlName" => "description"}))
    IpamPool.add_member(:auto_import, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AutoImport', traits: {"aws.protocols#ec2QueryName" => "AutoImport", "smithy.api#documentation" => "<p>If selected, IPAM will continuously look for resources within the CIDR range of this pool \n         and automatically import them as allocations into your IPAM. The CIDRs that will be allocated for\n         these resources must not already be allocated to other resources in order for the import to succeed. IPAM will import \n         a CIDR regardless of its compliance with the pool's allocation rules, so a resource might be imported and subsequently \n         marked as noncompliant. If IPAM discovers multiple CIDRs that overlap, IPAM will import the largest CIDR only. If IPAM \n         discovers multiple CIDRs with matching CIDRs, IPAM will randomly import one of them only.\n      </p>\n         <p>A locale must be set on the pool for this feature to work.</p>", "smithy.api#xmlName" => "autoImport"}))
    IpamPool.add_member(:publicly_advertisable, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'PubliclyAdvertisable', traits: {"aws.protocols#ec2QueryName" => "PubliclyAdvertisable", "smithy.api#documentation" => "<p>Determines if a pool is publicly advertisable. This option is not available for pools with AddressFamily set to <code>ipv4</code>.</p>", "smithy.api#xmlName" => "publiclyAdvertisable"}))
    IpamPool.add_member(:address_family, Smithy::Schema::Shapes::ShapeRef.new(shape: AddressFamily, location_name: 'AddressFamily', traits: {"aws.protocols#ec2QueryName" => "AddressFamily", "smithy.api#documentation" => "<p>The address family of the pool.</p>", "smithy.api#xmlName" => "addressFamily"}))
    IpamPool.add_member(:allocation_min_netmask_length, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamNetmaskLength, location_name: 'AllocationMinNetmaskLength', traits: {"aws.protocols#ec2QueryName" => "AllocationMinNetmaskLength", "smithy.api#documentation" => "<p>The minimum netmask length required for CIDR allocations in this IPAM pool to be compliant. The minimum netmask length must be less than the maximum netmask length. Possible netmask lengths for IPv4 addresses are 0 - 32. Possible netmask lengths for IPv6 addresses are  0 - 128.</p>", "smithy.api#xmlName" => "allocationMinNetmaskLength"}))
    IpamPool.add_member(:allocation_max_netmask_length, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamNetmaskLength, location_name: 'AllocationMaxNetmaskLength', traits: {"aws.protocols#ec2QueryName" => "AllocationMaxNetmaskLength", "smithy.api#documentation" => "<p>The maximum netmask length possible for CIDR allocations in this IPAM pool to be compliant. The maximum netmask length must be greater than the minimum netmask length. Possible netmask lengths for IPv4 addresses are 0 - 32. Possible netmask lengths for IPv6 addresses are  0 - 128.</p>", "smithy.api#xmlName" => "allocationMaxNetmaskLength"}))
    IpamPool.add_member(:allocation_default_netmask_length, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamNetmaskLength, location_name: 'AllocationDefaultNetmaskLength', traits: {"aws.protocols#ec2QueryName" => "AllocationDefaultNetmaskLength", "smithy.api#documentation" => "<p>The default netmask length for allocations added to this pool. If, for example, the CIDR assigned to this pool is 10.0.0.0/8 and \n         you enter 16 here, new allocations will default to 10.0.0.0/16.</p>", "smithy.api#xmlName" => "allocationDefaultNetmaskLength"}))
    IpamPool.add_member(:allocation_resource_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamResourceTagList, location_name: 'AllocationResourceTags', traits: {"aws.protocols#ec2QueryName" => "AllocationResourceTagSet", "smithy.api#documentation" => "<p>Tags that are required for resources that use CIDRs from this IPAM pool. Resources that do not have these tags will not be allowed to allocate space from the pool. If the resources have their tags changed after they have allocated space or if the allocation tagging requirements are changed on the pool, the resource may be marked as noncompliant.</p>", "smithy.api#xmlName" => "allocationResourceTagSet"}))
    IpamPool.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"aws.protocols#ec2QueryName" => "TagSet", "smithy.api#documentation" => "<p>The key/value combination of a tag assigned to the resource. Use the tag key in the filter name and the tag value as the filter value.\n    For example, to find all resources that have a tag with the key <code>Owner</code> and the value <code>TeamA</code>, specify <code>tag:Owner</code> for the filter name and <code>TeamA</code> for the filter value.</p>", "smithy.api#xmlName" => "tagSet"}))
    IpamPool.add_member(:aws_service, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamPoolAwsService, location_name: 'AwsService', traits: {"aws.protocols#ec2QueryName" => "AwsService", "smithy.api#documentation" => "<p>Limits which service in Amazon Web Services that the pool can be used in. \"ec2\", for example, allows users to use space for Elastic IP addresses and VPCs.</p>", "smithy.api#xmlName" => "awsService"}))
    IpamPool.add_member(:public_ip_source, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamPoolPublicIpSource, location_name: 'PublicIpSource', traits: {"aws.protocols#ec2QueryName" => "PublicIpSource", "smithy.api#documentation" => "<p>The IP address source for pools in the public scope. Only used for provisioning IP address CIDRs to pools in the public scope. Default is <code>BYOIP</code>. For more information, see <a href=\"https://docs.aws.amazon.com/vpc/latest/ipam/intro-create-ipv6-pools.html\">Create IPv6 pools</a> in the <i>Amazon VPC IPAM User Guide</i>. \n         By default, you can add only one Amazon-provided IPv6 CIDR block to a top-level IPv6 pool. For information on increasing the default limit, see <a href=\"https://docs.aws.amazon.com/vpc/latest/ipam/quotas-ipam.html\">Quotas for your IPAM</a> in the <i>Amazon VPC IPAM User Guide</i>.</p>", "smithy.api#xmlName" => "publicIpSource"}))
    IpamPool.add_member(:source_resource, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamPoolSourceResource, location_name: 'SourceResource', traits: {"aws.protocols#ec2QueryName" => "SourceResource", "smithy.api#documentation" => "<p>The resource used to provision CIDRs to a resource planning pool.</p>", "smithy.api#xmlName" => "sourceResource"}))
    IpamPool.type = Types::IpamPool
    IpamPoolAllocation.add_member(:cidr, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Cidr', traits: {"aws.protocols#ec2QueryName" => "Cidr", "smithy.api#documentation" => "<p>The CIDR for the allocation. A CIDR is a representation of an IP address and its associated network mask (or netmask) and \n         refers to a range of IP addresses. An IPv4 CIDR example is <code>10.24.34.0/23</code>. An IPv6 CIDR example is <code>2001:DB8::/32</code>.</p>", "smithy.api#xmlName" => "cidr"}))
    IpamPoolAllocation.add_member(:ipam_pool_allocation_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamPoolAllocationId, location_name: 'IpamPoolAllocationId', traits: {"aws.protocols#ec2QueryName" => "IpamPoolAllocationId", "smithy.api#documentation" => "<p>The ID of an allocation.</p>", "smithy.api#xmlName" => "ipamPoolAllocationId"}))
    IpamPoolAllocation.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"aws.protocols#ec2QueryName" => "Description", "smithy.api#documentation" => "<p>A description of the pool allocation.</p>", "smithy.api#xmlName" => "description"}))
