    IpamPoolAllocation.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamPoolAllocationResourceType, location_name: 'ResourceType', traits: {"aws.protocols#ec2QueryName" => "ResourceType", "smithy.api#documentation" => "<p>The type of the resource.</p>", "smithy.api#xmlName" => "resourceType"}))
