    IpamPoolAllocation.add_member(:resource_owner, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ResourceOwner', traits: {"aws.protocols#ec2QueryName" => "ResourceOwner", "smithy.api#documentation" => "<p>The owner of the resource.</p>", "smithy.api#xmlName" => "resourceOwner"}))
