    KeyPairInfo.add_member(:create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: MillisecondDateTime, location_name: 'CreateTime', traits: {"aws.protocols#ec2QueryName" => "CreateTime", "smithy.api#documentation" => "<p>If you used Amazon EC2 to create the key pair, this is the date and time when the key\n            was created, in <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\">ISO\n                8601 date-time format</a>, in the UTC time zone.</p>\n         <p>If you imported an existing key pair to Amazon EC2, this is the date and time the key\n            was imported, in <a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\">ISO\n                8601 date-time format</a>, in the UTC time zone.</p>", "smithy.api#xmlName" => "createTime"}))
