    LaunchTemplateCapacityReservationSpecificationRequest.add_member(:capacity_reservation_preference, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationPreference, location_name: 'CapacityReservationPreference', traits: {"smithy.api#documentation" => "<p>Indicates the instance's Capacity Reservation preferences. Possible preferences\n            include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>capacity-reservations-only</code> - The instance will only run in a\n                    Capacity Reservation or Capacity Reservation group. If capacity isn't available,\n                    the instance will fail to launch.</p>\n            </li>\n            <li>\n               <p>\n                  <code>open</code> - The instance can run in any <code>open</code> Capacity\n                    Reservation that has matching attributes (instance type, platform, Availability\n                    Zone, tenancy).</p>\n            </li>\n            <li>\n               <p>\n                  <code>none</code> - The instance avoids running in a Capacity Reservation even\n                    if one is available. The instance runs in On-Demand capacity.</p>\n            </li>\n         </ul>"}))
    LaunchTemplateCapacityReservationSpecificationRequest.add_member(:capacity_reservation_target, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationTarget, location_name: 'CapacityReservationTarget', traits: {"smithy.api#documentation" => "<p>Information about the target Capacity Reservation or Capacity Reservation\n            group.</p>"}))
    LaunchTemplateCapacityReservationSpecificationRequest.type = Types::LaunchTemplateCapacityReservationSpecificationRequest
    LaunchTemplateCapacityReservationSpecificationResponse.add_member(:capacity_reservation_preference, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationPreference, location_name: 'CapacityReservationPreference', traits: {"aws.protocols#ec2QueryName" => "CapacityReservationPreference", "smithy.api#documentation" => "<p>Indicates the instance's Capacity Reservation preferences. Possible preferences\n            include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>open</code> - The instance can run in any <code>open</code> Capacity\n                    Reservation that has matching attributes (instance type, platform, Availability\n                    Zone).</p>\n            </li>\n            <li>\n               <p>\n                  <code>none</code> - The instance avoids running in a Capacity Reservation even\n                    if one is available. The instance runs in On-Demand capacity.</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "capacityReservationPreference"}))
    LaunchTemplateCapacityReservationSpecificationResponse.add_member(:capacity_reservation_target, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationTargetResponse, location_name: 'CapacityReservationTarget', traits: {"aws.protocols#ec2QueryName" => "CapacityReservationTarget", "smithy.api#documentation" => "<p>Information about the target Capacity Reservation or Capacity Reservation\n            group.</p>", "smithy.api#xmlName" => "capacityReservationTarget"}))
