    LaunchTemplateCpuOptions.type = Types::LaunchTemplateCpuOptions
    LaunchTemplateCpuOptionsRequest.add_member(:core_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'CoreCount', traits: {"smithy.api#documentation" => "<p>The number of CPU cores for the instance.</p>"}))
    LaunchTemplateCpuOptionsRequest.add_member(:threads_per_core, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ThreadsPerCore', traits: {"smithy.api#documentation" => "<p>The number of threads per CPU core. To disable multithreading for the instance,\n            specify a value of <code>1</code>. Otherwise, specify the default value of\n                <code>2</code>.</p>"}))
