    LaunchTemplateEbsBlockDevice.add_member(:throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Throughput', traits: {"aws.protocols#ec2QueryName" => "Throughput", "smithy.api#documentation" => "<p>The throughput that the volume supports, in MiB/s.</p>", "smithy.api#xmlName" => "throughput"}))
    LaunchTemplateEbsBlockDevice.add_member(:volume_initialization_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'VolumeInitializationRate', traits: {"aws.protocols#ec2QueryName" => "VolumeInitializationRate", "smithy.api#documentation" => "<p>The Amazon EBS Provisioned Rate for Volume Initialization (volume initialization rate) specified for the volume, in MiB/s. \n            If no volume initialization rate was specified, the value is <code>null</code>.</p>", "smithy.api#xmlName" => "volumeInitializationRate"}))
    LaunchTemplateEbsBlockDevice.type = Types::LaunchTemplateEbsBlockDevice
    LaunchTemplateEbsBlockDeviceRequest.add_member(:encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'Encrypted', traits: {"smithy.api#documentation" => "<p>Indicates whether the EBS volume is encrypted. Encrypted volumes can only be attached\n            to instances that support Amazon EBS encryption. If you are creating a volume from a\n            snapshot, you can't specify an encryption value.</p>"}))
    LaunchTemplateEbsBlockDeviceRequest.add_member(:delete_on_termination, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DeleteOnTermination', traits: {"smithy.api#documentation" => "<p>Indicates whether the EBS volume is deleted on instance termination.</p>"}))
    LaunchTemplateEbsBlockDeviceRequest.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The number of I/O operations per second (IOPS). For <code>gp3</code>,\n            <code>io1</code>, and <code>io2</code> volumes, this represents the number of IOPS that\n            are provisioned for the volume. For <code>gp2</code> volumes, this represents the\n            baseline performance of the volume and the rate at which the volume accumulates I/O\n            credits for bursting.</p>\n         <p>The following are the supported values for each volume type:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>gp3</code>: 3,000 - 16,000 IOPS</p>\n            </li>\n            <li>\n               <p>\n                  <code>io1</code>: 100 - 64,000 IOPS</p>\n            </li>\n            <li>\n               <p>\n                  <code>io2</code>: 100 - 256,000 IOPS</p>\n            </li>\n         </ul>\n         <p>For <code>io2</code> volumes, you can achieve up to 256,000 IOPS on \n<a href=\"https://docs.aws.amazon.com/ec2/latest/instancetypes/ec2-nitro-instances.html\">instances \nbuilt on the Nitro System</a>. On other instances, you can achieve performance up to 32,000 IOPS.</p>\n         <p>This parameter is supported for <code>io1</code>, <code>io2</code>, and <code>gp3</code> volumes only.</p>"}))
    LaunchTemplateEbsBlockDeviceRequest.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyId, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>Identifier (key ID, key alias, key ARN, or alias ARN) of the customer managed KMS key to use for EBS encryption.</p>"}))
    LaunchTemplateEbsBlockDeviceRequest.add_member(:snapshot_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotId, location_name: 'SnapshotId', traits: {"smithy.api#documentation" => "<p>The ID of the snapshot.</p>"}))
    LaunchTemplateEbsBlockDeviceRequest.add_member(:volume_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'VolumeSize', traits: {"smithy.api#documentation" => "<p>The size of the volume, in GiBs. You must specify either a snapshot ID or a volume\n            size. The following are the supported volumes sizes for each volume type:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>gp2</code> and <code>gp3</code>: 1 - 16,384 GiB</p>\n            </li>\n            <li>\n               <p>\n                  <code>io1</code>: 4 - 16,384 GiB</p>\n            </li>\n            <li>\n               <p>\n                  <code>io2</code>: 4 - 65,536 GiB</p>\n            </li>\n            <li>\n               <p>\n                  <code>st1</code> and <code>sc1</code>: 125 - 16,384 GiB</p>\n            </li>\n            <li>\n               <p>\n                  <code>standard</code>: 1 - 1024 GiB</p>\n            </li>\n         </ul>"}))
    LaunchTemplateEbsBlockDeviceRequest.add_member(:volume_type, Smithy::Schema::Shapes::ShapeRef.new(shape: VolumeType, location_name: 'VolumeType', traits: {"smithy.api#documentation" => "<p>The volume type. For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/ebs-volume-types.html\">Amazon EBS volume types</a> in the\n                <i>Amazon EBS User Guide</i>.</p>"}))
    LaunchTemplateEbsBlockDeviceRequest.add_member(:throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Throughput', traits: {"smithy.api#documentation" => "<p>The throughput to provision for a <code>gp3</code> volume, with a maximum of 1,000\n            MiB/s.</p>\n         <p>Valid Range: Minimum value of 125. Maximum value of 1000.</p>"}))
    LaunchTemplateEbsBlockDeviceRequest.add_member(:volume_initialization_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'VolumeInitializationRate', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon EBS Provisioned Rate for Volume Initialization (volume initialization rate), in MiB/s, at which to download \n            the snapshot blocks from Amazon S3 to the volume. This is also known as <i>volume \n                initialization</i>. Specifying a volume initialization rate ensures that the volume is \n            initialized at a predictable and consistent rate after creation.</p>\n         <p>This parameter is supported only for volumes created from snapshots. Omit this parameter \n            if:</p>\n         <ul>\n            <li>\n               <p>You want to create the volume using fast snapshot restore. You must specify a snapshot \n                    that is enabled for fast snapshot restore. In this case, the volume is fully initialized \n                    at creation.</p>\n               <note>\n                  <p>If you specify a snapshot that is enabled for fast snapshot restore and a volume initialization rate, \n                        the volume will be initialized at the specified rate instead of fast snapshot restore.</p>\n               </note>\n            </li>\n            <li>\n               <p>You want to create a volume that is initialized at the default rate.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/initalize-volume.html\">\n            Initialize Amazon EBS volumes</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <p>Valid range: 100 - 300 MiB/s</p>"}))
