    LaunchTemplateInstanceMetadataOptions.add_member(:http_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateHttpTokensState, location_name: 'HttpTokens', traits: {"aws.protocols#ec2QueryName" => "HttpTokens", "smithy.api#documentation" => "<p>Indicates whether IMDSv2 is required.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>optional</code> - IMDSv2 is optional. You can choose whether to send a\n                    session token in your instance metadata retrieval requests. If you retrieve IAM\n                    role credentials without a session token, you receive the IMDSv1 role\n                    credentials. If you retrieve IAM role credentials using a valid session token,\n                    you receive the IMDSv2 role credentials.</p>\n            </li>\n            <li>\n               <p>\n                  <code>required</code> - IMDSv2 is required. You must send a session token in\n                    your instance metadata retrieval requests. With this option, retrieving the IAM\n                    role credentials always returns IMDSv2 credentials; IMDSv1 credentials are not\n                    available.</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "httpTokens"}))
    LaunchTemplateInstanceMetadataOptions.add_member(:http_put_response_hop_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'HttpPutResponseHopLimit', traits: {"aws.protocols#ec2QueryName" => "HttpPutResponseHopLimit", "smithy.api#documentation" => "<p>The desired HTTP PUT response hop limit for instance metadata requests. The larger the\n            number, the further instance metadata requests can travel.</p>\n         <p>Default: 1</p>\n         <p>Possible values: Integers from 1 to 64</p>", "smithy.api#xmlName" => "httpPutResponseHopLimit"}))
    LaunchTemplateInstanceMetadataOptions.add_member(:http_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateInstanceMetadataEndpointState, location_name: 'HttpEndpoint', traits: {"aws.protocols#ec2QueryName" => "HttpEndpoint", "smithy.api#documentation" => "<p>Enables or disables the HTTP metadata endpoint on your instances. If the parameter is\n            not specified, the default state is <code>enabled</code>.</p>\n         <note>\n            <p>If you specify a value of <code>disabled</code>, you will not be able to access\n                your instance metadata. </p>\n         </note>", "smithy.api#xmlName" => "httpEndpoint"}))
    LaunchTemplateInstanceMetadataOptions.add_member(:http_protocol_ipv6, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateInstanceMetadataProtocolIpv6, location_name: 'HttpProtocolIpv6', traits: {"aws.protocols#ec2QueryName" => "HttpProtocolIpv6", "smithy.api#documentation" => "<p>Enables or disables the IPv6 endpoint for the instance metadata service.</p>\n         <p>Default: <code>disabled</code>\n         </p>", "smithy.api#xmlName" => "httpProtocolIpv6"}))
