    LaunchTemplateInstanceMetadataOptions.type = Types::LaunchTemplateInstanceMetadataOptions
    LaunchTemplateInstanceMetadataOptionsRequest.add_member(:http_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateHttpTokensState, location_name: 'HttpTokens', traits: {"smithy.api#documentation" => "<p>Indicates whether IMDSv2 is required.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>optional</code> - IMDSv2 is optional. You can choose whether to send a\n                    session token in your instance metadata retrieval requests. If you retrieve IAM\n                    role credentials without a session token, you receive the IMDSv1 role\n                    credentials. If you retrieve IAM role credentials using a valid session token,\n                    you receive the IMDSv2 role credentials.</p>\n            </li>\n            <li>\n               <p>\n                  <code>required</code> - IMDSv2 is required. You must send a session token in\n                    your instance metadata retrieval requests. With this option, retrieving the IAM\n                    role credentials always returns IMDSv2 credentials; IMDSv1 credentials are not\n                    available.</p>\n            </li>\n         </ul>\n         <p>Default: If the value of <code>ImdsSupport</code> for the Amazon Machine Image (AMI)\n            for your instance is <code>v2.0</code>, the default is <code>required</code>.</p>"}))
    LaunchTemplateInstanceMetadataOptionsRequest.add_member(:http_put_response_hop_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'HttpPutResponseHopLimit', traits: {"smithy.api#documentation" => "<p>The desired HTTP PUT response hop limit for instance metadata requests. The larger the\n            number, the further instance metadata requests can travel.</p>\n         <p>Default: <code>1</code>\n         </p>\n         <p>Possible values: Integers from 1 to 64</p>"}))
    LaunchTemplateInstanceMetadataOptionsRequest.add_member(:http_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateInstanceMetadataEndpointState, location_name: 'HttpEndpoint', traits: {"smithy.api#documentation" => "<p>Enables or disables the HTTP metadata endpoint on your instances. If the parameter is\n            not specified, the default state is <code>enabled</code>.</p>\n         <note>\n            <p>If you specify a value of <code>disabled</code>, you will not be able to access\n                your instance metadata. </p>\n         </note>"}))
