    LaunchTemplateInstanceNetworkInterfaceSpecificationRequest.add_member(:associate_carrier_ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AssociateCarrierIpAddress', traits: {"smithy.api#documentation" => "<p>Associates a Carrier IP address with eth0 for a new network interface.</p>\n         <p>Use this option when you launch an instance in a Wavelength Zone and want to associate\n            a Carrier IP address with the network interface. For more information about Carrier IP\n            addresses, see <a href=\"https://docs.aws.amazon.com/wavelength/latest/developerguide/how-wavelengths-work.html#provider-owned-ip\">Carrier IP addresses</a> in the <i>Wavelength Developer\n            Guide</i>.</p>"}))
    LaunchTemplateInstanceNetworkInterfaceSpecificationRequest.add_member(:associate_public_ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AssociatePublicIpAddress', traits: {"smithy.api#documentation" => "<p>Associates a public IPv4 address with eth0 for a new network interface.</p>\n         <p>Amazon Web Services charges for all public IPv4 addresses, including public IPv4 addresses \nassociated with running instances and Elastic IP addresses. For more information, see the <i>Public IPv4 Address</i> tab on the <a href=\"http://aws.amazon.com/vpc/pricing/\">Amazon VPC pricing page</a>.</p>"}))
