    LaunchTemplateInstanceNetworkInterfaceSpecificationRequest.add_member(:device_index, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'DeviceIndex', traits: {"smithy.api#documentation" => "<p>The device index for the network interface attachment. The primary network interface\n            has a device index of 0. Each network interface is of type <code>interface</code>, you\n            must specify a device index. If you create a launch template that includes secondary\n            network interfaces but not a primary network interface, then you must add a primary\n            network interface as a launch parameter when you launch an instance from the\n            template.</p>"}))
    LaunchTemplateInstanceNetworkInterfaceSpecificationRequest.add_member(:groups, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIdStringList, location_name: 'Groups', traits: {"smithy.api#documentation" => "<p>The IDs of one or more security groups.</p>", "smithy.api#xmlName" => "SecurityGroupId"}))
    LaunchTemplateInstanceNetworkInterfaceSpecificationRequest.add_member(:interface_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'InterfaceType', traits: {"smithy.api#documentation" => "<p>The type of network interface. To create an Elastic Fabric Adapter (EFA), specify\n                <code>efa</code> or <code>efa</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/efa.html\">Elastic Fabric Adapter for AI/ML\n                and HPC workloads on Amazon EC2</a> in the\n            <i>Amazon EC2 User Guide</i>.</p>\n         <p>If you are not creating an EFA, specify <code>interface</code> or omit this\n            parameter.</p>\n         <p>If you specify <code>efa-only</code>, do not assign any IP addresses to the network\n            interface. EFA-only network interfaces do not support IP addresses.</p>\n         <p>Valid values: <code>interface</code> | <code>efa</code> | <code>efa-only</code>\n         </p>"}))
    LaunchTemplateInstanceNetworkInterfaceSpecificationRequest.add_member(:ipv6_address_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Ipv6AddressCount', traits: {"smithy.api#documentation" => "<p>The number of IPv6 addresses to assign to a network interface. Amazon EC2\n            automatically selects the IPv6 addresses from the subnet range. You can't use this\n            option if specifying specific IPv6 addresses.</p>"}))
    LaunchTemplateInstanceNetworkInterfaceSpecificationRequest.add_member(:ipv6_addresses, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceIpv6AddressListRequest, location_name: 'Ipv6Addresses', traits: {"smithy.api#documentation" => "<p>One or more specific IPv6 addresses from the IPv6 CIDR block range of your subnet. You\n            can't use this option if you're specifying a number of IPv6 addresses.</p>"}))
