    LaunchTemplateInstanceNetworkInterfaceSpecificationRequest.add_member(:private_ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PrivateIpAddress', traits: {"smithy.api#documentation" => "<p>The primary private IPv4 address of the network interface.</p>"}))
