    LaunchTemplateInstanceNetworkInterfaceSpecificationRequest.add_member(:network_card_index, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'NetworkCardIndex', traits: {"smithy.api#documentation" => "<p>The index of the network card. Some instance types support multiple network cards. The\n            primary network interface must be assigned to network card index 0. The default is\n            network card index 0.</p>"}))
    LaunchTemplateInstanceNetworkInterfaceSpecificationRequest.add_member(:ipv4_prefixes, Smithy::Schema::Shapes::ShapeRef.new(shape: Ipv4PrefixList, location_name: 'Ipv4Prefixes', traits: {"smithy.api#documentation" => "<p>One or more IPv4 prefixes to be assigned to the network interface. You cannot use this\n            option if you use the <code>Ipv4PrefixCount</code> option.</p>", "smithy.api#xmlName" => "Ipv4Prefix"}))
