    LaunchTemplateNetworkPerformanceOptions.add_member(:bandwidth_weighting, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceBandwidthWeighting, location_name: 'BandwidthWeighting', traits: {"aws.protocols#ec2QueryName" => "BandwidthWeighting", "smithy.api#documentation" => "<p>When you configure network bandwidth weighting, you can boost baseline bandwidth for\n            either networking or EBS by up to 25%. The total available baseline bandwidth for your\n            instance remains the same. The default option uses the standard bandwidth configuration\n            for your instance type.</p>", "smithy.api#xmlName" => "bandwidthWeighting"}))
    LaunchTemplateNetworkPerformanceOptions.type = Types::LaunchTemplateNetworkPerformanceOptions
    LaunchTemplateNetworkPerformanceOptionsRequest.add_member(:bandwidth_weighting, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceBandwidthWeighting, location_name: 'BandwidthWeighting', traits: {"smithy.api#documentation" => "<p>Specify the bandwidth weighting option to boost the associated type of baseline\n            bandwidth, as follows:</p>\n         <dl>\n            <dt>default</dt>\n            <dd>\n               <p>This option uses the standard bandwidth configuration for your instance\n                        type.</p>\n            </dd>\n            <dt>vpc-1</dt>\n            <dd>\n               <p>This option boosts your networking baseline bandwidth and reduces your EBS\n                        baseline bandwidth.</p>\n            </dd>\n            <dt>ebs-1</dt>\n            <dd>\n               <p>This option boosts your EBS baseline bandwidth and reduces your networking\n                        baseline bandwidth.</p>\n            </dd>\n         </dl>"}))
