    LaunchTemplateOverrides.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceType, location_name: 'InstanceType', traits: {"aws.protocols#ec2QueryName" => "InstanceType", "smithy.api#documentation" => "<p>The instance type.</p>", "smithy.api#xmlName" => "instanceType"}))
    LaunchTemplateOverrides.add_member(:spot_price, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SpotPrice', traits: {"aws.protocols#ec2QueryName" => "SpotPrice", "smithy.api#documentation" => "<p>The maximum price per unit hour that you are willing to pay for a Spot Instance. We do not recommend using this parameter because it can lead to \n         increased interruptions. If you do not specify this parameter, you will pay the current Spot price.</p>\n         <important>\n            <p>If you specify a maximum price, your instances will be interrupted more frequently than if you do not specify this parameter.</p>\n         </important>", "smithy.api#xmlName" => "spotPrice"}))
    LaunchTemplateOverrides.add_member(:subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetId, location_name: 'SubnetId', traits: {"aws.protocols#ec2QueryName" => "SubnetId", "smithy.api#documentation" => "<p>The ID of the subnet in which to launch the instances.</p>", "smithy.api#xmlName" => "subnetId"}))
    LaunchTemplateOverrides.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZone', traits: {"aws.protocols#ec2QueryName" => "AvailabilityZone", "smithy.api#documentation" => "<p>The Availability Zone in which to launch the instances.</p>", "smithy.api#xmlName" => "availabilityZone"}))
    LaunchTemplateOverrides.add_member(:weighted_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'WeightedCapacity', traits: {"aws.protocols#ec2QueryName" => "WeightedCapacity", "smithy.api#documentation" => "<p>The number of units provided by the specified instance type. These are the same units\n         that you chose to set the target capacity in terms of instances, or a performance\n         characteristic such as vCPUs, memory, or I/O.</p>\n         <p>If the target capacity divided by this value is not a whole number, Amazon EC2 rounds the\n         number of instances to the next whole number. If this value is not specified, the default\n         is 1.</p>\n         <note>\n            <p>When specifying weights, the price used in the <code>lowestPrice</code> and\n            <code>priceCapacityOptimized</code> allocation strategies is per\n            <i>unit</i> hour (where the instance price is divided by the specified\n            weight). However, if all the specified weights are above the requested\n            <code>TargetCapacity</code>, resulting in only 1 instance being launched, the price\n            used is per <i>instance</i> hour.</p>\n         </note>", "smithy.api#xmlName" => "weightedCapacity"}))
    LaunchTemplateOverrides.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'Priority', traits: {"aws.protocols#ec2QueryName" => "Priority", "smithy.api#documentation" => "<p>The priority for the launch template override. The highest priority is launched\n         first.</p>\n         <p>If <code>OnDemandAllocationStrategy</code> is set to <code>prioritized</code>, Spot Fleet\n         uses priority to determine which launch template override to use first in fulfilling\n         On-Demand capacity.</p>\n         <p>If the Spot <code>AllocationStrategy</code> is set to\n         <code>capacityOptimizedPrioritized</code>, Spot Fleet uses priority on a best-effort basis\n         to determine which launch template override to use in fulfilling Spot capacity, but\n         optimizes for capacity first.</p>\n         <p>Valid values are whole numbers starting at <code>0</code>. The lower the number, the\n         higher the priority. If no number is set, the launch template override has the lowest\n         priority. You can set the same priority for different launch template overrides.</p>", "smithy.api#xmlName" => "priority"}))
    LaunchTemplateOverrides.add_member(:instance_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRequirements, location_name: 'InstanceRequirements', traits: {"aws.protocols#ec2QueryName" => "InstanceRequirements", "smithy.api#documentation" => "<p>The instance requirements. When you specify instance requirements, Amazon EC2 will identify\n         instance types with the provided requirements, and then use your On-Demand and Spot\n         allocation strategies to launch instances from these instance types, in the same way as\n         when you specify a list of instance types.</p>\n         <note>\n            <p>If you specify <code>InstanceRequirements</code>, you can't specify\n            <code>InstanceType</code>.</p>\n         </note>", "smithy.api#xmlName" => "instanceRequirements"}))
    LaunchTemplateOverrides.type = Types::LaunchTemplateOverrides
