    LaunchTemplatePlacement.add_member(:partition_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'PartitionNumber', traits: {"aws.protocols#ec2QueryName" => "PartitionNumber", "smithy.api#documentation" => "<p>The number of the partition the instance should launch in. Valid only if the placement\n            group strategy is set to <code>partition</code>.</p>", "smithy.api#xmlName" => "partitionNumber"}))
    LaunchTemplatePlacement.add_member(:group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: PlacementGroupId, location_name: 'GroupId', traits: {"aws.protocols#ec2QueryName" => "GroupId", "smithy.api#documentation" => "<p>The Group ID of the placement group. You must specify the Placement Group <b>Group ID</b> to launch an instance in a shared placement\n            group.</p>", "smithy.api#xmlName" => "groupId"}))
