    LockSnapshotRequest.add_member(:snapshot_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotId, location_name: 'SnapshotId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the snapshot to lock.</p>", "smithy.api#required" => {}}))
    LockSnapshotRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually making the request, \n   and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. \n   Otherwise, it is <code>UnauthorizedOperation</code>.</p>"}))
    LockSnapshotRequest.add_member(:lock_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: LockMode, location_name: 'LockMode', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The mode in which to lock the snapshot. Specify one of the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>governance</code> - Locks the snapshot in governance mode. Snapshots locked in governance \n          mode can't be deleted until one of the following conditions are met:</p>\n               <ul>\n                  <li>\n                     <p>The lock duration expires.</p>\n                  </li>\n                  <li>\n                     <p>The snapshot is unlocked by a user with the appropriate permissions.</p>\n                  </li>\n               </ul>\n               <p>Users with the appropriate IAM permissions can unlock the snapshot, increase or decrease the lock \n          duration, and change the lock mode to <code>compliance</code> at any time.</p>\n               <p>If you lock a snapshot in <code>governance</code> mode, omit <b>\n          CoolOffPeriod</b>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>compliance</code> - Locks the snapshot in compliance mode. Snapshots locked in compliance \n          mode can't be unlocked by any user. They can be deleted only after the lock duration expires. Users \n          can't decrease the lock duration or change the lock mode to <code>governance</code>. However, users \n          with appropriate IAM permissions can increase the lock duration at any time.</p>\n               <p>If you lock a snapshot in <code>compliance</code> mode, you can optionally specify \n          <b>CoolOffPeriod</b>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    LockSnapshotRequest.add_member(:cool_off_period, Smithy::Schema::Shapes::ShapeRef.new(shape: CoolOffPeriodRequestHours, location_name: 'CoolOffPeriod', traits: {"smithy.api#documentation" => "<p>The cooling-off period during which you can unlock the snapshot or modify the lock settings after \n      locking the snapshot in compliance mode, in hours. After the cooling-off period expires, you can't \n      unlock or delete the snapshot, decrease the lock duration, or change the lock mode. You can increase \n      the lock duration after the cooling-off period expires.</p>\n         <p>The cooling-off period is optional when locking a snapshot in compliance mode. If you are locking \n      the snapshot in governance mode, omit this parameter.</p>\n         <p>To lock the snapshot in compliance mode immediately without a cooling-off period, omit this \n      parameter.</p>\n         <p>If you are extending the lock duration for a snapshot that is locked in compliance mode after \n      the cooling-off period has expired, omit this parameter. If you specify a cooling-period in a such \n      a request, the request fails.</p>\n         <p>Allowed values: Min 1, max 72.</p>"}))
    LockSnapshotRequest.add_member(:lock_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: RetentionPeriodRequestDays, location_name: 'LockDuration', traits: {"smithy.api#documentation" => "<p>The period of time for which to lock the snapshot, in days. The snapshot lock will automatically \n      expire after this period lapses.</p>\n         <p>You must specify either this parameter or <b>ExpirationDate</b>, but \n      not both.</p>\n         <p>Allowed values: Min: 1, max 36500</p>"}))
    LockSnapshotRequest.add_member(:expiration_date, Smithy::Schema::Shapes::ShapeRef.new(shape: MillisecondDateTime, location_name: 'ExpirationDate', traits: {"smithy.api#documentation" => "<p>The date and time at which the snapshot lock is to automatically expire, in the UTC time zone \n      (<code>YYYY-MM-DDThh:mm:ss.sssZ</code>).</p>\n         <p>You must specify either this parameter or <b>LockDuration</b>, but \n      not both.</p>"}))
    LockSnapshotRequest.type = Types::LockSnapshotRequest
    LockSnapshotResult.add_member(:snapshot_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshotId', traits: {"aws.protocols#ec2QueryName" => "SnapshotId", "smithy.api#documentation" => "<p>The ID of the snapshot</p>", "smithy.api#xmlName" => "snapshotId"}))
    LockSnapshotResult.add_member(:lock_state, Smithy::Schema::Shapes::ShapeRef.new(shape: LockState, location_name: 'LockState', traits: {"aws.protocols#ec2QueryName" => "LockState", "smithy.api#documentation" => "<p>The state of the snapshot lock. Valid states include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>compliance-cooloff</code> - The snapshot has been locked in \n          compliance mode but it is still within the cooling-off period. The snapshot can't be \n          deleted, but it can be unlocked and the lock settings can be modified by users with \n          appropriate permissions.</p>\n            </li>\n            <li>\n               <p>\n                  <code>governance</code> - The snapshot is locked in governance mode. The \n          snapshot can't be deleted, but it can be unlocked and the lock settings can be \n          modified by users with appropriate permissions.</p>\n            </li>\n            <li>\n               <p>\n                  <code>compliance</code> - The snapshot is locked in compliance mode and the \n          cooling-off period has expired. The snapshot can't be unlocked or deleted. The lock \n          duration can only be increased by users with appropriate permissions.</p>\n            </li>\n            <li>\n               <p>\n                  <code>expired</code> - The snapshot was locked in compliance or governance \n          mode but the lock duration has expired. The snapshot is not locked and can be deleted.</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "lockState"}))
    LockSnapshotResult.add_member(:lock_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: RetentionPeriodResponseDays, location_name: 'LockDuration', traits: {"aws.protocols#ec2QueryName" => "LockDuration", "smithy.api#documentation" => "<p>The period of time for which the snapshot is locked, in days.</p>", "smithy.api#xmlName" => "lockDuration"}))
    LockSnapshotResult.add_member(:cool_off_period, Smithy::Schema::Shapes::ShapeRef.new(shape: CoolOffPeriodResponseHours, location_name: 'CoolOffPeriod', traits: {"aws.protocols#ec2QueryName" => "CoolOffPeriod", "smithy.api#documentation" => "<p>The compliance mode cooling-off period, in hours.</p>", "smithy.api#xmlName" => "coolOffPeriod"}))
    LockSnapshotResult.add_member(:cool_off_period_expires_on, Smithy::Schema::Shapes::ShapeRef.new(shape: MillisecondDateTime, location_name: 'CoolOffPeriodExpiresOn', traits: {"aws.protocols#ec2QueryName" => "CoolOffPeriodExpiresOn", "smithy.api#documentation" => "<p>The date and time at which the compliance mode cooling-off period expires, in the UTC time zone \n      (<code>YYYY-MM-DDThh:mm:ss.sssZ</code>).</p>", "smithy.api#xmlName" => "coolOffPeriodExpiresOn"}))
