    ModifyClientVpnEndpointRequest.add_member(:connection_log_options, Smithy::Schema::Shapes::ShapeRef.new(shape: ConnectionLogOptions, location_name: 'ConnectionLogOptions', traits: {"smithy.api#documentation" => "<p>Information about the client connection logging options.</p>\n         <p>If you enable client connection logging, data about client connections is sent to a\n\t\t\tCloudwatch Logs log stream. The following information is logged:</p>\n         <ul>\n            <li>\n               <p>Client connection requests</p>\n            </li>\n            <li>\n               <p>Client connection results (successful and unsuccessful)</p>\n            </li>\n            <li>\n               <p>Reasons for unsuccessful client connection requests</p>\n            </li>\n            <li>\n               <p>Client connection termination time</p>\n            </li>\n         </ul>"}))
