    ModifyClientVpnEndpointRequest.add_member(:vpn_port, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'VpnPort', traits: {"smithy.api#documentation" => "<p>The port number to assign to the Client VPN endpoint for TCP and UDP traffic.</p>\n         <p>Valid Values: <code>443</code> | <code>1194</code>\n         </p>\n         <p>Default Value: <code>443</code>\n         </p>"}))
