    ModifyClientVpnEndpointRequest.add_member(:session_timeout_hours, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'SessionTimeoutHours', traits: {"smithy.api#documentation" => "<p>The maximum VPN session duration time in hours.</p>\n         <p>Valid values: <code>8 | 10 | 12 | 24</code>\n         </p>\n         <p>Default value: <code>24</code>\n         </p>"}))
    ModifyClientVpnEndpointRequest.add_member(:client_login_banner_options, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientLoginBannerOptions, location_name: 'ClientLoginBannerOptions', traits: {"smithy.api#documentation" => "<p>Options for enabling a customizable text banner that will be displayed on\n\t\t\tAmazon Web Services provided clients when a VPN session is established.</p>"}))
    ModifyClientVpnEndpointRequest.add_member(:client_route_enforcement_options, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientRouteEnforcementOptions, location_name: 'ClientRouteEnforcementOptions', traits: {"smithy.api#documentation" => "<p>Client route enforcement is a feature of the Client VPN service that helps enforce administrator defined routes on devices connected through the VPN. T\n\t\this feature helps improve your security posture by ensuring that network traffic originating from a connected client is not inadvertently sent outside the VPN tunnel.</p>\n         <p>Client route enforcement works by monitoring the route table of a connected device for routing policy changes to the VPN connection. If the feature detects any VPN routing policy modifications, it will automatically force an update to the route table, \n\t\t\treverting it back to the expected route configurations.</p>"}))
    ModifyClientVpnEndpointRequest.add_member(:disconnect_on_session_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DisconnectOnSessionTimeout', traits: {"smithy.api#documentation" => "<p>Indicates whether the client VPN session is disconnected after the maximum timeout specified in <code>sessionTimeoutHours</code> is reached. If <code>true</code>, users are prompted to reconnect client VPN. If <code>false</code>, client VPN attempts to reconnect automatically. The default value is <code>true</code>.</p>"}))
