    ModifyHostsRequest.add_member(:host_maintenance, Smithy::Schema::Shapes::ShapeRef.new(shape: HostMaintenance, location_name: 'HostMaintenance', traits: {"smithy.api#documentation" => "<p>Indicates whether to enable or disable host maintenance for the Dedicated Host. For\n            more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/dedicated-hosts-maintenance.html\">Host\n                maintenance</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
