    ModifyImageAttributeRequest.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageId, location_name: 'ImageId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the AMI.</p>", "smithy.api#required" => {}}))
    ModifyImageAttributeRequest.add_member(:launch_permission, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchPermissionModifications, location_name: 'LaunchPermission', traits: {"smithy.api#documentation" => "<p>A new launch permission for the AMI.</p>"}))
    ModifyImageAttributeRequest.add_member(:operation_type, Smithy::Schema::Shapes::ShapeRef.new(shape: OperationType, location_name: 'OperationType', traits: {"smithy.api#documentation" => "<p>The operation type. This parameter can be used only when the <code>Attribute</code>\n      parameter is <code>launchPermission</code>.</p>"}))
