    ModifyImageAttributeRequest.add_member(:value, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Value', traits: {"smithy.api#documentation" => "<p>The value of the attribute being modified. This parameter can be used only when the\n        <code>Attribute</code> parameter is <code>description</code> or\n      <code>imdsSupport</code>.</p>"}))
    ModifyImageAttributeRequest.add_member(:organization_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: OrganizationArnStringList, location_name: 'OrganizationArns', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an organization. This parameter can be used only when\n      the <code>Attribute</code> parameter is <code>launchPermission</code>.</p>", "smithy.api#xmlName" => "OrganizationArn"}))
    ModifyImageAttributeRequest.add_member(:organizational_unit_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: OrganizationalUnitArnStringList, location_name: 'OrganizationalUnitArns', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an organizational unit (OU). This parameter can be used\n      only when the <code>Attribute</code> parameter is <code>launchPermission</code>.</p>", "smithy.api#xmlName" => "OrganizationalUnitArn"}))
    ModifyImageAttributeRequest.add_member(:imds_support, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValue, location_name: 'ImdsSupport', traits: {"smithy.api#documentation" => "<p>Set to <code>v2.0</code> to indicate that IMDSv2 is specified in the AMI. Instances\n      launched from this AMI will have <code>HttpTokens</code> automatically set to\n        <code>required</code> so that, by default, the instance requires that IMDSv2 is used when\n      requesting instance metadata. In addition, <code>HttpPutResponseHopLimit</code> is set to\n        <code>2</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/configuring-IMDS-new-instances.html#configure-IMDS-new-instances-ami-configuration\">Configure the AMI</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <important>\n            <p>Do not use this parameter unless your AMI software supports IMDSv2. After you set the\n        value to <code>v2.0</code>, you can't undo it. The only way to “reset” your AMI is to create\n        a new AMI from the underlying snapshot.</p>\n         </important>"}))
    ModifyImageAttributeRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"aws.protocols#ec2QueryName" => "DryRun", "smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually making the request, \n\t\t\tand provides an error response. If you have the required permissions, the error response is \n\t\t\t<code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.</p>", "smithy.api#xmlName" => "dryRun"}))
    ModifyImageAttributeRequest.type = Types::ModifyImageAttributeRequest
    ModifyInstanceAttributeRequest.add_member(:source_dest_check, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'SourceDestCheck', traits: {"smithy.api#documentation" => "<p>Enable or disable source/destination checks, which ensure that the instance is either\n            the source or the destination of any traffic that it receives. If the value is\n                <code>true</code>, source/destination checks are enabled; otherwise, they are\n            disabled. The default value is <code>true</code>. You must disable source/destination\n            checks if the instance runs services such as network address translation, routing, or\n            firewalls.</p>"}))
    ModifyInstanceAttributeRequest.add_member(:disable_api_stop, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'DisableApiStop', traits: {"smithy.api#documentation" => "<p>Indicates whether an instance is enabled for stop protection. For more information,\n            see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-stop-protection.html\">Enable stop\n                protection for your instance</a>.</p>\n         <p></p>"}))
    ModifyInstanceAttributeRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"aws.protocols#ec2QueryName" => "DryRun", "smithy.api#documentation" => "<p>Checks whether you have the required permissions for the operation, without actually making the \n  request, and provides an error response. If you have the required permissions, the error response is \n  <code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.</p>", "smithy.api#xmlName" => "dryRun"}))
    ModifyInstanceAttributeRequest.add_member(:instance_id, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceId, location_name: 'InstanceId', traits: {"aws.protocols#ec2QueryName" => "InstanceId", "smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the instance.</p>", "smithy.api#required" => {}, "smithy.api#xmlName" => "instanceId"}))
    ModifyInstanceAttributeRequest.add_member(:attribute, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceAttributeName, location_name: 'Attribute', traits: {"aws.protocols#ec2QueryName" => "Attribute", "smithy.api#documentation" => "<p>The name of the attribute to modify.</p>\n         <note>\n            <p>When changing the instance type: If the original instance type is configured for\n                configurable bandwidth, and the desired instance type doesn't support configurable\n                bandwidth, first set the existing bandwidth configuration to <code>default</code>\n                using the <a>ModifyInstanceNetworkPerformanceOptions</a>\n                operation.</p>\n         </note>\n         <important>\n            <p>You can modify the following attributes only: <code>disableApiTermination</code> |\n                    <code>instanceType</code> | <code>kernel</code> | <code>ramdisk</code> |\n                    <code>instanceInitiatedShutdownBehavior</code> | <code>blockDeviceMapping</code>\n                | <code>userData</code> | <code>sourceDestCheck</code> | <code>groupSet</code> |\n                    <code>ebsOptimized</code> | <code>sriovNetSupport</code> |\n                    <code>enaSupport</code> | <code>nvmeSupport</code> | <code>disableApiStop</code>\n                | <code>enclaveOptions</code>\n            </p>\n         </important>", "smithy.api#xmlName" => "attribute"}))
    ModifyInstanceAttributeRequest.add_member(:value, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Value', traits: {"aws.protocols#ec2QueryName" => "Value", "smithy.api#documentation" => "<p>A new value for the attribute. Use only with the <code>kernel</code>,\n                <code>ramdisk</code>, <code>userData</code>, <code>disableApiTermination</code>, or\n                <code>instanceInitiatedShutdownBehavior</code> attribute.</p>", "smithy.api#xmlName" => "value"}))
    ModifyInstanceAttributeRequest.add_member(:block_device_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceBlockDeviceMappingSpecificationList, location_name: 'BlockDeviceMappings', traits: {"aws.protocols#ec2QueryName" => "BlockDeviceMapping", "smithy.api#documentation" => "<p>Modifies the <code>DeleteOnTermination</code> attribute for volumes that are currently\n            attached. The volume must be owned by the caller. If no value is specified for\n                <code>DeleteOnTermination</code>, the default is <code>true</code> and the volume is\n            deleted when the instance is terminated. You can't modify the <code>DeleteOnTermination</code> \n            attribute for volumes that are attached to Amazon Web Services-managed resources.</p>\n         <p>To add instance store volumes to an Amazon EBS-backed instance, you must add them when\n            you launch the instance. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/block-device-mapping-concepts.html#Using_OverridingAMIBDM\">Update the block device mapping when launching an instance</a> in the\n                <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "blockDeviceMapping"}))
    ModifyInstanceAttributeRequest.add_member(:disable_api_termination, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'DisableApiTermination', traits: {"aws.protocols#ec2QueryName" => "DisableApiTermination", "smithy.api#documentation" => "<p>Enable or disable termination protection for the instance. If the value is <code>true</code>, \n            you can't terminate the instance using the Amazon EC2 console, command line interface, or API. \n            You can't enable termination protection for Spot Instances.</p>", "smithy.api#xmlName" => "disableApiTermination"}))
    ModifyInstanceAttributeRequest.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValue, location_name: 'InstanceType', traits: {"aws.protocols#ec2QueryName" => "InstanceType", "smithy.api#documentation" => "<p>Changes the instance type to the specified value. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html\">Instance\n                types</a> in the <i>Amazon EC2 User Guide</i>. If the instance type is\n            not valid, the error returned is <code>InvalidInstanceAttributeValue</code>.</p>", "smithy.api#xmlName" => "instanceType"}))
    ModifyInstanceAttributeRequest.add_member(:kernel, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValue, location_name: 'Kernel', traits: {"aws.protocols#ec2QueryName" => "Kernel", "smithy.api#documentation" => "<p>Changes the instance's kernel to the specified value. We recommend that you use\n            PV-GRUB instead of kernels and RAM disks. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/UserProvidedKernels.html\">PV-GRUB</a>.</p>", "smithy.api#xmlName" => "kernel"}))
    ModifyInstanceAttributeRequest.add_member(:ramdisk, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValue, location_name: 'Ramdisk', traits: {"aws.protocols#ec2QueryName" => "Ramdisk", "smithy.api#documentation" => "<p>Changes the instance's RAM disk to the specified value. We recommend that you use\n            PV-GRUB instead of kernels and RAM disks. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/UserProvidedKernels.html\">PV-GRUB</a>.</p>", "smithy.api#xmlName" => "ramdisk"}))
    ModifyInstanceAttributeRequest.add_member(:user_data, Smithy::Schema::Shapes::ShapeRef.new(shape: BlobAttributeValue, location_name: 'UserData', traits: {"aws.protocols#ec2QueryName" => "UserData", "smithy.api#documentation" => "<p>Changes the instance's user data to the specified value. User data must be base64-encoded.\n            Depending on the tool or SDK that you're using, the base64-encoding might be performed for you.\n            For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instancedata-add-user-data.html\">Work with instance user data</a>.</p>", "smithy.api#xmlName" => "userData"}))
    ModifyInstanceAttributeRequest.add_member(:instance_initiated_shutdown_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValue, location_name: 'InstanceInitiatedShutdownBehavior', traits: {"aws.protocols#ec2QueryName" => "InstanceInitiatedShutdownBehavior", "smithy.api#documentation" => "<p>Specifies whether an instance stops or terminates when you initiate shutdown from the\n            instance (using the operating system command for system shutdown).</p>", "smithy.api#xmlName" => "instanceInitiatedShutdownBehavior"}))
    ModifyInstanceAttributeRequest.add_member(:groups, Smithy::Schema::Shapes::ShapeRef.new(shape: GroupIdStringList, location_name: 'Groups', traits: {"smithy.api#documentation" => "<p>Replaces the security groups of the instance with the specified security groups.\n            You must specify the ID of at least one security group, even if it's just the default\n            security group for the VPC.</p>", "smithy.api#xmlName" => "GroupId"}))
    ModifyInstanceAttributeRequest.add_member(:ebs_optimized, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'EbsOptimized', traits: {"aws.protocols#ec2QueryName" => "EbsOptimized", "smithy.api#documentation" => "<p>Specifies whether the instance is optimized for Amazon EBS I/O. This optimization\n            provides dedicated throughput to Amazon EBS and an optimized configuration stack to\n            provide optimal EBS I/O performance. This optimization isn't available with all instance\n            types. Additional usage charges apply when using an EBS Optimized instance.</p>", "smithy.api#xmlName" => "ebsOptimized"}))
    ModifyInstanceAttributeRequest.add_member(:sriov_net_support, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValue, location_name: 'SriovNetSupport', traits: {"aws.protocols#ec2QueryName" => "SriovNetSupport", "smithy.api#documentation" => "<p>Set to <code>simple</code> to enable enhanced networking with the Intel 82599 Virtual\n            Function interface for the instance.</p>\n         <p>There is no way to disable enhanced networking with the Intel 82599 Virtual Function\n            interface at this time.</p>\n         <p>This option is supported only for HVM instances. Specifying this option with a PV\n            instance can make it unreachable.</p>", "smithy.api#xmlName" => "sriovNetSupport"}))
    ModifyInstanceAttributeRequest.add_member(:ena_support, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'EnaSupport', traits: {"aws.protocols#ec2QueryName" => "EnaSupport", "smithy.api#documentation" => "<p>Set to <code>true</code> to enable enhanced networking with ENA for the\n            instance.</p>\n         <p>This option is supported only for HVM instances. Specifying this option with a PV\n            instance can make it unreachable.</p>", "smithy.api#xmlName" => "enaSupport"}))
