    ModifyInstanceMaintenanceOptionsRequest.add_member(:auto_recovery, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceAutoRecoveryState, location_name: 'AutoRecovery', traits: {"smithy.api#documentation" => "<p>Disables the automatic recovery behavior of your instance or sets it to\n            default.</p>"}))
    ModifyInstanceMaintenanceOptionsRequest.add_member(:reboot_migration, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRebootMigrationState, location_name: 'RebootMigration', traits: {"smithy.api#documentation" => "<p>Specifies whether to attempt reboot migration during a user-initiated reboot of an\n            instance that has a scheduled <code>system-reboot</code> event:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>default</code> - Amazon EC2 attempts to migrate the instance to\n                    new hardware (reboot migration). If successful, the <code>system-reboot</code>\n                    event is cleared. If unsuccessful, an in-place reboot occurs and the event\n                    remains scheduled.</p>\n            </li>\n            <li>\n               <p>\n                  <code>disabled</code> - Amazon EC2 keeps the instance on the same\n                    hardware (in-place reboot). The <code>system-reboot</code> event remains\n                    scheduled.</p>\n            </li>\n         </ul>\n         <p>This setting only applies to supported instances that have a scheduled reboot event.\n            For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/schedevents_actions_reboot.html#reboot-migration\">Enable or disable reboot migration</a> in the\n            <i>Amazon EC2 User Guide</i>.</p>"}))
    ModifyInstanceMaintenanceOptionsRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually\n            making the request, and provides an error response. If you have the required\n            permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is\n            <code>UnauthorizedOperation</code>.</p>"}))
    ModifyInstanceMaintenanceOptionsRequest.type = Types::ModifyInstanceMaintenanceOptionsRequest
    ModifyInstanceMaintenanceOptionsResult.add_member(:instance_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'InstanceId', traits: {"aws.protocols#ec2QueryName" => "InstanceId", "smithy.api#documentation" => "<p>The ID of the instance.</p>", "smithy.api#xmlName" => "instanceId"}))
    ModifyInstanceMaintenanceOptionsResult.add_member(:auto_recovery, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceAutoRecoveryState, location_name: 'AutoRecovery', traits: {"aws.protocols#ec2QueryName" => "AutoRecovery", "smithy.api#documentation" => "<p>Provides information on the current automatic recovery behavior of your\n            instance.</p>", "smithy.api#xmlName" => "autoRecovery"}))
    ModifyInstanceMaintenanceOptionsResult.add_member(:reboot_migration, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRebootMigrationState, location_name: 'RebootMigration', traits: {"aws.protocols#ec2QueryName" => "RebootMigration", "smithy.api#documentation" => "<p>Specifies whether to attempt reboot migration during a user-initiated reboot of an\n            instance that has a scheduled <code>system-reboot</code> event:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>default</code> - Amazon EC2 attempts to migrate the instance to\n                    new hardware (reboot migration). If successful, the <code>system-reboot</code>\n                    event is cleared. If unsuccessful, an in-place reboot occurs and the event\n                    remains scheduled.</p>\n            </li>\n            <li>\n               <p>\n                  <code>disabled</code> - Amazon EC2 keeps the instance on the same\n                    hardware (in-place reboot). The <code>system-reboot</code> event remains\n                    scheduled.</p>\n            </li>\n         </ul>\n         <p>This setting only applies to supported instances that have a scheduled reboot event.\n            For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/schedevents_actions_reboot.html#reboot-migration\">Enable or disable reboot migration</a> in the\n            <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "rebootMigration"}))
    ModifyInstanceMaintenanceOptionsResult.type = Types::ModifyInstanceMaintenanceOptionsResult
    ModifyInstanceMetadataDefaultsRequest.add_member(:http_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: MetadataDefaultHttpTokensState, location_name: 'HttpTokens', traits: {"smithy.api#documentation" => "<p>Indicates whether IMDSv2 is required.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>optional</code> – IMDSv2 is optional, which means that you can\n                    use either IMDSv2 or IMDSv1.</p>\n            </li>\n            <li>\n               <p>\n                  <code>required</code> – IMDSv2 is required, which means that IMDSv1 is\n                    disabled, and you must use IMDSv2.</p>\n            </li>\n         </ul>"}))
    ModifyInstanceMetadataDefaultsRequest.add_member(:http_put_response_hop_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'HttpPutResponseHopLimit', traits: {"smithy.api#documentation" => "<p>The maximum number of hops that the metadata token can travel. To indicate no\n            preference, specify <code>-1</code>.</p>\n         <p>Possible values: Integers from <code>1</code> to <code>64</code>, and <code>-1</code>\n            to indicate no preference</p>"}))
    ModifyInstanceMetadataDefaultsRequest.add_member(:http_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: DefaultInstanceMetadataEndpointState, location_name: 'HttpEndpoint', traits: {"smithy.api#documentation" => "<p>Enables or disables the IMDS endpoint on an instance. When disabled, the instance\n            metadata can't be accessed.</p>"}))
    ModifyInstanceMetadataDefaultsRequest.add_member(:instance_metadata_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: DefaultInstanceMetadataTagsState, location_name: 'InstanceMetadataTags', traits: {"smithy.api#documentation" => "<p>Enables or disables access to an instance's tags from the instance metadata. For more\n            information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/Using_Tags.html#work-with-tags-in-IMDS\">Work with\n                instance tags using the instance metadata</a> in the\n                <i>Amazon EC2 User Guide</i>.</p>"}))
