    ModifyInstanceMetadataDefaultsResult.type = Types::ModifyInstanceMetadataDefaultsResult
    ModifyInstanceMetadataOptionsRequest.add_member(:instance_id, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceId, location_name: 'InstanceId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the instance.</p>", "smithy.api#required" => {}}))
    ModifyInstanceMetadataOptionsRequest.add_member(:http_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: HttpTokensState, location_name: 'HttpTokens', traits: {"smithy.api#documentation" => "<p>Indicates whether IMDSv2 is required.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>optional</code> - IMDSv2 is optional. You can choose whether to send a \n                    session token in your instance metadata retrieval requests. If you retrieve \n                    IAM role credentials without a session token, you receive the IMDSv1 role \n                    credentials. If you retrieve IAM role credentials using a valid session token, \n                    you receive the IMDSv2 role credentials.</p>\n            </li>\n            <li>\n               <p>\n                  <code>required</code> - IMDSv2 is required. You must send a session token \n                    in your instance metadata retrieval requests. With this option, retrieving the \n                    IAM role credentials always returns IMDSv2 credentials; IMDSv1 credentials are \n                    not available.</p>\n            </li>\n         </ul>\n         <p>Default:</p>\n         <ul>\n            <li>\n               <p>If the value of <code>ImdsSupport</code> for the Amazon Machine Image (AMI)\n                    for your instance is <code>v2.0</code> and the account level default is set to\n                    <code>no-preference</code>, the default is <code>required</code>.</p>\n            </li>\n            <li>\n               <p>If the value of <code>ImdsSupport</code> for the Amazon Machine Image (AMI)\n                    for your instance is <code>v2.0</code>, but the account level default is set to\n                    <code>V1 or V2</code>, the default is <code>optional</code>.</p>\n            </li>\n         </ul>\n         <p>The default value can also be affected by other combinations of parameters. For more\n            information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/configuring-instance-metadata-options.html#instance-metadata-options-order-of-precedence\">Order of precedence for instance metadata options</a> in the\n            <i>Amazon EC2 User Guide</i>.</p>"}))
    ModifyInstanceMetadataOptionsRequest.add_member(:http_put_response_hop_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'HttpPutResponseHopLimit', traits: {"smithy.api#documentation" => "<p>The desired HTTP PUT response hop limit for instance metadata requests. The larger the\n            number, the further instance metadata requests can travel. If no parameter is specified,\n            the existing state is maintained.</p>\n         <p>Possible values: Integers from 1 to 64</p>"}))
    ModifyInstanceMetadataOptionsRequest.add_member(:http_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMetadataEndpointState, location_name: 'HttpEndpoint', traits: {"smithy.api#documentation" => "<p>Enables or disables the HTTP metadata endpoint on your instances. If this parameter is\n            not specified, the existing state is maintained.</p>\n         <p>If you specify a value of <code>disabled</code>, you cannot access your instance\n            metadata.</p>"}))
    ModifyInstanceMetadataOptionsRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually\n            making the request, and provides an error response. If you have the required\n            permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is\n                <code>UnauthorizedOperation</code>.</p>"}))
    ModifyInstanceMetadataOptionsRequest.add_member(:http_protocol_ipv6, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMetadataProtocolState, location_name: 'HttpProtocolIpv6', traits: {"smithy.api#documentation" => "<p>Enables or disables the IPv6 endpoint for the instance metadata service. \n            Applies only if you enabled the HTTP metadata endpoint.</p>"}))
    ModifyInstanceMetadataOptionsRequest.add_member(:instance_metadata_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMetadataTagsState, location_name: 'InstanceMetadataTags', traits: {"smithy.api#documentation" => "<p>Set to <code>enabled</code> to allow access to instance tags from the instance\n            metadata. Set to <code>disabled</code> to turn off access to instance tags from the\n            instance metadata. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/Using_Tags.html#work-with-tags-in-IMDS\">Work with\n                instance tags using the instance metadata</a>.</p>"}))
    ModifyInstanceMetadataOptionsRequest.type = Types::ModifyInstanceMetadataOptionsRequest
