    ModifyInstanceNetworkPerformanceRequest.add_member(:bandwidth_weighting, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceBandwidthWeighting, location_name: 'BandwidthWeighting', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specify the bandwidth weighting option to boost the associated type of baseline bandwidth, as follows:</p>\n         <dl>\n            <dt>default</dt>\n            <dd>\n               <p>This option uses the standard bandwidth configuration for your instance type.</p>\n            </dd>\n            <dt>vpc-1</dt>\n            <dd>\n               <p>This option boosts your networking baseline bandwidth and reduces your EBS \n                        baseline bandwidth.</p>\n            </dd>\n            <dt>ebs-1</dt>\n            <dd>\n               <p>This option boosts your EBS baseline bandwidth and reduces your networking \n                        baseline bandwidth.</p>\n            </dd>\n         </dl>", "smithy.api#required" => {}}))
    ModifyInstanceNetworkPerformanceRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks whether you have the required permissions for the operation, without actually making the \n  request, and provides an error response. If you have the required permissions, the error response is \n  <code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.</p>"}))
