    ModifyInstanceNetworkPerformanceResult.add_member(:bandwidth_weighting, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceBandwidthWeighting, location_name: 'BandwidthWeighting', traits: {"aws.protocols#ec2QueryName" => "BandwidthWeighting", "smithy.api#documentation" => "<p>Contains the updated configuration for bandwidth weighting on the specified instance.</p>", "smithy.api#xmlName" => "bandwidthWeighting"}))
