    ModifyInstancePlacementRequest.add_member(:group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: PlacementGroupName, location_name: 'GroupName', traits: {"smithy.api#documentation" => "<p>The name of the placement group in which to place the instance. For spread placement\n            groups, the instance must have a tenancy of <code>default</code>. For cluster and\n            partition placement groups, the instance must have a tenancy of <code>default</code> or\n                <code>dedicated</code>.</p>\n         <p>To remove an instance from a placement group, specify an empty string (\"\").</p>"}))
    ModifyInstancePlacementRequest.add_member(:partition_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'PartitionNumber', traits: {"smithy.api#documentation" => "<p>The number of the partition in which to place the instance. Valid only if the\n            placement group strategy is set to <code>partition</code>.</p>"}))
    ModifyInstancePlacementRequest.add_member(:host_resource_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'HostResourceGroupArn', traits: {"smithy.api#documentation" => "<p>The ARN of the host resource group in which to place the instance. The instance must\n            have a tenancy of <code>host</code> to specify this parameter.</p>"}))
    ModifyInstancePlacementRequest.add_member(:group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: PlacementGroupId, location_name: 'GroupId', traits: {"smithy.api#documentation" => "<p>The Group Id of a placement group. You must specify the Placement Group <b>Group Id</b> to launch an instance in a shared placement\n            group.</p>"}))
    ModifyInstancePlacementRequest.add_member(:instance_id, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceId, location_name: 'InstanceId', traits: {"aws.protocols#ec2QueryName" => "InstanceId", "smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the instance that you are modifying.</p>", "smithy.api#required" => {}, "smithy.api#xmlName" => "instanceId"}))
    ModifyInstancePlacementRequest.add_member(:tenancy, Smithy::Schema::Shapes::ShapeRef.new(shape: HostTenancy, location_name: 'Tenancy', traits: {"aws.protocols#ec2QueryName" => "Tenancy", "smithy.api#documentation" => "<p>The tenancy for the instance.</p>\n         <note>\n            <p>For T3 instances, you must launch the instance on a Dedicated Host to use a\n                tenancy of <code>host</code>. You can't change the tenancy from\n                <code>host</code> to <code>dedicated</code> or <code>default</code>.\n                Attempting to make one of these unsupported tenancy changes results in an\n                <code>InvalidRequest</code> error code.</p>\n         </note>", "smithy.api#xmlName" => "tenancy"}))
    ModifyInstancePlacementRequest.add_member(:affinity, Smithy::Schema::Shapes::ShapeRef.new(shape: Affinity, location_name: 'Affinity', traits: {"aws.protocols#ec2QueryName" => "Affinity", "smithy.api#documentation" => "<p>The affinity setting for the instance. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/how-dedicated-hosts-work.html#dedicated-hosts-affinity\">Host affinity</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "affinity"}))
