    ModifyIpamPoolRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>The description of the IPAM pool you want to modify.</p>"}))
    ModifyIpamPoolRequest.add_member(:auto_import, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AutoImport', traits: {"smithy.api#documentation" => "<p>If true, IPAM will continuously look for resources within the CIDR range of this pool \n         and automatically import them as allocations into your IPAM. The CIDRs that will be allocated for\n         these resources must not already be allocated to other resources in order for the import to succeed. IPAM will import \n         a CIDR regardless of its compliance with the pool's allocation rules, so a resource might be imported and subsequently \n         marked as noncompliant. If IPAM discovers multiple CIDRs that overlap, IPAM will import the largest CIDR only. If IPAM \n         discovers multiple CIDRs with matching CIDRs, IPAM will randomly import one of them only.\n      </p>\n         <p>A locale must be set on the pool for this feature to work.</p>"}))
    ModifyIpamPoolRequest.add_member(:allocation_min_netmask_length, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamNetmaskLength, location_name: 'AllocationMinNetmaskLength', traits: {"smithy.api#documentation" => "<p>The minimum netmask length required for CIDR allocations in this IPAM pool to be compliant. Possible \n         netmask lengths for IPv4 addresses are 0 - 32. Possible netmask lengths for IPv6 addresses are  0 - 128. The minimum netmask \n         length must be less than the maximum netmask length.</p>"}))
    ModifyIpamPoolRequest.add_member(:allocation_max_netmask_length, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamNetmaskLength, location_name: 'AllocationMaxNetmaskLength', traits: {"smithy.api#documentation" => "<p>The maximum netmask length possible for CIDR allocations in this IPAM pool to be compliant. Possible \n         netmask lengths for IPv4 addresses are 0 - 32. Possible netmask lengths for IPv6 addresses are  0 - 128.The maximum netmask \n         length must be greater than the minimum netmask length.</p>"}))
    ModifyIpamPoolRequest.add_member(:allocation_default_netmask_length, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamNetmaskLength, location_name: 'AllocationDefaultNetmaskLength', traits: {"smithy.api#documentation" => "<p>The default netmask length for allocations added to this pool. If, for example, the CIDR assigned to this pool is 10.0.0.0/8 and you enter 16 here, new allocations will default to 10.0.0.0/16.</p>"}))
    ModifyIpamPoolRequest.add_member(:clear_allocation_default_netmask_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ClearAllocationDefaultNetmaskLength', traits: {"smithy.api#documentation" => "<p>Clear the default netmask length allocation rule for this pool.</p>"}))
    ModifyIpamPoolRequest.add_member(:add_allocation_resource_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: RequestIpamResourceTagList, location_name: 'AddAllocationResourceTags', traits: {"smithy.api#documentation" => "<p>Add tag allocation rules to a pool. For more information about allocation rules, see <a href=\"https://docs.aws.amazon.com/vpc/latest/ipam/create-top-ipam.html\">Create a top-level pool</a> in the <i>Amazon VPC IPAM User Guide</i>.</p>", "smithy.api#xmlName" => "AddAllocationResourceTag"}))
