    ModifyIpamRequest.add_member(:tier, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamTier, location_name: 'Tier', traits: {"smithy.api#documentation" => "<p>IPAM is offered in a Free Tier and an Advanced Tier. For more information about the features available in each tier and the costs associated with the tiers, see <a href=\"http://aws.amazon.com/vpc/pricing/\">Amazon VPC pricing > IPAM tab</a>.</p>"}))
    ModifyIpamRequest.add_member(:enable_private_gua, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnablePrivateGua', traits: {"smithy.api#documentation" => "<p>Enable this option to use your own GUA ranges as private IPv6 addresses. This option is disabled by default.</p>"}))
    ModifyIpamRequest.add_member(:metered_account, Smithy::Schema::Shapes::ShapeRef.new(shape: IpamMeteredAccount, location_name: 'MeteredAccount', traits: {"smithy.api#documentation" => "<p>A metered account is an Amazon Web Services account that is charged for active IP addresses managed in IPAM. For more information, see <a href=\"https://docs.aws.amazon.com/vpc/latest/ipam/ipam-enable-cost-distro.html\">Enable cost distribution</a> in the <i>Amazon VPC IPAM User Guide</i>.</p>\n         <p>Possible values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ipam-owner</code> (default): The Amazon Web Services account which owns the IPAM is charged for all active IP addresses managed in IPAM.</p>\n            </li>\n            <li>\n               <p>\n                  <code>resource-owner</code>: The Amazon Web Services account that owns the IP address is charged for the active IP address.</p>\n            </li>\n         </ul>"}))
