    ModifyNetworkInterfaceAttributeRequest.add_member(:source_dest_check, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'SourceDestCheck', traits: {"aws.protocols#ec2QueryName" => "SourceDestCheck", "smithy.api#documentation" => "<p>Enable or disable source/destination checks, which ensure that the instance is either\n            the source or the destination of any traffic that it receives. If the value is\n                <code>true</code>, source/destination checks are enabled; otherwise, they are\n            disabled. The default value is <code>true</code>. You must disable source/destination\n            checks if the instance runs services such as network address translation, routing, or\n            firewalls.</p>", "smithy.api#xmlName" => "sourceDestCheck"}))
