    ModifyPrivateDnsNameOptionsRequest.add_member(:private_dns_hostname_type, Smithy::Schema::Shapes::ShapeRef.new(shape: HostnameType, location_name: 'PrivateDnsHostnameType', traits: {"smithy.api#documentation" => "<p>The type of hostname for EC2 instances. For IPv4 only subnets, an instance DNS name\n            must be based on the instance IPv4 address. For IPv6 only subnets, an instance DNS name\n            must be based on the instance ID. For dual-stack subnets, you can specify whether DNS\n            names use the instance IPv4 address or the instance ID.</p>"}))
