    ModifySubnetAttributeRequest.add_member(:map_public_ip_on_launch, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'MapPublicIpOnLaunch', traits: {"smithy.api#documentation" => "<p>Specify <code>true</code> to indicate that network interfaces attached to instances created in the\n            specified subnet should be assigned a public IPv4 address.</p>\n         <p>Amazon Web Services charges for all public IPv4 addresses, including public IPv4 addresses \nassociated with running instances and Elastic IP addresses. For more information, see the <i>Public IPv4 Address</i> tab on the <a href=\"http://aws.amazon.com/vpc/pricing/\">Amazon VPC pricing page</a>.</p>"}))
