    ModifySubnetAttributeRequest.add_member(:customer_owned_ipv4_pool, Smithy::Schema::Shapes::ShapeRef.new(shape: CoipPoolId, location_name: 'CustomerOwnedIpv4Pool', traits: {"smithy.api#documentation" => "<p>The customer-owned IPv4 address pool associated with the subnet.</p>\n         <p>You must set this value when you specify <code>true</code> for <code>MapCustomerOwnedIpOnLaunch</code>.</p>"}))
    ModifySubnetAttributeRequest.add_member(:enable_dns64, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'EnableDns64', traits: {"smithy.api#documentation" => "<p>Indicates whether DNS queries made to the Amazon-provided DNS Resolver in this subnet \n            should return synthetic IPv6 addresses for IPv4-only destinations.</p>\n         <p>You must first configure a NAT gateway in a public subnet (separate from the subnet \n           containing the IPv6-only workloads). For example, the subnet containing the NAT gateway \n           should have a <code>0.0.0.0/0</code> route pointing to the internet gateway. For more \n           information, see <a href=\"https://docs.aws.amazon.com/vpc/latest/userguide/nat-gateway-nat64-dns64.html#nat-gateway-nat64-dns64-walkthrough\">Configure DNS64 and NAT64</a> in the <i>Amazon VPC User Guide</i>.</p>"}))
    ModifySubnetAttributeRequest.add_member(:private_dns_hostname_type_on_launch, Smithy::Schema::Shapes::ShapeRef.new(shape: HostnameType, location_name: 'PrivateDnsHostnameTypeOnLaunch', traits: {"smithy.api#documentation" => "<p>The type of hostname to assign to instances in the subnet at launch. For IPv4-only and dual-stack (IPv4 and IPv6) subnets, an\n            instance DNS name can be based on the instance IPv4 address (ip-name) or the instance ID (resource-name). For IPv6 only subnets, an instance\n            DNS name must be based on the instance ID (resource-name).</p>"}))
    ModifySubnetAttributeRequest.add_member(:enable_resource_name_dns_a_record_on_launch, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'EnableResourceNameDnsARecordOnLaunch', traits: {"smithy.api#documentation" => "<p>Indicates whether to respond to DNS queries for instance hostnames with DNS A records.</p>"}))
    ModifySubnetAttributeRequest.add_member(:enable_resource_name_dns_aaaa_record_on_launch, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'EnableResourceNameDnsAAAARecordOnLaunch', traits: {"smithy.api#documentation" => "<p>Indicates whether to respond to DNS queries for instance hostnames with DNS AAAA records.</p>"}))
    ModifySubnetAttributeRequest.add_member(:enable_lni_at_device_index, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'EnableLniAtDeviceIndex', traits: {"smithy.api#documentation" => "<p>\n            Indicates the device position for local network interfaces in this subnet. For example, \n            <code>1</code> indicates local network interfaces in this subnet are the secondary \n            network interface (eth1). A local network interface cannot be the primary network\n            interface (eth0).\n        </p>"}))
