    ModifyVpcAttributeRequest.add_member(:enable_dns_hostnames, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'EnableDnsHostnames', traits: {"smithy.api#documentation" => "<p>Indicates whether the instances launched in the VPC get DNS hostnames. If enabled, instances in the VPC get DNS hostnames; otherwise, they do not.</p>\n         <p>You cannot modify the DNS resolution and DNS hostnames attributes in the same request. Use separate requests for each attribute. You can only enable DNS hostnames if you've enabled DNS support.</p>"}))
    ModifyVpcAttributeRequest.add_member(:enable_dns_support, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeBooleanValue, location_name: 'EnableDnsSupport', traits: {"smithy.api#documentation" => "<p>Indicates whether the DNS resolution is supported for the VPC. If enabled, queries to\n\t\t\tthe Amazon provided DNS server at the 169.254.169.253 IP address, or the reserved IP\n\t\t\taddress at the base of the VPC network range \"plus two\" succeed. If disabled, the Amazon\n\t\t\tprovided DNS service in the VPC that resolves public DNS hostnames to IP addresses is\n\t\t\tnot enabled.</p>\n         <p>You cannot modify the DNS resolution and DNS hostnames attributes in the same request. Use separate requests for each attribute.</p>"}))
