    ModifyVpcBlockPublicAccessExclusionResult.add_member(:vpc_block_public_access_exclusion, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcBlockPublicAccessExclusion, location_name: 'VpcBlockPublicAccessExclusion', traits: {"aws.protocols#ec2QueryName" => "VpcBlockPublicAccessExclusion", "smithy.api#documentation" => "<p>Details related to the exclusion.</p>", "smithy.api#xmlName" => "vpcBlockPublicAccessExclusion"}))
