    ModifyVpcBlockPublicAccessOptionsRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually making the request, \n   and provides an error response. If you have the required permissions, the error response is <code>DryRunOperation</code>. \n   Otherwise, it is <code>UnauthorizedOperation</code>.</p>"}))
    ModifyVpcBlockPublicAccessOptionsRequest.add_member(:internet_gateway_block_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: InternetGatewayBlockMode, location_name: 'InternetGatewayBlockMode', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The mode of VPC BPA.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>off</code>: VPC BPA is not enabled and traffic is allowed to and from internet gateways and egress-only internet gateways in this Region.</p>\n            </li>\n            <li>\n               <p>\n                  <code>block-bidirectional</code>: Block all traffic to and from internet gateways and egress-only internet gateways in this Region (except for excluded VPCs and subnets).</p>\n            </li>\n            <li>\n               <p>\n                  <code>block-ingress</code>: Block all internet traffic to the VPCs in this Region (except for VPCs or subnets which are excluded). Only traffic to and from NAT gateways and egress-only internet gateways is allowed because these gateways only allow outbound connections to be established.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ModifyVpcBlockPublicAccessOptionsRequest.type = Types::ModifyVpcBlockPublicAccessOptionsRequest
