    ModifyVpnTunnelOptionsRequest.add_member(:skip_tunnel_replacement, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SkipTunnelReplacement', traits: {"smithy.api#documentation" => "<p>Choose whether or not to trigger immediate tunnel replacement. This is only applicable when turning on or off <code>EnableTunnelLifecycleControl</code>.</p>\n         <p>Valid values: <code>True</code> | <code>False</code>\n         </p>"}))
    ModifyVpnTunnelOptionsRequest.add_member(:pre_shared_key_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreSharedKeyStorage', traits: {"smithy.api#documentation" => "<p>Specifies the storage mode for the pre-shared key (PSK). Valid values are <code>Standard</code> (stored in Site-to-Site VPN service) or <code>SecretsManager</code> (stored in Amazon Web Services Secrets Manager).</p>"}))
    ModifyVpnTunnelOptionsRequest.type = Types::ModifyVpnTunnelOptionsRequest
