    ModifyVpnTunnelOptionsResult.type = Types::ModifyVpnTunnelOptionsResult
    ModifyVpnTunnelOptionsSpecification.add_member(:tunnel_inside_cidr, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TunnelInsideCidr', traits: {"smithy.api#documentation" => "<p>The range of inside IPv4 addresses for the tunnel. Any specified CIDR blocks must be\n            unique across all VPN connections that use the same virtual private gateway. </p>\n         <p>Constraints: A size /30 CIDR block from the <code>169.254.0.0/16</code> range. The\n            following CIDR blocks are reserved and cannot be used:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>169.254.0.0/30</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>169.254.1.0/30</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>169.254.2.0/30</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>169.254.3.0/30</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>169.254.4.0/30</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>169.254.5.0/30</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>169.254.169.252/30</code>\n               </p>\n            </li>\n         </ul>"}))
    ModifyVpnTunnelOptionsSpecification.add_member(:tunnel_inside_ipv6_cidr, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TunnelInsideIpv6Cidr', traits: {"smithy.api#documentation" => "<p>The range of inside IPv6 addresses for the tunnel. Any specified CIDR blocks must be\n            unique across all VPN connections that use the same transit gateway.</p>\n         <p>Constraints: A size /126 CIDR block from the local <code>fd00::/8</code> range.</p>"}))
    ModifyVpnTunnelOptionsSpecification.add_member(:pre_shared_key, Smithy::Schema::Shapes::ShapeRef.new(shape: PreSharedKey, location_name: 'PreSharedKey', traits: {"smithy.api#documentation" => "<p>The pre-shared key (PSK) to establish initial authentication between the virtual\n            private gateway and the customer gateway.</p>\n         <p>Constraints: Allowed characters are alphanumeric characters, periods (.), and\n            underscores (_). Must be between 8 and 64 characters in length and cannot start with\n            zero (0).</p>"}))
    ModifyVpnTunnelOptionsSpecification.add_member(:phase1_lifetime_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Phase1LifetimeSeconds', traits: {"smithy.api#documentation" => "<p>The lifetime for phase 1 of the IKE negotiation, in seconds.</p>\n         <p>Constraints: A value between 900 and 28,800.</p>\n         <p>Default: <code>28800</code>\n         </p>"}))
    ModifyVpnTunnelOptionsSpecification.add_member(:phase2_lifetime_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Phase2LifetimeSeconds', traits: {"smithy.api#documentation" => "<p>The lifetime for phase 2 of the IKE negotiation, in seconds.</p>\n         <p>Constraints: A value between 900 and 3,600. The value must be less than the value for\n                <code>Phase1LifetimeSeconds</code>.</p>\n         <p>Default: <code>3600</code>\n         </p>"}))
    ModifyVpnTunnelOptionsSpecification.add_member(:rekey_margin_time_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'RekeyMarginTimeSeconds', traits: {"smithy.api#documentation" => "<p>The margin time, in seconds, before the phase 2 lifetime expires, during which the\n                Amazon Web Services side of the VPN connection performs an IKE rekey. The exact time\n            of the rekey is randomly selected based on the value for\n                <code>RekeyFuzzPercentage</code>.</p>\n         <p>Constraints: A value between 60 and half of <code>Phase2LifetimeSeconds</code>.</p>\n         <p>Default: <code>270</code>\n         </p>"}))
    ModifyVpnTunnelOptionsSpecification.add_member(:rekey_fuzz_percentage, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'RekeyFuzzPercentage', traits: {"smithy.api#documentation" => "<p>The percentage of the rekey window (determined by <code>RekeyMarginTimeSeconds</code>)\n            during which the rekey time is randomly selected.</p>\n         <p>Constraints: A value between 0 and 100.</p>\n         <p>Default: <code>100</code>\n         </p>"}))
    ModifyVpnTunnelOptionsSpecification.add_member(:replay_window_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ReplayWindowSize', traits: {"smithy.api#documentation" => "<p>The number of packets in an IKE replay window.</p>\n         <p>Constraints: A value between 64 and 2048.</p>\n         <p>Default: <code>1024</code>\n         </p>"}))
    ModifyVpnTunnelOptionsSpecification.add_member(:dpd_timeout_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'DPDTimeoutSeconds', traits: {"smithy.api#documentation" => "<p>The number of seconds after which a DPD timeout occurs. A DPD timeout of 40 seconds means that the VPN endpoint will consider the peer dead 30 seconds after the first failed keep-alive.</p>\n         <p>Constraints: A value greater than or equal to 30.</p>\n         <p>Default: <code>40</code>\n         </p>"}))
    ModifyVpnTunnelOptionsSpecification.add_member(:dpd_timeout_action, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DPDTimeoutAction', traits: {"smithy.api#documentation" => "<p>The action to take after DPD timeout occurs. Specify <code>restart</code> to restart\n            the IKE initiation. Specify <code>clear</code> to end the IKE session.</p>\n         <p>Valid Values: <code>clear</code> | <code>none</code> | <code>restart</code>\n         </p>\n         <p>Default: <code>clear</code>\n         </p>"}))
    ModifyVpnTunnelOptionsSpecification.add_member(:phase1_encryption_algorithms, Smithy::Schema::Shapes::ShapeRef.new(shape: Phase1EncryptionAlgorithmsRequestList, location_name: 'Phase1EncryptionAlgorithms', traits: {"smithy.api#documentation" => "<p>One or more encryption algorithms that are permitted for the VPN tunnel for phase 1\n            IKE negotiations.</p>\n         <p>Valid values: <code>AES128</code> | <code>AES256</code> | <code>AES128-GCM-16</code> |\n                <code>AES256-GCM-16</code>\n         </p>", "smithy.api#xmlName" => "Phase1EncryptionAlgorithm"}))
