    NatGateway.add_member(:provisioned_bandwidth, Smithy::Schema::Shapes::ShapeRef.new(shape: ProvisionedBandwidth, location_name: 'ProvisionedBandwidth', traits: {"aws.protocols#ec2QueryName" => "ProvisionedBandwidth", "smithy.api#documentation" => "<p>Reserved. If you need to sustain traffic greater than the <a href=\"https://docs.aws.amazon.com/vpc/latest/userguide/amazon-vpc-limits.html#vpc-limits-gateways\">documented limits</a>, \n          contact Amazon Web Services Support.</p>", "smithy.api#xmlName" => "provisionedBandwidth"}))
    NatGateway.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: NatGatewayState, location_name: 'State', traits: {"aws.protocols#ec2QueryName" => "State", "smithy.api#documentation" => "<p>The state of the NAT gateway.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>pending</code>: The NAT gateway is being created and is not ready to process\n          traffic.</p>\n            </li>\n            <li>\n               <p>\n                  <code>failed</code>: The NAT gateway could not be created. Check the\n            <code>failureCode</code> and <code>failureMessage</code> fields for the reason.</p>\n            </li>\n            <li>\n               <p>\n                  <code>available</code>: The NAT gateway is able to process traffic. This status remains\n          until you delete the NAT gateway, and does not indicate the health of the NAT gateway.</p>\n            </li>\n            <li>\n               <p>\n                  <code>deleting</code>: The NAT gateway is in the process of being terminated and may\n          still be processing traffic.</p>\n            </li>\n            <li>\n               <p>\n                  <code>deleted</code>: The NAT gateway has been terminated and is no longer processing\n          traffic.</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "state"}))
