    OnDemandOptions.add_member(:allocation_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetOnDemandAllocationStrategy, location_name: 'AllocationStrategy', traits: {"aws.protocols#ec2QueryName" => "AllocationStrategy", "smithy.api#documentation" => "<p>The strategy that determines the order of the launch template overrides to use in\n         fulfilling On-Demand capacity.</p>\n         <p>\n            <code>lowest-price</code> - EC2 Fleet uses price to determine the order, launching the lowest\n         price first.</p>\n         <p>\n            <code>prioritized</code> - EC2 Fleet uses the priority that you assigned to each launch\n         template override, launching the highest priority first.</p>\n         <p>Default: <code>lowest-price</code>\n         </p>", "smithy.api#xmlName" => "allocationStrategy"}))
