    OnDemandOptionsRequest.add_member(:single_instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SingleInstanceType', traits: {"smithy.api#documentation" => "<p>Indicates that the fleet uses a single instance type to launch all On-Demand Instances in the\n         fleet.</p>\n         <p>Supported only for fleets of type <code>instant</code>.</p>"}))
