    RegisterImageRequest.add_member(:billing_products, Smithy::Schema::Shapes::ShapeRef.new(shape: BillingProductList, location_name: 'BillingProducts', traits: {"smithy.api#documentation" => "<p>The billing product codes. Your account must be authorized to specify billing product\n      codes.</p>\n         <p>If your account is not authorized to specify billing product codes, you can publish AMIs\n      that include billable software and list them on the Amazon Web Services Marketplace. You must first register as a seller\n      on the Amazon Web Services Marketplace. For more information, see <a href=\"https://docs.aws.amazon.com/marketplace/latest/userguide/user-guide-for-sellers.html\">Getting started as an Amazon Web Services Marketplace seller</a> and <a href=\"https://docs.aws.amazon.com/marketplace/latest/userguide/ami-products.html\">AMI-based products in Amazon Web Services Marketplace</a> in the <i>Amazon Web Services Marketplace Seller Guide</i>.</p>", "smithy.api#xmlName" => "BillingProduct"}))
    RegisterImageRequest.add_member(:boot_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: BootModeValues, location_name: 'BootMode', traits: {"smithy.api#documentation" => "<p>The boot mode of the AMI. A value of <code>uefi-preferred</code> indicates that the AMI\n      supports both UEFI and Legacy BIOS.</p>\n         <note>\n            <p>The operating system contained in the AMI must be configured to support the specified\n        boot mode.</p>\n         </note>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ami-boot.html\">Instance launch behavior with Amazon EC2\n        boot modes</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    RegisterImageRequest.add_member(:tpm_support, Smithy::Schema::Shapes::ShapeRef.new(shape: TpmSupportValues, location_name: 'TpmSupport', traits: {"smithy.api#documentation" => "<p>Set to <code>v2.0</code> to enable Trusted Platform Module (TPM) support. For more\n      information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/nitrotpm.html\">NitroTPM</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    RegisterImageRequest.add_member(:uefi_data, Smithy::Schema::Shapes::ShapeRef.new(shape: StringType, location_name: 'UefiData', traits: {"smithy.api#documentation" => "<p>Base64 representation of the non-volatile UEFI variable store. To retrieve the UEFI data,\n      use the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_GetInstanceUefiData\">GetInstanceUefiData</a> command. You can inspect and modify the UEFI data by using the\n        <a href=\"https://github.com/awslabs/python-uefivars\">python-uefivars tool</a> on\n      GitHub. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/uefi-secure-boot.html\">UEFI Secure Boot for Amazon EC2\n        instances</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    RegisterImageRequest.add_member(:imds_support, Smithy::Schema::Shapes::ShapeRef.new(shape: ImdsSupportValues, location_name: 'ImdsSupport', traits: {"smithy.api#documentation" => "<p>Set to <code>v2.0</code> to indicate that IMDSv2 is specified in the AMI. Instances\n      launched from this AMI will have <code>HttpTokens</code> automatically set to\n        <code>required</code> so that, by default, the instance requires that IMDSv2 is used when\n      requesting instance metadata. In addition, <code>HttpPutResponseHopLimit</code> is set to\n        <code>2</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/configuring-IMDS-new-instances.html#configure-IMDS-new-instances-ami-configuration\">Configure the AMI</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <note>\n            <p>If you set the value to <code>v2.0</code>, make sure that your AMI software can support\n        IMDSv2.</p>\n         </note>"}))
    RegisterImageRequest.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: TagSpecificationList, location_name: 'TagSpecifications', traits: {"smithy.api#documentation" => "<p>The tags to apply to the AMI.</p>\n         <p>To tag the AMI, the value for <code>ResourceType</code> must be <code>image</code>. If you\n      specify another value for <code>ResourceType</code>, the request fails.</p>\n         <p>To tag an AMI after it has been registered, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateTags.html\">CreateTags</a>.</p>", "smithy.api#xmlName" => "TagSpecification"}))
    RegisterImageRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"aws.protocols#ec2QueryName" => "DryRun", "smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually making the request, \n\t\t\tand provides an error response. If you have the required permissions, the error response is \n\t\t\t<code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.</p>", "smithy.api#xmlName" => "dryRun"}))
    RegisterImageRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Name', traits: {"aws.protocols#ec2QueryName" => "Name", "smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A name for your AMI.</p>\n         <p>Constraints: 3-128 alphanumeric characters, parentheses (()), square brackets ([]), spaces\n      ( ), periods (.), slashes (/), dashes (-), single quotes ('), at-signs (@), or\n      underscores(_)</p>", "smithy.api#required" => {}, "smithy.api#xmlName" => "name"}))
