    RegisterImageRequest.add_member(:architecture, Smithy::Schema::Shapes::ShapeRef.new(shape: ArchitectureValues, location_name: 'Architecture', traits: {"aws.protocols#ec2QueryName" => "Architecture", "smithy.api#documentation" => "<p>The architecture of the AMI.</p>\n         <p>Default: For Amazon EBS-backed AMIs, <code>i386</code>. For instance store-backed AMIs, the\n      architecture specified in the manifest file.</p>", "smithy.api#xmlName" => "architecture"}))
