    RegisterImageRequest.add_member(:sriov_net_support, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SriovNetSupport', traits: {"aws.protocols#ec2QueryName" => "SriovNetSupport", "smithy.api#documentation" => "<p>Set to <code>simple</code> to enable enhanced networking with the Intel 82599 Virtual\n      Function interface for the AMI and any instances that you launch from the AMI.</p>\n         <p>There is no way to disable <code>sriovNetSupport</code> at this time.</p>\n         <p>This option is supported only for HVM AMIs. Specifying this option with a PV AMI can make\n      instances launched from the AMI unreachable.</p>", "smithy.api#xmlName" => "sriovNetSupport"}))
    RegisterImageRequest.add_member(:ena_support, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnaSupport', traits: {"aws.protocols#ec2QueryName" => "EnaSupport", "smithy.api#documentation" => "<p>Set to <code>true</code> to enable enhanced networking with ENA for the AMI and any\n      instances that you launch from the AMI.</p>\n         <p>This option is supported only for HVM AMIs. Specifying this option with a PV AMI can make\n      instances launched from the AMI unreachable.</p>", "smithy.api#xmlName" => "enaSupport"}))
