    ReplaceNetworkAclEntryRequest.add_member(:protocol, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Protocol', traits: {"aws.protocols#ec2QueryName" => "Protocol", "smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The protocol number. A value of \"-1\" means all protocols. If you specify \"-1\" or a\n           protocol number other than \"6\" (TCP), \"17\" (UDP), or \"1\" (ICMP), traffic on all ports is \n           allowed, regardless of any ports or ICMP types or codes that you specify. If you specify \n           protocol \"58\" (ICMPv6) and specify an IPv4 CIDR block, traffic for all ICMP types and \n           codes allowed, regardless of any that you specify. If you specify protocol \"58\" (ICMPv6) \n           and specify an IPv6 CIDR block, you must specify an ICMP type and code.</p>", "smithy.api#required" => {}, "smithy.api#xmlName" => "protocol"}))
    ReplaceNetworkAclEntryRequest.add_member(:rule_action, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleAction, location_name: 'RuleAction', traits: {"aws.protocols#ec2QueryName" => "RuleAction", "smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Indicates whether to allow or deny the traffic that matches the rule.</p>", "smithy.api#required" => {}, "smithy.api#xmlName" => "ruleAction"}))
