    RequestLaunchTemplateData.add_member(:ram_disk_id, Smithy::Schema::Shapes::ShapeRef.new(shape: RamdiskId, location_name: 'RamDiskId', traits: {"smithy.api#documentation" => "<p>The ID of the RAM disk.</p>\n         <important>\n            <p>We recommend that you use PV-GRUB instead of kernels and RAM disks. For more\n                information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/UserProvidedkernels.html\">User provided\n                    kernels</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         </important>"}))
    RequestLaunchTemplateData.add_member(:disable_api_termination, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DisableApiTermination', traits: {"smithy.api#documentation" => "<p>Indicates whether termination protection is enabled for the instance. The default is\n                <code>false</code>, which means that you can terminate the instance using the Amazon EC2\n            console, command line tools, or API. You can enable termination protection when you\n            launch an instance, while the instance is running, or while the instance is\n            stopped.</p>"}))
    RequestLaunchTemplateData.add_member(:instance_initiated_shutdown_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: ShutdownBehavior, location_name: 'InstanceInitiatedShutdownBehavior', traits: {"smithy.api#documentation" => "<p>Indicates whether an instance stops or terminates when you initiate shutdown from the\n            instance (using the operating system command for system shutdown).</p>\n         <p>Default: <code>stop</code>\n         </p>"}))
    RequestLaunchTemplateData.add_member(:user_data, Smithy::Schema::Shapes::ShapeRef.new(shape: SensitiveUserData, location_name: 'UserData', traits: {"smithy.api#documentation" => "<p>The user data to make available to the instance. You must provide base64-encoded text.\n            User data is limited to 16 KB. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/user-data.html\">Run commands when you launch an EC2\n                instance with user data input</a> in the\n            <i>Amazon EC2 User Guide</i>.</p>\n         <p>If you are creating the launch template for use with Batch, the user\n            data must be provided in the <a href=\"https://cloudinit.readthedocs.io/en/latest/topics/format.html#mime-multi-part-archive\">MIME multi-part archive format</a>. For more information, see <a href=\"https://docs.aws.amazon.com/batch/latest/userguide/launch-templates.html#lt-user-data\">Amazon EC2 user data in launch templates</a> in the\n                    <i>Batch User Guide</i>.</p>"}))
    RequestLaunchTemplateData.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateTagSpecificationRequestList, location_name: 'TagSpecifications', traits: {"smithy.api#documentation" => "<p>The tags to apply to the resources that are created during instance launch. These tags\n            are not applied to the launch template.</p>", "smithy.api#xmlName" => "TagSpecification"}))
    RequestLaunchTemplateData.add_member(:elastic_gpu_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticGpuSpecificationList, location_name: 'ElasticGpuSpecifications', traits: {"smithy.api#deprecated" => {"since" => "2024-01-08", "message" => "Specifying Elastic Graphics accelerators is no longer supported on the RunInstances API."}, "smithy.api#documentation" => "<p>Deprecated.</p>\n         <note>\n            <p>Amazon Elastic Graphics reached end of life on January 8, 2024.</p>\n         </note>", "smithy.api#xmlName" => "ElasticGpuSpecification"}))
    RequestLaunchTemplateData.add_member(:elastic_inference_accelerators, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateElasticInferenceAcceleratorList, location_name: 'ElasticInferenceAccelerators', traits: {"smithy.api#deprecated" => {"since" => "2024-01-08", "message" => "Specifying Elastic Inference accelerators is no longer supported on the RunInstances API."}, "smithy.api#documentation" => "<note>\n            <p>Amazon Elastic Inference is no longer available.</p>\n         </note>\n         <p>An elastic inference accelerator to associate with the instance. Elastic inference\n            accelerators are a resource you can attach to your Amazon EC2 instances to accelerate\n            your Deep Learning (DL) inference workloads.</p>\n         <p>You cannot specify accelerators from different generations in the same request.</p>", "smithy.api#xmlName" => "ElasticInferenceAccelerator"}))
    RequestLaunchTemplateData.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIdStringList, location_name: 'SecurityGroupIds', traits: {"smithy.api#documentation" => "<p>The IDs of the security groups.</p>\n         <p>If you specify a network interface, you must specify any security groups as part of\n            the network interface instead of using this parameter.</p>", "smithy.api#xmlName" => "SecurityGroupId"}))
    RequestLaunchTemplateData.add_member(:security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupStringList, location_name: 'SecurityGroups', traits: {"smithy.api#documentation" => "<p>The names of the security groups. For a nondefault VPC, you must use security group\n            IDs instead.</p>\n         <p>If you specify a network interface, you must specify any security groups as part of\n            the network interface instead of using this parameter.</p>", "smithy.api#xmlName" => "SecurityGroup"}))
    RequestLaunchTemplateData.add_member(:instance_market_options, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateInstanceMarketOptionsRequest, location_name: 'InstanceMarketOptions', traits: {"smithy.api#documentation" => "<p>The market (purchasing) option for the instances.</p>"}))
    RequestLaunchTemplateData.add_member(:credit_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: CreditSpecificationRequest, location_name: 'CreditSpecification', traits: {"smithy.api#documentation" => "<p>The credit option for CPU usage of the instance. Valid only for T instances.</p>"}))
    RequestLaunchTemplateData.add_member(:cpu_options, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateCpuOptionsRequest, location_name: 'CpuOptions', traits: {"smithy.api#documentation" => "<p>The CPU options for the instance. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-optimize-cpu.html\">CPU\n                options for Amazon EC2 instances</a> in the\n            <i>Amazon EC2 User Guide</i>.</p>"}))
    RequestLaunchTemplateData.add_member(:capacity_reservation_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateCapacityReservationSpecificationRequest, location_name: 'CapacityReservationSpecification', traits: {"smithy.api#documentation" => "<p>The Capacity Reservation targeting option. If you do not specify this parameter, the\n            instance's Capacity Reservation preference defaults to <code>open</code>, which enables\n            it to run in any open Capacity Reservation that has matching attributes (instance type,\n            platform, Availability Zone).</p>"}))
    RequestLaunchTemplateData.add_member(:license_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateLicenseSpecificationListRequest, location_name: 'LicenseSpecifications', traits: {"smithy.api#documentation" => "<p>The license configurations.</p>", "smithy.api#xmlName" => "LicenseSpecification"}))
    RequestLaunchTemplateData.add_member(:hibernation_options, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateHibernationOptionsRequest, location_name: 'HibernationOptions', traits: {"smithy.api#documentation" => "<p>Indicates whether an instance is enabled for hibernation. This parameter is valid only\n            if the instance meets the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/hibernating-prerequisites.html\">hibernation\n                prerequisites</a>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/Hibernate.html\">Hibernate your Amazon EC2 instance</a>\n            in the <i>Amazon EC2 User Guide</i>.</p>"}))
    RequestLaunchTemplateData.add_member(:metadata_options, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateInstanceMetadataOptionsRequest, location_name: 'MetadataOptions', traits: {"smithy.api#documentation" => "<p>The metadata options for the instance. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/configuring-instance-metadata-options.html\">Configure\n                the Instance Metadata Service options</a> in the\n                <i>Amazon EC2 User Guide</i>.</p>"}))
    RequestLaunchTemplateData.add_member(:enclave_options, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateEnclaveOptionsRequest, location_name: 'EnclaveOptions', traits: {"smithy.api#documentation" => "<p>Indicates whether the instance is enabled for Amazon Web Services Nitro Enclaves. For more\n            information, see <a href=\"https://docs.aws.amazon.com/enclaves/latest/user/nitro-enclave.html\">What is Nitro Enclaves?</a> in the\n                <i>Amazon Web Services Nitro Enclaves User Guide</i>.</p>\n         <p>You can't enable Amazon Web Services Nitro Enclaves and hibernation on the same instance.</p>"}))
    RequestLaunchTemplateData.add_member(:instance_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRequirementsRequest, location_name: 'InstanceRequirements', traits: {"smithy.api#documentation" => "<p>The attributes for the instance types. When you specify instance attributes, Amazon EC2 will\n         identify instance types with these attributes.</p>\n         <p>You must specify <code>VCpuCount</code> and <code>MemoryMiB</code>. All other attributes\n         are optional. Any unspecified optional attribute is set to its default.</p>\n         <p>When you specify multiple attributes, you get instance types that satisfy all of the\n         specified attributes. If you specify multiple values for an attribute, you get instance\n         types that satisfy any of the specified values.</p>\n         <p>To limit the list of instance types from which Amazon EC2 can identify matching instance types, \n         you can use one of the following parameters, but not both in the same request:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>AllowedInstanceTypes</code> - The instance types to include in the list. All \n               other instance types are ignored, even if they match your specified attributes.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ExcludedInstanceTypes</code> - The instance types to exclude from the list, \n               even if they match your specified attributes.</p>\n            </li>\n         </ul>\n         <note>\n            <p>If you specify <code>InstanceRequirements</code>, you can't specify\n            <code>InstanceType</code>.</p>\n            <p>Attribute-based instance type selection is only supported when using Auto Scaling\n            groups, EC2 Fleet, and Spot Fleet to launch instances. If you plan to use the launch template in\n            the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-launch-instance-wizard.html\">launch instance\n               wizard</a>, or with the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_RunInstances.html\">RunInstances</a> API or\n              <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/aws-properties-ec2-instance.html\">AWS::EC2::Instance</a> Amazon Web Services CloudFormation resource, you can't specify <code>InstanceRequirements</code>.</p>\n         </note>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-fleet-attribute-based-instance-type-selection.html\">Specify attributes for instance type selection for EC2 Fleet or Spot Fleet</a> and <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/spot-placement-score.html\">Spot\n            placement score</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    RequestLaunchTemplateData.add_member(:private_dns_name_options, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplatePrivateDnsNameOptionsRequest, location_name: 'PrivateDnsNameOptions', traits: {"smithy.api#documentation" => "<p>The options for the instance hostname. The default values are inherited from the\n            subnet.</p>"}))
    RequestLaunchTemplateData.add_member(:maintenance_options, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateInstanceMaintenanceOptionsRequest, location_name: 'MaintenanceOptions', traits: {"smithy.api#documentation" => "<p>The maintenance options for the instance.</p>"}))
    RequestLaunchTemplateData.add_member(:disable_api_stop, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DisableApiStop', traits: {"smithy.api#documentation" => "<p>Indicates whether to enable the instance for stop protection. For more information,\n            see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-stop-protection.html\">Enable stop protection for your EC2 instances</a> in the\n                <i>Amazon EC2 User Guide</i>.</p>"}))
