    RequestLaunchTemplateData.add_member(:network_performance_options, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateNetworkPerformanceOptionsRequest, location_name: 'NetworkPerformanceOptions', traits: {"smithy.api#documentation" => "<p>Contains launch template settings to boost network performance for the type of\n            workload that runs on your instance.</p>"}))
    RequestLaunchTemplateData.type = Types::RequestLaunchTemplateData
    RequestSpotFleetRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"aws.protocols#ec2QueryName" => "DryRun", "smithy.api#documentation" => "<p>Checks whether you have the required permissions for the action, without actually\n            making the request, and provides an error response. If you have the required\n            permissions, the error response is <code>DryRunOperation</code>. Otherwise, it is\n                <code>UnauthorizedOperation</code>.</p>", "smithy.api#xmlName" => "dryRun"}))
    RequestSpotFleetRequest.add_member(:spot_fleet_request_config, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotFleetRequestConfigData, location_name: 'SpotFleetRequestConfig', traits: {"aws.protocols#ec2QueryName" => "SpotFleetRequestConfig", "smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The configuration for the Spot Fleet request.</p>", "smithy.api#required" => {}, "smithy.api#xmlName" => "spotFleetRequestConfig"}))
