    RouteServerBgpOptions.add_member(:peer_asn, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'PeerAsn', traits: {"aws.protocols#ec2QueryName" => "PeerAsn", "smithy.api#documentation" => "<p>The Border Gateway Protocol (BGP) Autonomous System Number (ASN) for the appliance. Valid values are from 1 to 4294967295. We recommend using a private ASN in the 64512–65534 (16-bit ASN) or 4200000000–4294967294 (32-bit ASN) range.</p>", "smithy.api#xmlName" => "peerAsn"}))
    RouteServerBgpOptions.add_member(:peer_liveness_detection, Smithy::Schema::Shapes::ShapeRef.new(shape: RouteServerPeerLivenessMode, location_name: 'PeerLivenessDetection', traits: {"aws.protocols#ec2QueryName" => "PeerLivenessDetection", "smithy.api#documentation" => "<p>The liveness detection protocol used for the BGP peer.</p>\n         <p>The requested liveness detection protocol for the BGP peer.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>bgp-keepalive</code>: The standard BGP keep alive mechanism (<a href=\"https://www.rfc-editor.org/rfc/rfc4271#page-21\">RFC4271</a>) that is stable but may take longer to fail-over in cases of network impact or router failure.</p>\n            </li>\n            <li>\n               <p>\n                  <code>bfd</code>: An additional Bidirectional Forwarding Detection (BFD) protocol (<a href=\"https://www.rfc-editor.org/rfc/rfc5880\">RFC5880</a>) that enables fast failover by using more sensitive liveness detection.</p>\n            </li>\n         </ul>\n         <p>Defaults to <code>bgp-keepalive</code>.</p>", "smithy.api#xmlName" => "peerLivenessDetection"}))
    RouteServerBgpOptions.type = Types::RouteServerBgpOptions
    RouteServerBgpOptionsRequest.add_member(:peer_asn, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'PeerAsn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Border Gateway Protocol (BGP) Autonomous System Number (ASN) for the appliance. Valid values are from 1 to 4294967295. We recommend using a private ASN in the 64512–65534 (16-bit ASN) or 4200000000–4294967294 (32-bit ASN) range.</p>", "smithy.api#required" => {}}))
    RouteServerBgpOptionsRequest.add_member(:peer_liveness_detection, Smithy::Schema::Shapes::ShapeRef.new(shape: RouteServerPeerLivenessMode, location_name: 'PeerLivenessDetection', traits: {"smithy.api#documentation" => "<p>The requested liveness detection protocol for the BGP peer.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>bgp-keepalive</code>: The standard BGP keep alive mechanism (<a href=\"https://www.rfc-editor.org/rfc/rfc4271#page-21\">RFC4271</a>) that is stable but may take longer to fail-over in cases of network impact or router failure.</p>\n            </li>\n            <li>\n               <p>\n                  <code>bfd</code>: An additional Bidirectional Forwarding Detection (BFD) protocol (<a href=\"https://www.rfc-editor.org/rfc/rfc5880\">RFC5880</a>) that enables fast failover by using more sensitive liveness detection.</p>\n            </li>\n         </ul>\n         <p>Defaults to <code>bgp-keepalive</code>.</p>"}))
