    RunInstancesRequest.add_member(:block_device_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceMappingRequestList, location_name: 'BlockDeviceMappings', traits: {"smithy.api#documentation" => "<p>The block device mapping, which defines the EBS volumes and instance store volumes to\n            attach to the instance at launch. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/block-device-mapping-concepts.html\">Block device\n                mappings</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "BlockDeviceMapping"}))
