    RunInstancesRequest.add_member(:ipv6_address_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Ipv6AddressCount', traits: {"smithy.api#documentation" => "<p>The number of IPv6 addresses to associate with the primary network\n            interface. Amazon EC2 chooses the IPv6 addresses from the range of your subnet. You\n            cannot specify this option and the option to assign specific IPv6 addresses in the same\n            request. You can specify this option if you've specified a minimum number of instances\n            to launch.</p>\n         <p>You cannot specify this option and the network interfaces option in the same\n            request.</p>"}))
    RunInstancesRequest.add_member(:ipv6_addresses, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceIpv6AddressList, location_name: 'Ipv6Addresses', traits: {"smithy.api#documentation" => "<p>The IPv6 addresses from the range of the subnet to associate with the\n            primary network interface. You cannot specify this option and the option to assign a\n            number of IPv6 addresses in the same request. You cannot specify this option if you've\n            specified a minimum number of instances to launch.</p>\n         <p>You cannot specify this option and the network interfaces option in the same\n            request.</p>", "smithy.api#xmlName" => "Ipv6Address"}))
    RunInstancesRequest.add_member(:kernel_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KernelId, location_name: 'KernelId', traits: {"smithy.api#documentation" => "<p>The ID of the kernel.</p>\n         <important>\n            <p>We recommend that you use PV-GRUB instead of kernels and RAM disks. For more\n                information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/UserProvidedkernels.html\">PV-GRUB</a> in the\n                    <i>Amazon EC2 User Guide</i>.</p>\n         </important>"}))
    RunInstancesRequest.add_member(:key_name, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyPairName, location_name: 'KeyName', traits: {"smithy.api#documentation" => "<p>The name of the key pair. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/create-key-pairs.html\">Create a key pair for your EC2 instance</a>.</p>\n         <important>\n            <p>If you do not specify a key pair, you can't connect to the instance unless you\n                choose an AMI that is configured to allow users another way to log in.</p>\n         </important>"}))
    RunInstancesRequest.add_member(:max_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'MaxCount', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum number of instances to launch. If you specify a value that is more\n            capacity than Amazon EC2 can launch in the target Availability Zone, Amazon EC2 \n            launches the largest possible number of instances above the specified minimum\n            count.</p>\n         <p>Constraints: Between 1 and the quota for the specified instance type for your account for this Region. \n            For more information, see <a href=\"https://docs.aws.amazon.com/ec2/latest/instancetypes/ec2-instance-quotas.html\">Amazon EC2 instance type quotas</a>.</p>", "smithy.api#required" => {}}))
    RunInstancesRequest.add_member(:min_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'MinCount', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The minimum number of instances to launch. If you specify a value that is more\n            capacity than Amazon EC2 can provide in the target Availability Zone, Amazon EC2 does\n            not launch any instances.</p>\n         <p>Constraints: Between 1 and the quota for the specified instance type for your account for this Region.\n            For more information, see <a href=\"https://docs.aws.amazon.com/ec2/latest/instancetypes/ec2-instance-quotas.html\">Amazon EC2 instance type quotas</a>.</p>", "smithy.api#required" => {}}))
    RunInstancesRequest.add_member(:monitoring, Smithy::Schema::Shapes::ShapeRef.new(shape: RunInstancesMonitoringEnabled, location_name: 'Monitoring', traits: {"smithy.api#documentation" => "<p>Specifies whether detailed monitoring is enabled for the instance.</p>"}))
    RunInstancesRequest.add_member(:placement, Smithy::Schema::Shapes::ShapeRef.new(shape: Placement, location_name: 'Placement', traits: {"smithy.api#documentation" => "<p>The placement for the instance.</p>"}))
    RunInstancesRequest.add_member(:ramdisk_id, Smithy::Schema::Shapes::ShapeRef.new(shape: RamdiskId, location_name: 'RamdiskId', traits: {"smithy.api#documentation" => "<p>The ID of the RAM disk to select. Some kernels require additional drivers at launch.\n            Check the kernel requirements for information about whether you need to specify a RAM\n            disk. To find kernel requirements, go to the Amazon Web Services Resource Center and\n            search for the kernel ID.</p>\n         <important>\n            <p>We recommend that you use PV-GRUB instead of kernels and RAM disks. For more\n                information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/UserProvidedkernels.html\">PV-GRUB</a> in the\n                    <i>Amazon EC2 User Guide</i>.</p>\n         </important>"}))
    RunInstancesRequest.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupIdStringList, location_name: 'SecurityGroupIds', traits: {"smithy.api#documentation" => "<p>The IDs of the security groups.</p>\n         <p>If you specify a network interface, you must specify any security groups as part of\n            the network interface instead of using this parameter.</p>", "smithy.api#xmlName" => "SecurityGroupId"}))
    RunInstancesRequest.add_member(:security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroupStringList, location_name: 'SecurityGroups', traits: {"smithy.api#documentation" => "<p>[Default VPC] The names of the security groups.</p>\n         <p>If you specify a network interface, you must specify any security groups as part of\n            the network interface instead of using this parameter.</p>\n         <p>Default: Amazon EC2 uses the default security group.</p>", "smithy.api#xmlName" => "SecurityGroup"}))
    RunInstancesRequest.add_member(:subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetId, location_name: 'SubnetId', traits: {"smithy.api#documentation" => "<p>The ID of the subnet to launch the instance into.</p>\n         <p>If you specify a network interface, you must specify any subnets as part of the\n            network interface instead of using this parameter.</p>"}))
    RunInstancesRequest.add_member(:user_data, Smithy::Schema::Shapes::ShapeRef.new(shape: RunInstancesUserData, location_name: 'UserData', traits: {"smithy.api#documentation" => "<p>The user data to make available to the instance. User data must be base64-encoded.\n            Depending on the tool or SDK that you're using, the base64-encoding might be performed for you.\n            For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/user-data.html\">Run commands at launch using instance user data</a>.</p>"}))
    RunInstancesRequest.add_member(:elastic_gpu_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: ElasticGpuSpecifications, location_name: 'ElasticGpuSpecification', traits: {"smithy.api#deprecated" => {"since" => "2024-01-08", "message" => "Specifying Elastic Graphics accelerators is no longer supported on the RunInstances API."}, "smithy.api#documentation" => "<p>An elastic GPU to associate with the instance.</p>\n         <note>\n            <p>Amazon Elastic Graphics reached end of life on January 8, 2024.</p>\n         </note>"}))
