    RunInstancesRequest.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: TagSpecificationList, location_name: 'TagSpecifications', traits: {"smithy.api#documentation" => "<p>The tags to apply to the resources that are created during instance launch.</p>\n         <p>You can specify tags for the following resources only:</p>\n         <ul>\n            <li>\n               <p>Instances</p>\n            </li>\n            <li>\n               <p>Volumes</p>\n            </li>\n            <li>\n               <p>Spot Instance requests</p>\n            </li>\n            <li>\n               <p>Network interfaces</p>\n            </li>\n         </ul>\n         <p>To tag a resource after it has been created, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateTags.html\">CreateTags</a>.</p>", "smithy.api#xmlName" => "TagSpecification"}))
    RunInstancesRequest.add_member(:launch_template, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateSpecification, location_name: 'LaunchTemplate', traits: {"smithy.api#documentation" => "<p>The launch template. Any additional parameters that you specify for the new instance \n            overwrite the corresponding parameters included in the launch template.</p>"}))
    RunInstancesRequest.add_member(:instance_market_options, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMarketOptionsRequest, location_name: 'InstanceMarketOptions', traits: {"smithy.api#documentation" => "<p>The market (purchasing) option for the instances.</p>\n         <p>For <a>RunInstances</a>, persistent Spot Instance requests are\n            only supported when <b>InstanceInterruptionBehavior</b> is set\n            to either <code>hibernate</code> or <code>stop</code>.</p>"}))
    RunInstancesRequest.add_member(:credit_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: CreditSpecificationRequest, location_name: 'CreditSpecification', traits: {"smithy.api#documentation" => "<p>The credit option for CPU usage of the burstable performance instance. Valid values\n            are <code>standard</code> and <code>unlimited</code>. To change this attribute after\n            launch, use <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_ModifyInstanceCreditSpecification.html\">\n                ModifyInstanceCreditSpecification</a>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/burstable-performance-instances.html\">Burstable\n                performance instances</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <p>Default: <code>standard</code> (T2 instances) or <code>unlimited</code> (T3/T3a/T4g\n            instances)</p>\n         <p>For T3 instances with <code>host</code> tenancy, only <code>standard</code> is\n            supported.</p>"}))
    RunInstancesRequest.add_member(:cpu_options, Smithy::Schema::Shapes::ShapeRef.new(shape: CpuOptionsRequest, location_name: 'CpuOptions', traits: {"smithy.api#documentation" => "<p>The CPU options for the instance. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-optimize-cpu.html\">Optimize CPU options</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    RunInstancesRequest.add_member(:capacity_reservation_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationSpecification, location_name: 'CapacityReservationSpecification', traits: {"smithy.api#documentation" => "<p>Information about the Capacity Reservation targeting option. If you do not specify this parameter, the\n            instance's Capacity Reservation preference defaults to <code>open</code>, which enables\n            it to run in any open Capacity Reservation that has matching attributes (instance type,\n            platform, Availability Zone, and tenancy).</p>"}))
    RunInstancesRequest.add_member(:hibernation_options, Smithy::Schema::Shapes::ShapeRef.new(shape: HibernationOptionsRequest, location_name: 'HibernationOptions', traits: {"smithy.api#documentation" => "<p>Indicates whether an instance is enabled for hibernation. This parameter is valid only\n            if the instance meets the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/hibernating-prerequisites.html\">hibernation\n                prerequisites</a>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/Hibernate.html\">Hibernate your Amazon EC2\n                instance</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <p>You can't enable hibernation and Amazon Web Services Nitro Enclaves on the same\n            instance.</p>"}))
    RunInstancesRequest.add_member(:license_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: LicenseSpecificationListRequest, location_name: 'LicenseSpecifications', traits: {"smithy.api#documentation" => "<p>The license configurations.</p>", "smithy.api#xmlName" => "LicenseSpecification"}))
    RunInstancesRequest.add_member(:metadata_options, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMetadataOptionsRequest, location_name: 'MetadataOptions', traits: {"smithy.api#documentation" => "<p>The metadata options for the instance. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/configuring-instance-metadata-options.html\">Configure the Instance Metadata Service options</a>.</p>"}))
    RunInstancesRequest.add_member(:enclave_options, Smithy::Schema::Shapes::ShapeRef.new(shape: EnclaveOptionsRequest, location_name: 'EnclaveOptions', traits: {"smithy.api#documentation" => "<p>Indicates whether the instance is enabled for Amazon Web Services Nitro Enclaves. For\n            more information, see <a href=\"https://docs.aws.amazon.com/enclaves/latest/user/\">Amazon Web Services Nitro\n                Enclaves User Guide</a>.</p>\n         <p>You can't enable Amazon Web Services Nitro Enclaves and hibernation on the same\n            instance.</p>"}))
    RunInstancesRequest.add_member(:private_dns_name_options, Smithy::Schema::Shapes::ShapeRef.new(shape: PrivateDnsNameOptionsRequest, location_name: 'PrivateDnsNameOptions', traits: {"smithy.api#documentation" => "<p>The options for the instance hostname. \n            The default values are inherited from the subnet.\n            Applies only if creating a network interface, not attaching an existing one.</p>"}))
    RunInstancesRequest.add_member(:maintenance_options, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMaintenanceOptionsRequest, location_name: 'MaintenanceOptions', traits: {"smithy.api#documentation" => "<p>The maintenance and recovery options for the instance.</p>"}))
    RunInstancesRequest.add_member(:disable_api_stop, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DisableApiStop', traits: {"smithy.api#documentation" => "<p>Indicates whether an instance is enabled for stop protection. For more information,\n            see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-stop-protection.html\">Enable stop protection for your EC2 instances</a>.</p>"}))
    RunInstancesRequest.add_member(:enable_primary_ipv6, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnablePrimaryIpv6', traits: {"smithy.api#documentation" => "<p>If you’re launching an instance into a dual-stack or IPv6-only subnet, you can enable\n            assigning a primary IPv6 address. A primary IPv6 address is an IPv6 GUA address\n            associated with an ENI that you have enabled to use a primary IPv6 address. Use this\n            option if an instance relies on its IPv6 address not changing. When you launch the\n            instance, Amazon Web Services will automatically assign an IPv6 address associated with\n            the ENI attached to your instance to be the primary IPv6 address. Once you enable an\n            IPv6 GUA address to be a primary IPv6, you cannot disable it. When you enable an IPv6\n            GUA address to be a primary IPv6, the first IPv6 GUA will be made the primary IPv6\n            address until the instance is terminated or the network interface is detached. If you\n            have multiple IPv6 addresses associated with an ENI attached to your instance and you\n            enable a primary IPv6 address, the first IPv6 GUA address associated with the ENI\n            becomes the primary IPv6 address.</p>"}))
    RunInstancesRequest.add_member(:network_performance_options, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceNetworkPerformanceOptionsRequest, location_name: 'NetworkPerformanceOptions', traits: {"smithy.api#documentation" => "<p>Contains settings for the network performance options for the instance.</p>"}))
    RunInstancesRequest.add_member(:operator, Smithy::Schema::Shapes::ShapeRef.new(shape: OperatorRequest, location_name: 'Operator', traits: {"smithy.api#documentation" => "<p>Reserved for internal use.</p>"}))
    RunInstancesRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"aws.protocols#ec2QueryName" => "DryRun", "smithy.api#documentation" => "<p>Checks whether you have the required permissions for the operation, without actually making the \n  request, and provides an error response. If you have the required permissions, the error response is \n  <code>DryRunOperation</code>. Otherwise, it is <code>UnauthorizedOperation</code>.</p>", "smithy.api#xmlName" => "dryRun"}))
    RunInstancesRequest.add_member(:disable_api_termination, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DisableApiTermination', traits: {"aws.protocols#ec2QueryName" => "DisableApiTermination", "smithy.api#documentation" => "<p>Indicates whether termination protection is enabled for the instance. The default\n            is <code>false</code>, which means that you can terminate the instance using\n            the Amazon EC2 console, command line tools, or API. You can enable termination protection\n            when you launch an instance, while the instance is running, or while the instance\n            is stopped.</p>", "smithy.api#xmlName" => "disableApiTermination"}))
    RunInstancesRequest.add_member(:instance_initiated_shutdown_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: ShutdownBehavior, location_name: 'InstanceInitiatedShutdownBehavior', traits: {"aws.protocols#ec2QueryName" => "InstanceInitiatedShutdownBehavior", "smithy.api#documentation" => "<p>Indicates whether an instance stops or terminates when you initiate shutdown from the\n            instance (using the operating system command for system shutdown).</p>\n         <p>Default: <code>stop</code>\n         </p>", "smithy.api#xmlName" => "instanceInitiatedShutdownBehavior"}))
    RunInstancesRequest.add_member(:private_ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PrivateIpAddress', traits: {"aws.protocols#ec2QueryName" => "PrivateIpAddress", "smithy.api#documentation" => "<p>The primary IPv4 address. You must specify a value from the IPv4 address\n            range of the subnet.</p>\n         <p>Only one private IP address can be designated as primary. You can't specify this\n            option if you've specified the option to designate a private IP address as the primary\n            IP address in a network interface specification. You cannot specify this option if\n            you're launching more than one instance in the request.</p>\n         <p>You cannot specify this option and the network interfaces option in the same\n            request.</p>", "smithy.api#xmlName" => "privateIpAddress"}))
    RunInstancesRequest.add_member(:client_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ClientToken', traits: {"aws.protocols#ec2QueryName" => "ClientToken", "smithy.api#documentation" => "<p>Unique, case-sensitive identifier you provide to ensure the idempotency of the\n            request. If you do not specify a client token, a randomly generated token is used for\n            the request to ensure idempotency.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/ec2/latest/devguide/ec2-api-idempotency.html\">Ensuring idempotency in Amazon EC2 API requests</a>.</p>\n         <p>Constraints: Maximum 64 ASCII characters</p>", "smithy.api#idempotencyToken" => {}, "smithy.api#xmlName" => "clientToken"}))
    RunInstancesRequest.add_member(:additional_info, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AdditionalInfo', traits: {"aws.protocols#ec2QueryName" => "AdditionalInfo", "smithy.api#documentation" => "<p>Reserved.</p>", "smithy.api#xmlName" => "additionalInfo"}))
    RunInstancesRequest.add_member(:network_interfaces, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceNetworkInterfaceSpecificationList, location_name: 'NetworkInterfaces', traits: {"aws.protocols#ec2QueryName" => "NetworkInterface", "smithy.api#documentation" => "<p>The network interfaces to associate with the instance.</p>", "smithy.api#xmlName" => "networkInterface"}))
    RunInstancesRequest.add_member(:iam_instance_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: IamInstanceProfileSpecification, location_name: 'IamInstanceProfile', traits: {"aws.protocols#ec2QueryName" => "IamInstanceProfile", "smithy.api#documentation" => "<p>The name or Amazon Resource Name (ARN) of an IAM instance\n            profile.</p>", "smithy.api#xmlName" => "iamInstanceProfile"}))
    RunInstancesRequest.add_member(:ebs_optimized, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EbsOptimized', traits: {"aws.protocols#ec2QueryName" => "EbsOptimized", "smithy.api#documentation" => "<p>Indicates whether the instance is optimized for Amazon EBS I/O. This optimization\n            provides dedicated throughput to Amazon EBS and an optimized configuration stack to\n            provide optimal Amazon EBS I/O performance. This optimization isn't available with all\n            instance types. Additional usage charges apply when using an EBS-optimized\n            instance.</p>\n         <p>Default: <code>false</code>\n         </p>", "smithy.api#xmlName" => "ebsOptimized"}))
