    RunScheduledInstancesRequest.add_member(:instance_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'InstanceCount', traits: {"smithy.api#documentation" => "<p>The number of instances.</p>\n         <p>Default: 1</p>"}))
