    SpotCapacityRebalance.add_member(:replacement_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: ReplacementStrategy, location_name: 'ReplacementStrategy', traits: {"aws.protocols#ec2QueryName" => "ReplacementStrategy", "smithy.api#documentation" => "<p>The replacement strategy to use. Only available for fleets of type\n            <code>maintain</code>.</p>\n         <p>\n            <code>launch</code> - Spot Fleet launches a new replacement Spot Instance when a\n            rebalance notification is emitted for an existing Spot Instance in the fleet. Spot Fleet\n            does not terminate the instances that receive a rebalance notification. You can\n            terminate the old instances, or you can leave them running. You are charged for all\n            instances while they are running. </p>\n         <p>\n            <code>launch-before-terminate</code> - Spot Fleet launches a new replacement Spot\n            Instance when a rebalance notification is emitted for an existing Spot Instance in the\n            fleet, and then, after a delay that you specify (in <code>TerminationDelay</code>),\n            terminates the instances that received a rebalance notification.</p>", "smithy.api#xmlName" => "replacementStrategy"}))
    SpotCapacityRebalance.add_member(:termination_delay, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'TerminationDelay', traits: {"aws.protocols#ec2QueryName" => "TerminationDelay", "smithy.api#documentation" => "<p>The amount of time (in seconds) that Amazon EC2 waits before terminating the old Spot\n            Instance after launching a new replacement Spot Instance.</p>\n         <p>Required when <code>ReplacementStrategy</code> is set to <code>launch-before-terminate</code>.</p>\n         <p>Not valid when <code>ReplacementStrategy</code> is set to <code>launch</code>.</p>\n         <p>Valid values: Minimum value of <code>120</code> seconds. Maximum value of <code>7200</code> seconds.</p>", "smithy.api#xmlName" => "terminationDelay"}))
