    SpotFleetLaunchSpecification.add_member(:block_device_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceMappingList, location_name: 'BlockDeviceMappings', traits: {"aws.protocols#ec2QueryName" => "BlockDeviceMapping", "smithy.api#documentation" => "<p>One or more block devices that are mapped to the Spot Instances. You can't specify both\n            a snapshot ID and an encryption value. This is because only blank volumes can be\n            encrypted on creation. If a snapshot is the basis for a volume, it is not blank and its\n            encryption status is used for the volume encryption status.</p>", "smithy.api#xmlName" => "blockDeviceMapping"}))
    SpotFleetLaunchSpecification.add_member(:ebs_optimized, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EbsOptimized', traits: {"aws.protocols#ec2QueryName" => "EbsOptimized", "smithy.api#documentation" => "<p>Indicates whether the instances are optimized for EBS I/O. This optimization provides dedicated throughput to Amazon EBS and an optimized configuration stack to provide optimal EBS I/O performance. This optimization isn't available with all instance types. Additional usage charges apply when using an EBS Optimized instance.</p>\n         <p>Default: <code>false</code>\n         </p>", "smithy.api#xmlName" => "ebsOptimized"}))
    SpotFleetLaunchSpecification.add_member(:iam_instance_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: IamInstanceProfileSpecification, location_name: 'IamInstanceProfile', traits: {"aws.protocols#ec2QueryName" => "IamInstanceProfile", "smithy.api#documentation" => "<p>The IAM instance profile.</p>", "smithy.api#xmlName" => "iamInstanceProfile"}))
    SpotFleetLaunchSpecification.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ImageId, location_name: 'ImageId', traits: {"aws.protocols#ec2QueryName" => "ImageId", "smithy.api#documentation" => "<p>The ID of the AMI.</p>", "smithy.api#xmlName" => "imageId"}))
    SpotFleetLaunchSpecification.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceType, location_name: 'InstanceType', traits: {"aws.protocols#ec2QueryName" => "InstanceType", "smithy.api#documentation" => "<p>The instance type.</p>", "smithy.api#xmlName" => "instanceType"}))
    SpotFleetLaunchSpecification.add_member(:kernel_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KernelId', traits: {"aws.protocols#ec2QueryName" => "KernelId", "smithy.api#documentation" => "<p>The ID of the kernel.</p>", "smithy.api#xmlName" => "kernelId"}))
    SpotFleetLaunchSpecification.add_member(:key_name, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyPairName, location_name: 'KeyName', traits: {"aws.protocols#ec2QueryName" => "KeyName", "smithy.api#documentation" => "<p>The name of the key pair.</p>", "smithy.api#xmlName" => "keyName"}))
    SpotFleetLaunchSpecification.add_member(:monitoring, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotFleetMonitoring, location_name: 'Monitoring', traits: {"aws.protocols#ec2QueryName" => "Monitoring", "smithy.api#documentation" => "<p>Enable or disable monitoring for the instances.</p>", "smithy.api#xmlName" => "monitoring"}))
    SpotFleetLaunchSpecification.add_member(:network_interfaces, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceNetworkInterfaceSpecificationList, location_name: 'NetworkInterfaces', traits: {"aws.protocols#ec2QueryName" => "NetworkInterfaceSet", "smithy.api#documentation" => "<p>The network interfaces.</p>\n         <note>\n            <p>\n               <code>SpotFleetLaunchSpecification</code> does not support Elastic Fabric Adapter (EFA). \n             You must use <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_LaunchTemplateConfig.html\">LaunchTemplateConfig</a> instead.</p>\n         </note>", "smithy.api#xmlName" => "networkInterfaceSet"}))
    SpotFleetLaunchSpecification.add_member(:placement, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotPlacement, location_name: 'Placement', traits: {"aws.protocols#ec2QueryName" => "Placement", "smithy.api#documentation" => "<p>The placement information.</p>", "smithy.api#xmlName" => "placement"}))
    SpotFleetLaunchSpecification.add_member(:ramdisk_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'RamdiskId', traits: {"aws.protocols#ec2QueryName" => "RamdiskId", "smithy.api#documentation" => "<p>The ID of the RAM disk. Some kernels require additional drivers at launch. Check the kernel \n          requirements for information about whether you need to specify a RAM disk. To find kernel \n          requirements, refer to the Amazon Web Services Resource Center and search for the kernel ID.</p>", "smithy.api#xmlName" => "ramdiskId"}))
    SpotFleetLaunchSpecification.add_member(:spot_price, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SpotPrice', traits: {"aws.protocols#ec2QueryName" => "SpotPrice", "smithy.api#documentation" => "<p>The maximum price per unit hour that you are willing to pay for a Spot Instance. We do not recommend using this parameter because it can lead to \n          increased interruptions. If you do not specify this parameter, you will pay the current Spot price.</p>\n         <important>\n            <p>If you specify a maximum price, your instances will be interrupted more frequently than if you do not specify this parameter.</p>\n         </important>", "smithy.api#xmlName" => "spotPrice"}))
    SpotFleetLaunchSpecification.add_member(:subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetId, location_name: 'SubnetId', traits: {"aws.protocols#ec2QueryName" => "SubnetId", "smithy.api#documentation" => "<p>The IDs of the subnets in which to launch the instances. To specify multiple subnets, separate\n         them using commas; for example, \"subnet-1234abcdeexample1, subnet-0987cdef6example2\".</p>\n         <p>If you specify a network interface, you must specify any subnets as part of the\n         network interface instead of using this parameter.</p>", "smithy.api#xmlName" => "subnetId"}))
    SpotFleetLaunchSpecification.add_member(:user_data, Smithy::Schema::Shapes::ShapeRef.new(shape: SensitiveUserData, location_name: 'UserData', traits: {"aws.protocols#ec2QueryName" => "UserData", "smithy.api#documentation" => "<p>The base64-encoded user data that instances use when starting up. User data is limited to 16 KB.</p>", "smithy.api#xmlName" => "userData"}))
    SpotFleetLaunchSpecification.add_member(:weighted_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'WeightedCapacity', traits: {"aws.protocols#ec2QueryName" => "WeightedCapacity", "smithy.api#documentation" => "<p>The number of units provided by the specified instance type. These are the same units\n        that you chose to set the target capacity in terms of instances, or a performance\n        characteristic such as vCPUs, memory, or I/O.</p>\n         <p>If the target capacity divided by this value is not a whole number, Amazon EC2 rounds the\n        number of instances to the next whole number. If this value is not specified, the default\n        is 1.</p>\n         <note>\n            <p>When specifying weights, the price used in the <code>lowestPrice</code> and\n           <code>priceCapacityOptimized</code> allocation strategies is per\n           <i>unit</i> hour (where the instance price is divided by the specified\n           weight). However, if all the specified weights are above the requested\n           <code>TargetCapacity</code>, resulting in only 1 instance being launched, the price\n           used is per <i>instance</i> hour.</p>\n         </note>", "smithy.api#xmlName" => "weightedCapacity"}))
    SpotFleetLaunchSpecification.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotFleetTagSpecificationList, location_name: 'TagSpecifications', traits: {"aws.protocols#ec2QueryName" => "TagSpecificationSet", "smithy.api#documentation" => "<p>The tags to apply during creation.</p>", "smithy.api#xmlName" => "tagSpecificationSet"}))
    SpotFleetLaunchSpecification.add_member(:instance_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRequirements, location_name: 'InstanceRequirements', traits: {"aws.protocols#ec2QueryName" => "InstanceRequirements", "smithy.api#documentation" => "<p>The attributes for the instance types. When you specify instance attributes, Amazon EC2 will\n         identify instance types with those attributes.</p>\n         <note>\n            <p>If you specify <code>InstanceRequirements</code>, you can't specify\n            <code>InstanceType</code>.</p>\n         </note>", "smithy.api#xmlName" => "instanceRequirements"}))
    SpotFleetLaunchSpecification.add_member(:security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: GroupIdentifierList, location_name: 'SecurityGroups', traits: {"aws.protocols#ec2QueryName" => "GroupSet", "smithy.api#documentation" => "<p>The security groups.</p>\n         <p>If you specify a network interface, you must specify any security groups as part of\n        the network interface instead of using this parameter.</p>", "smithy.api#xmlName" => "groupSet"}))
    SpotFleetLaunchSpecification.type = Types::SpotFleetLaunchSpecification
    SpotFleetMonitoring.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'Enabled', traits: {"aws.protocols#ec2QueryName" => "Enabled", "smithy.api#documentation" => "<p>Enables monitoring for the instance.</p>\n         <p>Default: <code>false</code>\n         </p>", "smithy.api#xmlName" => "enabled"}))
    SpotFleetMonitoring.type = Types::SpotFleetMonitoring
    SpotFleetRequestConfig.add_member(:activity_status, Smithy::Schema::Shapes::ShapeRef.new(shape: ActivityStatus, location_name: 'ActivityStatus', traits: {"aws.protocols#ec2QueryName" => "ActivityStatus", "smithy.api#documentation" => "<p>The progress of the Spot Fleet request. \n          If there is an error, the status is <code>error</code>.\n          After all requests are placed, the status is <code>pending_fulfillment</code>.\n          If the size of the fleet is equal to or greater than its target capacity, the status is <code>fulfilled</code>.\n          If the size of the fleet is decreased, the status is <code>pending_termination</code>\n          while Spot Instances are terminating.</p>", "smithy.api#xmlName" => "activityStatus"}))
    SpotFleetRequestConfig.add_member(:create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: MillisecondDateTime, location_name: 'CreateTime', traits: {"aws.protocols#ec2QueryName" => "CreateTime", "smithy.api#documentation" => "<p>The creation date and time of the request.</p>", "smithy.api#xmlName" => "createTime"}))
    SpotFleetRequestConfig.add_member(:spot_fleet_request_config, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotFleetRequestConfigData, location_name: 'SpotFleetRequestConfig', traits: {"aws.protocols#ec2QueryName" => "SpotFleetRequestConfig", "smithy.api#documentation" => "<p>The configuration of the Spot Fleet request.</p>", "smithy.api#xmlName" => "spotFleetRequestConfig"}))
    SpotFleetRequestConfig.add_member(:spot_fleet_request_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SpotFleetRequestId', traits: {"aws.protocols#ec2QueryName" => "SpotFleetRequestId", "smithy.api#documentation" => "<p>The ID of the Spot Fleet request.</p>", "smithy.api#xmlName" => "spotFleetRequestId"}))
    SpotFleetRequestConfig.add_member(:spot_fleet_request_state, Smithy::Schema::Shapes::ShapeRef.new(shape: BatchState, location_name: 'SpotFleetRequestState', traits: {"aws.protocols#ec2QueryName" => "SpotFleetRequestState", "smithy.api#documentation" => "<p>The state of the Spot Fleet request.</p>", "smithy.api#xmlName" => "spotFleetRequestState"}))
    SpotFleetRequestConfig.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"aws.protocols#ec2QueryName" => "TagSet", "smithy.api#documentation" => "<p>The tags for a Spot Fleet resource.</p>", "smithy.api#xmlName" => "tagSet"}))
    SpotFleetRequestConfig.type = Types::SpotFleetRequestConfig
    SpotFleetRequestConfigData.add_member(:allocation_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: AllocationStrategy, location_name: 'AllocationStrategy', traits: {"aws.protocols#ec2QueryName" => "AllocationStrategy", "smithy.api#documentation" => "<p>The strategy that determines how to allocate the target Spot Instance capacity across the Spot Instance\n            pools specified by the Spot Fleet launch configuration. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/spot-fleet-allocation-strategy.html\">Allocation\n                strategies for Spot Instances</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <dl>\n            <dt>priceCapacityOptimized (recommended)</dt>\n            <dd>\n               <p>Spot Fleet identifies the pools with  \n                   the highest capacity availability for the number of instances that are launching. This means \n                   that we will request Spot Instances from the pools that we believe have the lowest chance of interruption \n                   in the near term. Spot Fleet then requests Spot Instances from the lowest priced of these pools.</p>\n            </dd>\n            <dt>capacityOptimized</dt>\n            <dd>\n               <p>Spot Fleet identifies the pools with  \n                   the highest capacity availability for the number of instances that are launching. This means \n                   that we will request Spot Instances from the pools that we believe have the lowest chance of interruption \n                   in the near term. To give certain\n          instance types a higher chance of launching first, use\n          <code>capacityOptimizedPrioritized</code>. Set a priority for each instance type by\n          using the <code>Priority</code> parameter for <code>LaunchTemplateOverrides</code>. You can\n          assign the same priority to different <code>LaunchTemplateOverrides</code>. EC2 implements\n          the priorities on a best-effort basis, but optimizes for capacity first.\n          <code>capacityOptimizedPrioritized</code> is supported only if your Spot Fleet uses a\n          launch template. Note that if the <code>OnDemandAllocationStrategy</code> is set to\n          <code>prioritized</code>, the same priority is applied when fulfilling On-Demand\n          capacity.</p>\n            </dd>\n            <dt>diversified</dt>\n            <dd>\n               <p>Spot Fleet requests instances from all of the Spot Instance pools that you\n          specify.</p>\n            </dd>\n            <dt>lowestPrice (not recommended)</dt>\n            <dd>\n               <important>\n                  <p>We don't recommend the <code>lowestPrice</code> allocation strategy because\n                     it has the highest risk of interruption for your Spot Instances.</p>\n               </important>\n               <p>Spot Fleet requests instances from the lowest priced Spot Instance pool that has available\n                  capacity. If the lowest priced pool doesn't have available capacity, the Spot Instances\n                  come from the next lowest priced pool that has available capacity. If a pool runs\n                  out of capacity before fulfilling your desired capacity, Spot Fleet will continue to\n                  fulfill your request by drawing from the next lowest priced pool. To ensure that\n                  your desired capacity is met, you might receive Spot Instances from several pools. Because\n                  this strategy only considers instance price and not capacity availability, it\n                  might lead to high interruption rates.</p>\n            </dd>\n         </dl>\n         <p>Default: <code>lowestPrice</code>\n         </p>", "smithy.api#xmlName" => "allocationStrategy"}))
    SpotFleetRequestConfigData.add_member(:on_demand_allocation_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: OnDemandAllocationStrategy, location_name: 'OnDemandAllocationStrategy', traits: {"aws.protocols#ec2QueryName" => "OnDemandAllocationStrategy", "smithy.api#documentation" => "<p>The order of the launch template overrides to use in fulfilling On-Demand capacity. If\n            you specify <code>lowestPrice</code>, Spot Fleet uses price to determine the order, launching\n            the lowest price first. If you specify <code>prioritized</code>, Spot Fleet uses the priority\n            that you assign to each Spot Fleet launch template override, launching the highest priority\n            first. If you do not specify a value, Spot Fleet defaults to <code>lowestPrice</code>.</p>", "smithy.api#xmlName" => "onDemandAllocationStrategy"}))
    SpotFleetRequestConfigData.add_member(:spot_maintenance_strategies, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotMaintenanceStrategies, location_name: 'SpotMaintenanceStrategies', traits: {"aws.protocols#ec2QueryName" => "SpotMaintenanceStrategies", "smithy.api#documentation" => "<p>The strategies for managing your Spot Instances that are at an elevated risk of being\n            interrupted.</p>", "smithy.api#xmlName" => "spotMaintenanceStrategies"}))
    SpotFleetRequestConfigData.add_member(:client_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ClientToken', traits: {"aws.protocols#ec2QueryName" => "ClientToken", "smithy.api#documentation" => "<p>A unique, case-sensitive identifier that you provide to ensure the idempotency of your\n            listings. This helps to avoid duplicate listings. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/Run_Instance_Idempotency.html\">Ensuring Idempotency</a>.</p>", "smithy.api#xmlName" => "clientToken"}))
    SpotFleetRequestConfigData.add_member(:excess_capacity_termination_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: ExcessCapacityTerminationPolicy, location_name: 'ExcessCapacityTerminationPolicy', traits: {"aws.protocols#ec2QueryName" => "ExcessCapacityTerminationPolicy", "smithy.api#documentation" => "<p>Indicates whether running instances should be terminated if you decrease the\n            target capacity of the Spot Fleet request below the current size of the Spot Fleet.</p>\n         <p>Supported only for fleets of type <code>maintain</code>.</p>", "smithy.api#xmlName" => "excessCapacityTerminationPolicy"}))
    SpotFleetRequestConfigData.add_member(:fulfilled_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'FulfilledCapacity', traits: {"aws.protocols#ec2QueryName" => "FulfilledCapacity", "smithy.api#documentation" => "<p>The number of units fulfilled by this request compared to the set target capacity. You\n            cannot set this value.</p>", "smithy.api#xmlName" => "fulfilledCapacity"}))
    SpotFleetRequestConfigData.add_member(:on_demand_fulfilled_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'OnDemandFulfilledCapacity', traits: {"aws.protocols#ec2QueryName" => "OnDemandFulfilledCapacity", "smithy.api#documentation" => "<p>The number of On-Demand units fulfilled by this request compared to the set target\n            On-Demand capacity.</p>", "smithy.api#xmlName" => "onDemandFulfilledCapacity"}))
    SpotFleetRequestConfigData.add_member(:iam_fleet_role, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'IamFleetRole', traits: {"aws.protocols#ec2QueryName" => "IamFleetRole", "smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an Identity and Access Management (IAM) role\n         that grants the Spot Fleet the permission to request, launch, terminate, and tag instances\n         on your behalf. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/spot-fleet-requests.html#spot-fleet-prerequisites\">Spot\n            Fleet prerequisites</a> in the <i>Amazon EC2 User Guide</i>. Spot Fleet can\n         terminate Spot Instances on your behalf when you cancel its Spot Fleet request using <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CancelSpotFleetRequests\">CancelSpotFleetRequests</a> or when the Spot Fleet request expires, if you set\n            <code>TerminateInstancesWithExpiration</code>.</p>", "smithy.api#required" => {}, "smithy.api#xmlName" => "iamFleetRole"}))
    SpotFleetRequestConfigData.add_member(:launch_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchSpecsList, location_name: 'LaunchSpecifications', traits: {"aws.protocols#ec2QueryName" => "LaunchSpecifications", "smithy.api#documentation" => "<p>The launch specifications for the Spot Fleet request. If you specify\n                <code>LaunchSpecifications</code>, you can't specify\n                <code>LaunchTemplateConfigs</code>. If you include On-Demand capacity in your\n            request, you must use <code>LaunchTemplateConfigs</code>.</p>\n         <note>\n            <p>If an AMI specified in a launch specification is deregistered or disabled, no new\n            instances can be launched from the AMI. For fleets of type <code>maintain</code>, the\n            target capacity will not be maintained.</p>\n         </note>", "smithy.api#xmlName" => "launchSpecifications"}))
    SpotFleetRequestConfigData.add_member(:launch_template_configs, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateConfigList, location_name: 'LaunchTemplateConfigs', traits: {"aws.protocols#ec2QueryName" => "LaunchTemplateConfigs", "smithy.api#documentation" => "<p>The launch template and overrides. If you specify <code>LaunchTemplateConfigs</code>,\n            you can't specify <code>LaunchSpecifications</code>. If you include On-Demand capacity\n            in your request, you must use <code>LaunchTemplateConfigs</code>.</p>", "smithy.api#xmlName" => "launchTemplateConfigs"}))
    SpotFleetRequestConfigData.add_member(:spot_price, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SpotPrice', traits: {"aws.protocols#ec2QueryName" => "SpotPrice", "smithy.api#documentation" => "<p>The maximum price per unit hour that you are willing to pay for a Spot Instance. We do not recommend \n            using this parameter because it can lead to increased interruptions. If you do not specify this parameter, you will pay the current Spot price.</p>\n         <important>\n            <p>If you specify a maximum price, your instances will be interrupted more frequently than if you do not specify this parameter.</p>\n         </important>", "smithy.api#xmlName" => "spotPrice"}))
    SpotFleetRequestConfigData.add_member(:target_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'TargetCapacity', traits: {"aws.protocols#ec2QueryName" => "TargetCapacity", "smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The number of units to request for the Spot Fleet. You can choose to set the target\n            capacity in terms of instances or a performance characteristic that is important to your\n            application workload, such as vCPUs, memory, or I/O. If the request type is\n                <code>maintain</code>, you can specify a target capacity of 0 and add capacity\n            later.</p>", "smithy.api#required" => {}, "smithy.api#xmlName" => "targetCapacity"}))
    SpotFleetRequestConfigData.add_member(:on_demand_target_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'OnDemandTargetCapacity', traits: {"aws.protocols#ec2QueryName" => "OnDemandTargetCapacity", "smithy.api#documentation" => "<p>The number of On-Demand units to request. You can choose to set the target capacity in\n            terms of instances or a performance characteristic that is important to your application\n            workload, such as vCPUs, memory, or I/O. If the request type is <code>maintain</code>,\n            you can specify a target capacity of 0 and add capacity later.</p>", "smithy.api#xmlName" => "onDemandTargetCapacity"}))
    SpotFleetRequestConfigData.add_member(:on_demand_max_total_price, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OnDemandMaxTotalPrice', traits: {"aws.protocols#ec2QueryName" => "OnDemandMaxTotalPrice", "smithy.api#documentation" => "<p>The maximum amount per hour for On-Demand Instances that you're willing to pay. You\n            can use the <code>onDemandMaxTotalPrice</code> parameter, the\n                <code>spotMaxTotalPrice</code> parameter, or both parameters to ensure that your\n            fleet cost does not exceed your budget. If you set a maximum price per hour for the\n            On-Demand Instances and Spot Instances in your request, Spot Fleet will launch instances until it reaches the\n            maximum amount you're willing to pay. When the maximum amount you're willing to pay is\n            reached, the fleet stops launching instances even if it hasn’t met the target\n            capacity.</p>\n         <note>\n            <p>If your fleet includes T instances that are configured as <code>unlimited</code>,\n            and if their average CPU usage exceeds the baseline utilization, you will incur a charge\n            for surplus credits. The <code>onDemandMaxTotalPrice</code> does not account for surplus\n            credits, and, if you use surplus credits, your final cost might be higher than what you\n            specified for <code>onDemandMaxTotalPrice</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/burstable-performance-instances-unlimited-mode-concepts.html#unlimited-mode-surplus-credits\">Surplus credits can incur charges</a> in the\n               <i>Amazon EC2 User Guide</i>.</p>\n         </note>", "smithy.api#xmlName" => "onDemandMaxTotalPrice"}))
    SpotFleetRequestConfigData.add_member(:spot_max_total_price, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SpotMaxTotalPrice', traits: {"aws.protocols#ec2QueryName" => "SpotMaxTotalPrice", "smithy.api#documentation" => "<p>The maximum amount per hour for Spot Instances that you're willing to pay. You can use\n         the <code>spotMaxTotalPrice</code> parameter, the <code>onDemandMaxTotalPrice</code>\n         parameter, or both parameters to ensure that your fleet cost does not exceed your budget.\n         If you set a maximum price per hour for the On-Demand Instances and Spot Instances in your request, Spot Fleet will\n         launch instances until it reaches the maximum amount you're willing to pay. When the\n         maximum amount you're willing to pay is reached, the fleet stops launching instances even\n         if it hasn’t met the target capacity.</p>\n         <note>\n            <p>If your fleet includes T instances that are configured as <code>unlimited</code>,\n            and if their average CPU usage exceeds the baseline utilization, you will incur a charge\n            for surplus credits. The <code>spotMaxTotalPrice</code> does not account for surplus\n            credits, and, if you use surplus credits, your final cost might be higher than what you\n            specified for <code>spotMaxTotalPrice</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/burstable-performance-instances-unlimited-mode-concepts.html#unlimited-mode-surplus-credits\">Surplus credits can incur charges</a> in the\n               <i>Amazon EC2 User Guide</i>.</p>\n         </note>", "smithy.api#xmlName" => "spotMaxTotalPrice"}))
    SpotFleetRequestConfigData.add_member(:terminate_instances_with_expiration, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'TerminateInstancesWithExpiration', traits: {"aws.protocols#ec2QueryName" => "TerminateInstancesWithExpiration", "smithy.api#documentation" => "<p>Indicates whether running Spot Instances are terminated when the Spot Fleet request\n            expires.</p>", "smithy.api#xmlName" => "terminateInstancesWithExpiration"}))
    SpotFleetRequestConfigData.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: FleetType, location_name: 'Type', traits: {"aws.protocols#ec2QueryName" => "Type", "smithy.api#documentation" => "<p>The type of request. Indicates whether the Spot Fleet only requests the target\n            capacity or also attempts to maintain it. When this value is <code>request</code>, the\n            Spot Fleet only places the required requests. It does not attempt to replenish Spot\n            Instances if capacity is diminished, nor does it submit requests in alternative Spot\n            pools if capacity is not available. When this value is <code>maintain</code>, the Spot\n            Fleet maintains the target capacity. The Spot Fleet places the required requests to meet\n            capacity and automatically replenishes any interrupted instances. Default:\n                <code>maintain</code>. <code>instant</code> is listed but is not used by Spot\n            Fleet.</p>", "smithy.api#xmlName" => "type"}))
    SpotFleetRequestConfigData.add_member(:valid_from, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'ValidFrom', traits: {"aws.protocols#ec2QueryName" => "ValidFrom", "smithy.api#documentation" => "<p>The start date and time of the request, in UTC format\n                (<i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).\n            By default, Amazon EC2 starts fulfilling the request immediately.</p>", "smithy.api#xmlName" => "validFrom"}))
    SpotFleetRequestConfigData.add_member(:valid_until, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'ValidUntil', traits: {"aws.protocols#ec2QueryName" => "ValidUntil", "smithy.api#documentation" => "<p>The end date and time of the request, in UTC format\n                (<i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).\n            After the end date and time, no new Spot Instance requests are placed or able to fulfill\n            the request. If no value is specified, the Spot Fleet request remains until you cancel\n            it.</p>", "smithy.api#xmlName" => "validUntil"}))
    SpotFleetRequestConfigData.add_member(:replace_unhealthy_instances, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ReplaceUnhealthyInstances', traits: {"aws.protocols#ec2QueryName" => "ReplaceUnhealthyInstances", "smithy.api#documentation" => "<p>Indicates whether Spot Fleet should replace unhealthy instances.</p>", "smithy.api#xmlName" => "replaceUnhealthyInstances"}))
    SpotFleetRequestConfigData.add_member(:instance_interruption_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceInterruptionBehavior, location_name: 'InstanceInterruptionBehavior', traits: {"aws.protocols#ec2QueryName" => "InstanceInterruptionBehavior", "smithy.api#documentation" => "<p>The behavior when a Spot Instance is interrupted. The default is\n                <code>terminate</code>.</p>", "smithy.api#xmlName" => "instanceInterruptionBehavior"}))
    SpotFleetRequestConfigData.add_member(:load_balancers_config, Smithy::Schema::Shapes::ShapeRef.new(shape: LoadBalancersConfig, location_name: 'LoadBalancersConfig', traits: {"aws.protocols#ec2QueryName" => "LoadBalancersConfig", "smithy.api#documentation" => "<p>One or more Classic Load Balancers and target groups to attach to the Spot Fleet\n            request. Spot Fleet registers the running Spot Instances with the specified Classic Load\n            Balancers and target groups.</p>\n         <p>With Network Load Balancers, Spot Fleet cannot register instances that have the\n            following instance types: C1, CC1, CC2, CG1, CG2, CR1, CS1, G1, G2, HI1, HS1, M1, M2,\n            M3, and T1.</p>", "smithy.api#xmlName" => "loadBalancersConfig"}))
    SpotFleetRequestConfigData.add_member(:instance_pools_to_use_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'InstancePoolsToUseCount', traits: {"aws.protocols#ec2QueryName" => "InstancePoolsToUseCount", "smithy.api#documentation" => "<p>The number of Spot pools across which to allocate your target Spot capacity. Valid\n            only when Spot <b>AllocationStrategy</b> is set to\n                <code>lowest-price</code>. Spot Fleet selects the cheapest Spot pools and evenly\n            allocates your target Spot capacity across the number of Spot pools that you\n            specify.</p>\n         <p>Note that Spot Fleet attempts to draw Spot Instances from the number of pools that you specify on a\n            best effort basis. If a pool runs out of Spot capacity before fulfilling your target\n            capacity, Spot Fleet will continue to fulfill your request by drawing from the next cheapest\n            pool. To ensure that your target capacity is met, you might receive Spot Instances from more than\n            the number of pools that you specified. Similarly, if most of the pools have no Spot\n            capacity, you might receive your full target capacity from fewer than the number of\n            pools that you specified.</p>", "smithy.api#xmlName" => "instancePoolsToUseCount"}))
    SpotFleetRequestConfigData.add_member(:context, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Context', traits: {"aws.protocols#ec2QueryName" => "Context", "smithy.api#documentation" => "<p>Reserved.</p>", "smithy.api#xmlName" => "context"}))
    SpotFleetRequestConfigData.add_member(:target_capacity_unit_type, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetCapacityUnitType, location_name: 'TargetCapacityUnitType', traits: {"aws.protocols#ec2QueryName" => "TargetCapacityUnitType", "smithy.api#documentation" => "<p>The unit for the target capacity. You can specify this parameter only when \n         using attribute-based instance type selection.</p>\n         <p>Default: <code>units</code> (the number of instances)</p>", "smithy.api#xmlName" => "targetCapacityUnitType"}))
    SpotFleetRequestConfigData.add_member(:tag_specifications, Smithy::Schema::Shapes::ShapeRef.new(shape: TagSpecificationList, location_name: 'TagSpecifications', traits: {"smithy.api#documentation" => "<p>The key-value pair for tagging the Spot Fleet request on creation. The value for\n                <code>ResourceType</code> must be <code>spot-fleet-request</code>, otherwise the\n            Spot Fleet request fails. To tag instances at launch, specify the tags in the <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-launch-templates.html#create-launch-template\">launch\n                template</a> (valid only if you use <code>LaunchTemplateConfigs</code>) or in\n            the <code>\n               <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_SpotFleetTagSpecification.html\">SpotFleetTagSpecification</a>\n            </code> (valid only if you use\n                <code>LaunchSpecifications</code>). For information about tagging after launch, see\n                <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/Using_Tags.html#tag-resources\">Tag your resources</a>.</p>", "smithy.api#xmlName" => "TagSpecification"}))
