    SpotFleetTagSpecification.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceType, location_name: 'ResourceType', traits: {"aws.protocols#ec2QueryName" => "ResourceType", "smithy.api#documentation" => "<p>The type of resource. Currently, the only resource type that is supported is\n                <code>instance</code>. To tag the Spot Fleet request on creation, use the\n                <code>TagSpecifications</code> parameter in <code>\n               <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_SpotFleetRequestConfigData.html\">SpotFleetRequestConfigData</a>\n            </code>.</p>", "smithy.api#xmlName" => "resourceType"}))
