    SpotInstanceRequest.add_member(:availability_zone_group, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZoneGroup', traits: {"aws.protocols#ec2QueryName" => "AvailabilityZoneGroup", "smithy.api#documentation" => "<p>The Availability Zone group. If you specify the same Availability Zone group for all Spot Instance requests, all Spot Instances are launched in the same Availability Zone.</p>", "smithy.api#xmlName" => "availabilityZoneGroup"}))
    SpotInstanceRequest.add_member(:block_duration_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'BlockDurationMinutes', traits: {"aws.protocols#ec2QueryName" => "BlockDurationMinutes", "smithy.api#documentation" => "<p>Deprecated.</p>", "smithy.api#xmlName" => "blockDurationMinutes"}))
    SpotInstanceRequest.add_member(:create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'CreateTime', traits: {"aws.protocols#ec2QueryName" => "CreateTime", "smithy.api#documentation" => "<p>The date and time when the Spot Instance request was created, in UTC format (for example, <i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).</p>", "smithy.api#xmlName" => "createTime"}))
    SpotInstanceRequest.add_member(:fault, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotInstanceStateFault, location_name: 'Fault', traits: {"aws.protocols#ec2QueryName" => "Fault", "smithy.api#documentation" => "<p>The fault codes for the Spot Instance request, if any.</p>", "smithy.api#xmlName" => "fault"}))
    SpotInstanceRequest.add_member(:instance_id, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceId, location_name: 'InstanceId', traits: {"aws.protocols#ec2QueryName" => "InstanceId", "smithy.api#documentation" => "<p>The instance ID, if an instance has been launched to fulfill the Spot Instance request.</p>", "smithy.api#xmlName" => "instanceId"}))
    SpotInstanceRequest.add_member(:launch_group, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LaunchGroup', traits: {"aws.protocols#ec2QueryName" => "LaunchGroup", "smithy.api#documentation" => "<p>The instance launch group. Launch groups are Spot Instances that launch together and terminate together.</p>", "smithy.api#xmlName" => "launchGroup"}))
    SpotInstanceRequest.add_member(:launch_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchSpecification, location_name: 'LaunchSpecification', traits: {"aws.protocols#ec2QueryName" => "LaunchSpecification", "smithy.api#documentation" => "<p>Additional information for launching instances.</p>", "smithy.api#xmlName" => "launchSpecification"}))
    SpotInstanceRequest.add_member(:launched_availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LaunchedAvailabilityZone', traits: {"aws.protocols#ec2QueryName" => "LaunchedAvailabilityZone", "smithy.api#documentation" => "<p>The Availability Zone in which the request is launched.</p>\n         <p>Either <code>launchedAvailabilityZone</code> or <code>launchedAvailabilityZoneId</code> can be specified, but not both</p>", "smithy.api#xmlName" => "launchedAvailabilityZone"}))
    SpotInstanceRequest.add_member(:launched_availability_zone_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LaunchedAvailabilityZoneId', traits: {"aws.protocols#ec2QueryName" => "LaunchedAvailabilityZoneId", "smithy.api#documentation" => "<p>The ID of the Availability Zone in which the request is launched.</p>\n         <p>Either <code>launchedAvailabilityZone</code> or <code>launchedAvailabilityZoneId</code> can be specified, but not both</p>", "smithy.api#xmlName" => "launchedAvailabilityZoneId"}))
    SpotInstanceRequest.add_member(:product_description, Smithy::Schema::Shapes::ShapeRef.new(shape: RIProductDescription, location_name: 'ProductDescription', traits: {"aws.protocols#ec2QueryName" => "ProductDescription", "smithy.api#documentation" => "<p>The product description associated with the Spot Instance.</p>", "smithy.api#xmlName" => "productDescription"}))
    SpotInstanceRequest.add_member(:spot_instance_request_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SpotInstanceRequestId', traits: {"aws.protocols#ec2QueryName" => "SpotInstanceRequestId", "smithy.api#documentation" => "<p>The ID of the Spot Instance request.</p>", "smithy.api#xmlName" => "spotInstanceRequestId"}))
    SpotInstanceRequest.add_member(:spot_price, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SpotPrice', traits: {"aws.protocols#ec2QueryName" => "SpotPrice", "smithy.api#documentation" => "<p>The maximum price per unit hour that you are willing to pay for a Spot Instance. We do not recommend \n            using this parameter because it can lead to increased interruptions. If you do not specify this parameter, you will pay the current Spot price.</p>\n         <important>\n            <p>If you specify a maximum price, your instances will be interrupted more frequently than if you do not specify this parameter.</p>\n         </important>", "smithy.api#xmlName" => "spotPrice"}))
    SpotInstanceRequest.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotInstanceState, location_name: 'State', traits: {"aws.protocols#ec2QueryName" => "State", "smithy.api#documentation" => "<p>The state of the Spot Instance request. Spot request status information helps track your Spot\n            Instance requests. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/spot-request-status.html\">Spot request status</a> in the\n                <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "state"}))
    SpotInstanceRequest.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotInstanceStatus, location_name: 'Status', traits: {"aws.protocols#ec2QueryName" => "Status", "smithy.api#documentation" => "<p>The status code and status message describing the Spot Instance request.</p>", "smithy.api#xmlName" => "status"}))
    SpotInstanceRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"aws.protocols#ec2QueryName" => "TagSet", "smithy.api#documentation" => "<p>Any tags assigned to the resource.</p>", "smithy.api#xmlName" => "tagSet"}))
    SpotInstanceRequest.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotInstanceType, location_name: 'Type', traits: {"aws.protocols#ec2QueryName" => "Type", "smithy.api#documentation" => "<p>The Spot Instance request type.</p>", "smithy.api#xmlName" => "type"}))
    SpotInstanceRequest.add_member(:valid_from, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'ValidFrom', traits: {"aws.protocols#ec2QueryName" => "ValidFrom", "smithy.api#documentation" => "<p>The start date of the request, in UTC format (for example,\n                <i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).\n            The request becomes active at this date and time.</p>", "smithy.api#xmlName" => "validFrom"}))
    SpotInstanceRequest.add_member(:valid_until, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'ValidUntil', traits: {"aws.protocols#ec2QueryName" => "ValidUntil", "smithy.api#documentation" => "<p>The end date of the request, in UTC format\n                (<i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).</p>\n         <ul>\n            <li>\n               <p>For a persistent request, the request remains active until the <code>validUntil</code> date\n                    and time is reached. Otherwise, the request remains active until you cancel it.\n                </p>\n            </li>\n            <li>\n               <p>For a one-time request, the request remains active until all instances launch,\n                    the request is canceled, or the <code>validUntil</code> date and time is reached. By default, the\n                    request is valid for 7 days from the date the request was created.</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "validUntil"}))
    SpotInstanceRequest.add_member(:instance_interruption_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceInterruptionBehavior, location_name: 'InstanceInterruptionBehavior', traits: {"aws.protocols#ec2QueryName" => "InstanceInterruptionBehavior", "smithy.api#documentation" => "<p>The behavior when a Spot Instance is interrupted.</p>", "smithy.api#xmlName" => "instanceInterruptionBehavior"}))
