    SpotInstanceStatus.add_member(:code, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Code', traits: {"aws.protocols#ec2QueryName" => "Code", "smithy.api#documentation" => "<p>The status code. For a list of status codes, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/spot-request-status.html#spot-instance-request-status-understand\">Spot request status codes</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#xmlName" => "code"}))
    SpotInstanceStatus.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Message', traits: {"aws.protocols#ec2QueryName" => "Message", "smithy.api#documentation" => "<p>The description for the status code.</p>", "smithy.api#xmlName" => "message"}))
    SpotInstanceStatus.add_member(:update_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'UpdateTime', traits: {"aws.protocols#ec2QueryName" => "UpdateTime", "smithy.api#documentation" => "<p>The date and time of the most recent status update, in UTC format (for example,\n                <i>YYYY</i>-<i>MM</i>-<i>DD</i>T<i>HH</i>:<i>MM</i>:<i>SS</i>Z).</p>", "smithy.api#xmlName" => "updateTime"}))
