    SpotPlacementScore.add_member(:region, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Region', traits: {"aws.protocols#ec2QueryName" => "Region", "smithy.api#documentation" => "<p>The Region.</p>", "smithy.api#xmlName" => "region"}))
    SpotPlacementScore.add_member(:availability_zone_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZoneId', traits: {"aws.protocols#ec2QueryName" => "AvailabilityZoneId", "smithy.api#documentation" => "<p>The Availability Zone.</p>", "smithy.api#xmlName" => "availabilityZoneId"}))
    SpotPlacementScore.add_member(:score, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Score', traits: {"aws.protocols#ec2QueryName" => "Score", "smithy.api#documentation" => "<p>The placement score, on a scale from <code>1</code> to <code>10</code>. A score of\n            <code>10</code> indicates that your Spot request is highly likely to succeed in this\n         Region or Availability Zone. A score of <code>1</code> indicates that your Spot request is\n         not likely to succeed. </p>", "smithy.api#xmlName" => "score"}))
