    VpcBlockPublicAccessOptions.add_member(:managed_by, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedBy, location_name: 'ManagedBy', traits: {"aws.protocols#ec2QueryName" => "ManagedBy", "smithy.api#documentation" => "<p>The entity that manages the state of VPC BPA. Possible values include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>account</code> - The state is managed by the account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>declarative-policy</code> - The state is managed by a declarative policy\n                    and can't be modified by the account.</p>\n            </li>\n         </ul>", "smithy.api#xmlName" => "managedBy"}))
    VpcBlockPublicAccessOptions.add_member(:exclusions_allowed, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcBlockPublicAccessExclusionsAllowed, location_name: 'ExclusionsAllowed', traits: {"aws.protocols#ec2QueryName" => "ExclusionsAllowed", "smithy.api#documentation" => "<p>Determines if exclusions are allowed. If you have <a href=\"https://docs.aws.amazon.com/vpc/latest/userguide/security-vpc-bpa.html#security-vpc-bpa-exclusions-orgs\">enabled VPC BPA at the Organization level</a>, exclusions may be\n                <code>not-allowed</code>. Otherwise, they are <code>allowed</code>.</p>", "smithy.api#xmlName" => "exclusionsAllowed"}))
