    VpnTunnelOptionsSpecification.add_member(:startup_action, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StartupAction', traits: {"smithy.api#documentation" => "<p>The action to take when the establishing the tunnel for the VPN connection. By\n            default, your customer gateway device must initiate the IKE negotiation and bring up the\n            tunnel. Specify <code>start</code> for Amazon Web Services to initiate the IKE\n            negotiation.</p>\n         <p>Valid Values: <code>add</code> | <code>start</code>\n         </p>\n         <p>Default: <code>add</code>\n         </p>"}))
